window.PB_TEXTS=window.PB_TEXTS||{};window.PB_TEXTS["PB-552B25917CA26951"]={"schemaVersion": 1, "documentId": "PB-552B25917CA26951", "title": "Det Lysande Sällskapet Jönköpings Par Bricole 125 år (2004)", "sourceSha256": "552b25917ca2695102397ad4b17ca210f8f72da5c21dd9fafa57c486d4bb1df1", "method": "Poppler pdftotext -layout; existing PDF text layer; no new OCR", "extractedAt": "2026-10-05T13:28:03.101015+00:00", "pages": [{"pdfPage": 1, "printedPage": null, "text": "", "ocrText": "", "ocrSegments": [""], "autoTextLayer": "original", "machineAssessment": {"confidence": 0.0, "needsReview": true, "automaticSplit": false, "engine": "Tesseract 5.5.3; LSTM; psm 3", "version": "batch-v2", "sourceSha256": "552b25917ca2695102397ad4b17ca210f8f72da5c21dd9fafa57c486d4bb1df1", "modelHashes": {"Fraktur": "29a867a25f1b00a5e9827356582515619d5102688bc1d14015789c78941116ee", "swe": "360303308aa5d4a912ac3b3637691152b7532d9bd6e960639db1affb83db7ea9"}, "languages": ["swe"], "selection": "confidence-and-coverage-heuristic; not proofreading", "createdAt": "2026-10-05T14:09:54.297594+00:00", "statisticsParser": "tsv-quote-none-v1; prior row counts checked"}}, {"pdfPage": 2, "printedPage": null, "text": "Det Lysande Sällskapet\nJönköpings Par Bricole\n       125 år"}, {"pdfPage": 3, "printedPage": null, "text": "Ansvarig utgivare:    Dan Ekström\nText:                 Jönköpings Par Bricole\nBild:                 Jönköpings Par Bricole, Jönköpings läns Museum, Jönköpings-Posten\nRedaktionskommitté:   Eric Haglund, Ragnar Jonsell, Harald Wigstrand, Gunnar Åkerskog\nTryck:                Tabergs Tryckeri 2004"}, {"pdfPage": 4, "printedPage": null, "text": "SÄLLSKAPETS HÖGE BESKYDDARE\n\n\n\n\n   H.M. KONUNG CARL XVI GUSTAF"}, {"pdfPage": 5, "printedPage": null, "text": "Innehållsförteckning\n\n                                                                                                                              Sid\n\nFörord ....................................................................................................................     6\nSällskapets historia ................................................................................................           9\n    De första femtio åren .........................................................................................             9\n    De senaste femtio åren ....................................................................................... 28\n\n\nTre Jönköpingsbricollister .................................................................................... 47\n    Johan Axel Stedt ................................................................................................ 47\n    Gustaf Lorentz ................................................................................................... 48\n    Knut-Erik Jahnke ............................................................................................... 49\n\n\nDokument över gångna tider ................................................................................. 52\n    De Gyllene Böckerna ......................................................................................... 52\n    Avisa - En tidning i tre akter .............................................................................. 53\n    Sällskapets handlingar ...................................................................................... 64\n\n\nSällskapets rum och salar ...................................................................................... 65\n    Stora Hotellet ..................................................................................................... 66\n    ”Stadshuset” ...................................................................................................... 68\n    Kansli med Bellmanssal och Barbarasalong ..................................................... 70\n\n\n\n\n4"}, {"pdfPage": 6, "printedPage": null, "text": "Sid\nSällskapets rekvisita och inventarier ..................................................................... 75\n\n\nSällskapets Talanggrupper ..................................................................................... 84\n   Den Bacchanaliska Kören ................................................................................. 84\n   Den Bacchanaliska Musiken ............................................................................. 99\n   Den Bacchanaliska Teatern ............................................................................... 107\n   Jönköpings Bacchanaliska Akademi för Skalde- och Talekonst ........................ 124\n   Den Bacchanaliska Måltidsakademin Luculli Gille .......................................... 131\n\n\nSällskapets andra aktiviteter .................................................................................. 140\n\n\nTvå publika evenemang på 1990-talet ................................................................... 143\n   Magnus Ladulås 700 år - ett historiskt skådespel från tiden\n   för Jönköpings grundande ................................................................................. 143\n   Operamaskeradbalen ......................................................................................... 147\n\n\nSällskapets Styrande Mästare ................................................................................ 156\n\n\nSällskapets vedermälen ......................................................................................... 166\n\n\nTabula Gratulatoria ................................................................................................ 170\n\n\n\n\n                                                                                                                           5"}, {"pdfPage": 7, "printedPage": null, "text": "Förord\nEtthundratjugofem år är en avsevärd tidsrymd. En tidsrymd fylld av händelser, utveck-\nling och förändring. Många är de brev, protokoll, årsberättelser, tal och skrifter m.m.,\nsom under årens lopp producerats och blivit ett minnesmärke över just den tid, då orden\nsattes på pränt. Det finns således mycket att förmedla nutidens och framtidens Bricole-\nbröder från den tid som varit. Vår dåtid. Bokens artiklar beskriver olika händelser och\nspeglar skilda tidsepoker inom det Lysande Sällskapet Jönköpings Par Bricole under de\ngångna åren. Sällskapet har tidigare utgivit en jubileumsskrift vid femtioårsjubileet år\n1929.\n    Det Styrande Guvernementet gav under 2003 Jönköpings Bacchanaliska Akademi i\nuppdrag att ta fram en minnesbok till Sällskapets 125-årsjubileum i november 2004.\nInom Akademin utsågs en särskild redaktionskommitté bestående av Harald Wigstrand,\nRagnar Jonsell, Gunnar Åkerskog samt Eric Haglund. Kommittén involverade ett antal\nsärskilt erfarne och talangfulle Bröder som författare av olika avsnitt. Dessa var Sty-\nrande Mästaren Dan Ekström, Riddareintendenten emeritus Ulf Larsson, Arbetsgradernas\nOrdförande Bernt Lindqvist, Ordföranden för Den Bacchanaliska Musiken Tommy\nÖberg, Ordensantikvarien Bo E Karlsson samt Praeses emeritus i Luculli Gille Ingemar\nBoman.\n    Flera äldre och minnesgoda Bröder medverkade med erfarenheter från det\nbricollistiska livet inom vårt Sällskap. Av dessa vill vi särskilt framhålla Ordensarkivarien\noch Jubelkommendören - tillika Directeuren emeritus för Den Bacchanaliska Teatern -\nBror Nätt, Teaterbrodern Rolf von Otter, Förste Riddarordningsmannen emeritus Lars\nLöfstedt samt Jubelkommendörerna Arne Hallin och Lennart Sjöblom.\n    I boken finns ett antal äldre och yngre fotografier. Dessa har hämtats från Sällska-\npets arkiv och fotografen är i de allra flesta fall okänd. I de fall fotografen är känd finns\nhans namn angivet på sedvanligt sätt. En del kompletterande bilder har tagits av\nOrdens-conterfejaren Erik Svensson. Äldre pappersfotografier kan numera överföras\ntill en digital bild. Detta arbete har huvudsakligen gjorts av Folkrörelsearkivet, Brodern\nLars Löfstedt, Rosen Foto & Ur, Huskvarna och Tryckopia AB.\n\n\n\n\n6"}, {"pdfPage": 8, "printedPage": null, "text": "Många Bröder har vidare stöttat arbetet med jubileumsboken genom direkta ekono-\nmiska bidrag. Deras namn finns angivna på särskilt plats i boken.\n   Redaktionskommittén vill framföra ett varmt tack till alla de, som - på många skilda\nsätt - medverkat till förverkligandet av denna Jubileumsbok, Det Lysande Sällskapet\nJönköpings Par Bricole 125 år.\n\nJönköping i november 2004\n\n\nDan Ekström                            Eric Haglund\nStyrande Mästare                       Praeses\n                                      Jönköpings Bacchanaliska Akademi\n\n\nRagnar Jonsell                         Harald Wigstrand\nStändig sekreterare                    Ordensbibliotekarie\nJönköpings Bacchanaliska Akademi\n\n\nGunnar Åkerskog\nOrdens Talare och Skald\n\n\n\n\n                                                                                      7"}, {"pdfPage": 9, "printedPage": null, "text": "8"}, {"pdfPage": 10, "printedPage": null, "text": "Sällskapets historia\nDe första femtio åren\nBildandet\nDet Bacchanaliska ljuset upptändes i Jönköping år 1879. Två till staden inflyttade män\nhade skådat det Bacchanaliska ljuset i Borås Par Bricole och man kan förmoda att\nherrarna vid besök i någon av stadens finare salonger talade mycket om ordensliv och\nom Par Bricole i synnerhet. Vad som sades vet vi naturligtvis inte, men man kan för-\nmoda att det talades om Borås Par Bricole och om hur lång, smal och krånglig vägen\nvar dit. Vägen gick inte som nu över Ulricehamn utan man fick företa sig en betydligt\nlängre resa upp mot Skaraborgstrakterna för att med häst och vagn komma till Borås.\nDetta var säkert en av orsakerna till att man förde på tal att det borde bildas ett bricolleri\ni Jönköping, en stad som vid den tiden beboddes av cirka 8000 invånare. I högtidstalet\nvid Jönköpings Par Bricoles 25-årsjubileum den 17 april 1904 talade Jonas Karling om\nbildandet:\n   ”Förhållandet var så, att vid den tid, då jag inflyttade till Jönköping, fanns här en\npostmästare vid namn Paul Billing, vilken liksom jag förut bott i Borås, där vi båda\nskådat det Bacchanaliska ljuset och efter vars värmande strålar vi båda kände samma\nlängtan, vilken ej lämnade oss ro förrän vi genom en annons, under vilken postmästaren\nmed av rörelse darrande hand tecknade sitt namn, inbjudit de för saken intresserade till\nett sammanträde på Stadshuset eller den lokal, som nu (1904) innehas av källaremästaren\nLundholm, med den påföljd att ett 50-tal av stadens ledande män samlades, och gläd-\njande att säga befunno sig bland dessa ytterligare trenne Bricollbröder, nämligen\nGuvernören Carl Lars Svante Friedländer, vice Guvernören Carl Lyth och Över-\nkommendören Oscar Weidenhielm”.\n   Det möte, som Karling och Billing kallat till,\nhölls den 2 februari 1879. Det 50-tal av stadens\nledande män, som hade läst annonsen och blivit\nintresserade av idén om att försöka starta en\nfilialloge i Jönköping, utsåg denna afton en kom-\nmitté, som fick i uppdrag att ta kontakt med\nModerlogen i Stockholm. Kommittén bestod av\nCarl Friedländer (Göta Par Bricole), Paul Billing\noch Jonas Karling (Borås Par Bricole) samt av\nrådmannen Gustaf Grapengiesser och apoteka-\nren Carl Falk. Samtidigt beslöt man att trygga\nekonomin genom att bilda en ekonomisk garan-\ntifond, eller som det hette då ”en fond för\nundanröjande av ekonomiska svårigheter”. 39\nstycken av de närvarande herrarna satsade 25\n\n\n                                                                                             9"}, {"pdfPage": 11, "printedPage": null, "text": "kronor var i garantifonden, ett belopp som väl motsvarar en dryg månadslön för en\ntjänsteman idag. Jönköpings Par Bricoles ekonomiska startkapital var alltså 975 kro-\nnor, som 1879 var en ganska stor summa pengar. På garantifondens lista hittar man\nbland initiativtagarnas namn också den dynamiske tändsticksdisponenten Bernhard Hay,\nsom blev vårt Sällskaps andre Styrande Mästare.\n    Moderlogen svarade snabbt på skrivelsen från Jönköping. Redan i slutet av februari\nsamma år fick man ett svar som löd:\n    ”Vi Styrande Mästare och samtlige Ledamöter av Stora Konseljen inom Det\nLysande Sällskapet Par Bricole tillbjude alla dem, som detta vårt Öppna Brev se eller\nhöra, vår kärvänliga hälsning med glädje och gamman! Som flere i Staden Jönköping\nboende medlemmar av Sällskapet Par Bricole hos oss, såsom Styresmän för den\näldsta och ursprungliga Moderlogen av nämnda Sällskap, tillkännagivet sin önskan att\nfå inom nämnda stad anlägga och öppna en Brikolleri-loge med all den glans denna\nOrden fordrar, för att förena det nyttiga med det angenäma samt åt sig och andra bereda\ntillfälle till muntra och anständiga nöjen, alltså hava vi härigenom och i kraft av detta\nvårt Öppna Brev velat tillåta, såsom vi nu och förordna, det må i staden Jönköping en\nloge för Sällskapet Par Bricole öppnas under namn av Jönköpings PAR BRICOLE,\nägande denna loge att till befrämjande av Ordning, Munterhet, Styrka och Förtrolighet\nsamt i enlighet med de stadgar och ritualer, som varda till denna loge överlämnade,\nantaga och med sig förena Nitiske och i Vingården Arbetande Kommendörer, Klare och\nBefallande Överkommendörer samt Oförgängligt Skinande och Durchseende Bröder,\nävensom att utnämna och antaga Högt Durchseende och Högt Oförgänglige Vice\nGuvernörer, att nyttja och bruka denna Ordens prydnader och insegel samt att alltid\noch allestädes såsom en i sann och rättmätig ordning tillkommen Brikolleri-loge aktas\noch anses. Under Broderlig tillönskan av all framgång och trevnad hava vi, å Stora\nKonseljens vägnar, detta Stiftelsebrev med våra namns egenhändiga underskrift och\nmed Ordens stora signét bekräftat, vilket skedde i Stockholm den tjugondefemte dagen\ni februari månad av år Ett Tusen Åttahundra och på det Sjuttionionde”.\n\nP.O.BÄCKSTRÖM                    C.J.HALLIN.                J.O.SUNDELL.\nStormästare                         Dep. Mästare              Stor-Kansler.\n(sigill)\n                                                             J.E.Wahlström\n                                                             Storsekreterare\n   Jönköpings Par Bricole fick alltså från början befogenhet från Moderlogen att ge de\nFem Första Graderna. Samtidigt som Stiftelsebrevet kom till Jönköping, anlände också\nDet Styrande Guvernementets förordnande. I detta sades att Den Högst Durchseende\noch Högst Oförgänglige Brodern Friedländer anförtrotts att vara den blivande logens\nOrdförande Mästare, som det kallades på den tiden. Numera är benämningen Styrande\nMästare. Bröderna i kommittén kontaktade omedelbart logen i Borås och fick därifrån\nde värdefulla anvisningarna om den rekvisita som behövdes för att genomföra\narbetsgraderna. Dessutom kom från Borås handskrivna kopior av ordenssångerna medan\n\n10"}, {"pdfPage": 12, "printedPage": null, "text": "ritualerna kom från Moderlogen. Vi kanske skall påminna oss om att alla avskrifter var\nhandskrivna och inte som nu kopierade genom snabb modern teknik. Alla handlingar\nsom förutsatte gradgivning i Arbetsgraderna, våra fyra första grader, hade kommit till\nJönköping inom ramen av sex veckor, vilket talar om ett stort intresse både från Moder-\nlogen och från Borås Par Bricole. Man kan förmoda att ”smygavskrifter” redan fanns i\nJönköping eftersom vice Häradshövdingen Olof Emil Lindegren under denna\nsexveckorsperiod repeterade de sånger och de ceremonier som skulle användas vid den\nofficiella Gradgivningen. Detta står att läsa i den skrift som utgavs vid Jönköpings Par\nBricoles 50-års jubileum.\n    Den 2 februari 1879 hade, som tidigare sagts, ett femtiotal män av stadens societet\nsamlats i Stadshuset för bildandet av Jönköpings Par Bricole. Den 14 april samma år\nantecknar vi som Sällskapets födelsedag. Då samlades man nämligen i Spegelsalen på\nStora Hotellet för att ge den Första Graden. Men innan detta kunde ske måste Styrande\nMästaren Carl Friedländer utnämna och förordna Guvernement och Ämbetsmän,\nvilket skedde samma dag. Till Deputerad Styrande Mästare utsågs Oscar Weidenhielm,\ntill Styrande Kansler Paul Billing, till Protonotarie Gustaf Grapengiesser, till Providör\nF.A. Holmström och till Ordens Kantor Olof Emil Lindegren. Samtliga upphöjdes till\nvice Guvernörer (Femte Graden). Paul Billing var med vid givandet av Graden efter-\nsom han redan hade Sällskapets Första Riddaregrad (Sjätte Graden).\n    En intressant iakttagelse är hur få ämbeten, som vid tiden för vårt bildande ansågs\nbehövas vid Gradgivningen. Tre Styrande, Protonotarie, Providör och Ordens Kantor,\ndet var allt. Man kan säga att tiderna har förändrats inom vårt Lysande Sällskap\nJönköpings Par Bricole. Vid den Första Graden den 14 april antogs 53 nya Bröder, av\nvilka 8 dekorerades utan reception. Varför dessa åtta lyfts ut från den övriga receptionen\nvet vi inte, men det är troligt, att de fanns med som ämbetsmän vid Gradgivningen. Det\nfinns inga protokoll om detta. Redan 14 dagar därefter, närmare bestämt den 2 maj, var\nman beredd att ge den Andra Graden. 34 Bröder recipierades. Samtidigt tog man in\n6 nya medlemmar.\n    Kammarreception är alltså inget nytt och redan den 2 maj 1879 kammarrecipierades\nsex Bröder direkt till Andra Graden. Den 26 juli firade man Bellmandagen och upptog\n14 nya medlemmar (utan reception). Högtidstalet hölls av borgmästare Axel\nPrintzensköld. Man noterade för övrigt att det just detta år var 50 år sedan bysten av\nCarl Michael Bellman invigts på Djurgården (1829) i närvaro av vår förste Bernadotte\nCarl XIV Johan och Bellmans hustru Lovisa, som överlevde Bellman med över 50 år.\n    Under födelseåret 1879 genomförde Jönköpings Par Bricole ytterligare fem sam-\nmanträden. Den Tredje Graden gavs den 14 november. 22 Bröder recipierades och bland\ndem den originelle industrimannen, Munksjö Pappersbruks chef K. O. (Ottonin)\nLjungquist, ett namn som han lär ha fått eftersom han var det nionde barnet i familjen\noch det åttonde hade dött. Han är förmodligen en av få i Sverige som ligger begravd på\nsin arbetsplats. Hans grav finns en bit från disponentvillan på anrika Munksjö pappers-\nbruk i Jönköping.\n    Jönköpings Par Bricoles första Barbaradag firades den 6 december 1879. Då antogs\n\n                                                                                       11"}, {"pdfPage": 13, "printedPage": null, "text": "20 nya Bröder i Sällskapet, bland dem\n                                              stationsskrivaren Olle Blank som skulle\n                                              komma att betyda mycket för teaterns verk-\n                                              samhet.\n                                                 Den 13 april 1880, ganska exakt ett år\n                                              efter stiftandet, gavs för första gången Den\n                                              Fjärde Graden. 16 Bröder upphöjdes.\n                                                 Värt att notera från tiden omkring\n                                              det första verksamhetsåret är sammanträ-\n                                              det den 14 maj 1880. Då firade ”PAR\n                                              BRICOLE Allmänt” Sofiadagen, efter Olof\n                                              Kexéls beteckning ”Ordens-Instiftelse-\n                                              dag”, till ära för Kexéls väninna opera-\n                                              dansösen Sophie Holmstedt. Denna bri-\n                                              collistiska högtidsdag föll ur bruk i Jönkö-\n                                              ping redan under 1800-talet. Vid Sofia-\n                                              dagen den 14 maj 1880 valdes ämbetsmän\n                                              för nästkommande arbetsår. Sällskapet\n                                              fick sin förste Intendent vid detta tillfälle,\nLudvig Wahlin, som var teckningslärare vid tekniska yrkesskolan i Jönköping.\n   Vid det första arbetsårets slut i maj 1880 hade Jönköpings Par Bricole 126 ledamö-\nter. På Barbaradagen 1880 gavs den Femte Graden för första gången till nio Bröder.\nFöljande Barbara, 1881, höll borgmästaren Axel Printzensköld Barbaratalet på vers.\nDet ansågs vara ett av de friskaste som hållits bland Par Bricoles orationer. I talet får\nman veta ganska mycket om hur livet var i Jönköping och i vårt Sällskap vid denna tid.\nVi återger några strofer;\n\n     ”Än ett solvarv har förrunnit av Brikolleriets liv\n     under festligt glada samkväm, utan käbbel eller kiv,\n     då i vimlet runt omkring oss på varandra hopat sig\n     val- och bal- och kransskandaler, tidningsgräl och tändstickskrig.\n\n     Sådant har ej rört vårt gille, där allt gått sin gamla trall.\n     Minsta tratt som guvernören aldrig sviktat i sitt kall,\n     och fast sången i tenoren numer klingar något svag,\n     gör den dock som förr sitt bästa, liksom på min lyra jag.\n\n     Här bär glädjen högt sin fana, fritt den viftar uti skyn\n     och den fyllda bålen prunkar, liksom kyrkan, mitt i byn,\n     infall, skämt och löjen fladdra liksom gyllne bin omkring\n     och om de än svida, såra dock aldrig deras sting.\n\n\n12"}, {"pdfPage": 14, "printedPage": null, "text": "Första tryckta matrikeln i Jönköpings Par Bricole år 1881.\n\n\n\n\n   Må vi då i botten tömma jublande en festpokal\n   för allt stort och varmt, som blixtrar fram utur vår ritual,\n   för vart levnadslustigt upptåg, varje infall gott och glatt,\n   för det harmlöst vassa skämtet och för vart godmodigt spratt”.\n\n   Boråsaren Jonas Karling avgick som Ceremonimästare redan den 15 maj 1882 och\nersattes av Inspektör Edgar Strehlenert, men Karling inträdde i sitt ämbete igen redan\n1883. Orsaken till detta har inte gått att utreda, men en trolig anledning är att ingenjör\nKarling ville öppna vägen för en kollega. Det verkar dock som om den nye Ceremoni-\nmästaren inte höll den klass man hade hoppats eftersom han inte nämns igen i dessa\nsammanhang. Den 15 maj 1883 finner man för första gången en teaterdirektör bland\nämbetsmännen. Den förste direktören hette Axel Ekelund. Man värnade tidigt om sången\noch musiken och även om våra protokoll innehåller ganska litet om just Den\nBacchanaliska Musiken kan vi konstatera att man redan den 27 oktober 1883 recipierade\n11 Bröder från musiken i Den Tredje Graden, bland dem den nyvalde teaterdirektören\nEkelund. Den 19 april 1884 invaldes presidenten för Göta Hovrätt, O. W. Stael von\nHolstein i Sällskapet. En annan betydelsefull person som anslöt sig samma år var\n\n\n                                                                                       13"}, {"pdfPage": 15, "printedPage": null, "text": "redaktören Rud. Björkman. Han intogs i Sällskapet den 27 juli 1884 mot förbindelsen\natt recipieras på tändstickschefens egendom Björneberg utanför Jönköping, dit\nBröderna hade inbjudits för att fira Bellmans minne. Vid Barbarafesten samma år hög-\ntidstalade Jonas Karling. Det var året då Oscar II hade ”gjort” Jönköping och jagat\nfasan på Visingsö och Karling hade i sitt Barbaratal på vers berättat om hur Moster\nBarbara hade infunnit sig i Jönköping vid denna tid. Naturligtvis hade hon beviljat\nSällskapets Ceremonimästare (Karling) en intervju och i den konstaterat ”den utom-\nordentliga effekt, som bricolleriets införande i Jönköping hade medfört”, vilket också\nhade ingivit henne tanken, som hon förut bestämt hävdat, att det var fullständigt\nlönlöst att göra folk (bricollister) av kalmucker. Det är i alla fall från Barbaratalet 1884\nvi hittar Jonas Karlings klassiska uttryck:\n\n     ”Kalmucken är rudis på allting, som hör\n     till mänskliga edukationen.\n     Han duger ej förrän han blir kommendör\n     och undergått har receptionen.\n     Men då kan det hända man finner ibland\n     rätt bra exemplar från kalmuckernas land”.\n\n                                                   Ett annat datum väl värt att notera är\n                                               den 16 december 1884. Då gavs för första\n                                               gången Den Första Riddaregraden i Jön-\n                                               köping. Det var 17 Bröder som upphöjdes\n                                               till S:t Sigfrids Riddare, vår nuvarande\n                                               Sjätte Grad.\n                                                   Följande år, den 15 mars 1885, fick lek-\n                                               tor Carl Oskar von Porat Den Sjätte Gra-\n                                               den. Han var lärare vid läroverket och blev\n                                               en av logens förgrundsmän och kanske en\n                                               av vårt Sällskaps allra främsta vältalare.\n                                               Han höll talet vid Gradgivningen och lov-\n                                               sjöng bricolleriet med bl.a. följande:\n\n\n\n                                               Överallt i våra dagar\n                                               knotar man och ängsligt klagar:\n                                               ”Livets visa går i moll”.\n                                               Men om herrar pessimister\n                                               bara blevo Bricollister,\n                                               snart de sågo inga brister.\n                                               Ty de ses ej i Bricole.\n\n14"}, {"pdfPage": 16, "printedPage": null, "text": "En och var blev icke givet\n   under vandringen i livet\n   spela stolt en huvudroll.\n   Här dock gå vi magnifike,\n   uppå band och stjärnor rike,\n   och i glans finns knappt vår like\n   när vi mötas i Bricole.\n\n   Mången har, när bokslut göres\n   och hans livsvinst överföres,\n   i behållning kanske noll.\n   Men här får han millioner\n   ljusa, glada - illusioner,\n   som vid upptåg, tal och toner\n   vingen lyfta i Bricole.\n\n   Upptåg, tokerier, vittra tal och tonernas sköna musik utgjorde den gemensamma\nnämnaren för Jönköpings Par Bricole den första tiden. Förmodligen är detta en av de\nbidragande orsakerna till att vi idag kan skriva en jubileumsbok om Sällskapets 125\nåriga historia. Det är lätt att förstå, när man läser om hur det var då, att ”pojklynnet”\nbland stadens societet spred sig och att många ville uppleva Par Bricoles unika gemen-\nskap. Visst fanns det ordensliv och annan gemenskap i Jönköping, men Karling och\nBilling, som hade upplevt det bricollistiska ljuset i Borås, visste nog vad stadens\nledande män saknade. De var förmodligen ganska övertygade om att den unika\nbricollistiska gemenskapen skulle samla det bästa och det främsta av vältalighet till ett\nuppsluppet och efter kultur hungrande Jönköping. Teatern kom tidigt att sätta sin prägel\npå Jönköpings Par Bricole. Redan den 15 maj 1885 utnämndes Olle Blank till teater-\ndirektör och om denne fantastiske teaterdirektör med artistnamnet Jean Gautier kan\nman läsa mer i kapitlet om Den Bacchanaliska Teatern.\n   Den 16 maj 1886 är en milstolpe i Jönköpings Par Bricoles historia. Då gavs för\nförsta gången Den Sjunde Graden i Jönköping. När Graden gavs hade två Bröder från\nGöta Par Bricole kommit för att biträda vid Gradgivningen. 16 Bröder recipierades i\nSpegelsalen. Samma dag gavs den Åttonde Graden (förmodligen för första gången)\noch Bröderna som upphöjdes var Bernhard Hay, Paul Billing, Jonas Karling och Carl\nFalk. Efter Gradgivningen var det måltidskalas där man uppläste ett svarstelegram från\nKonung Oscar II. Den första parentationen omtalas i ett protokoll från den 10 novem-\nber 1885. Det var apotekare Carl Falk som parenterade sex bortgångna Bröder.\n   När Jönköpings Par Bricole firade sin tioåriga födelsedag konstaterades att man\nsedan bildandet haft 90 sammanträden och hade vid 1889 års början 314 med-\nlemmar, av vilka 87 Bröder var Riddare (Sjätte och Sjunde Graden).\n\n\n\n\n                                                                                      15"}, {"pdfPage": 17, "printedPage": null, "text": "Kristider i början\nPar Bricole har startats på några platser i Sverige där verksamheten inte längre finns\nkvar, t ex i Karlskrona. Det verkar som om all nyetablering ofta följs av några års\nbekymmer. De flesta Logerna kan vittna om detta i sin historieskrivning. Missmodet\ndrabbade också Bröderna i Jönköping och det verkar som om detta infann sig redan\nföre tioårsfesten. Protonotarien klagar i en skrivelse strax innan tioårsfesten att ”endast\n46 Bröder voro närvarande vid en 4:e grads givande, och i april 1890 funnos inga\nrecipiender alls vid ett allmänt PAR BRICOLE” Det var så nedslående att vice Härads-\nhövding Arvid Cronholm enligt protokollet ”anmälde ledsnad över Par Bricoles tynande\nlivsverksamhet” och föreslog att en uppryckningskommitté skulle bildas. En sådan\nkonstituerades också och i denna insattes ”den ledsne” samt den glade stationsskrivaren\noch teaterdirektören Olle Blank. Kommittén skulle komma med förslag på vad man\nkunde göra för att väcka intresset igen. Redan efter några veckor upplästes kommitténs\nutlåtande och det antogs nya tjänstemän i enligt med deras förslag. Vad som stod\ni utlåtandet och vad tjänstemannaförslaget gick ut på vet vi inte, men man kan läsa i\nsamma års Barbaratal att ”den ledsne” d v s Cronholm hade fått en framstående funk-\ntion som Ceremonimästare. Barbaratalaren skriver:\n\n”Jag minnes ock att han blev vald till C. M,\nmen sedan dess jag inte har sett te’en...”\n\n   Redan när denna spydighet levererades hade dock Ceremonimästarens uppgifter över-\ntagits av ingenjör Alvar Muntzing. Barbaratalet hölls av ingenjör Gustaf Engström,\nsom inte skräder orden när han går till räfst och rättarting med Bröderna. Som nästan\nalla Barbaratalare sade han sig haft förmånen av ett personligt sammanträffande med\ndet illustra fruntimret och hon hade varit rätt skarp i tonen mot Jönköpingsbricolleriet.\n\n     ”Du dåre, sade hon med rösten bruten,\n     hur vågar du att mana fram min bild idag?\n     Jag tycker gärna du kan hålla truten!\n     Jag finner mer ej nöje uti edert lag;\n     där split och tvedräkt högt sin spira föra,\n     har inte jag ett enda dugg att göra”\n\n   Det förefaller som om Moster Barbara tyckte att man hållit för få sammankomster.\nVidare klagar hon på slitningar som tycks ha varit av politisk art. När man tänker på de\nmän som var med vid bildandet och åren därefter kan man kanske förstå att det gick\nganska hett till. Jönköpings Par Bricole bestod på den tiden av de starkaste och in-\nflytelserikaste männen i samhället. Det var brukspatroner och ledande industrimän,\nhäradshövdingar och självaste landshövdingen, hovrättspresidenten och andra ledande\ntjänstemän i stadens olika förvaltningar, alla män i det högsta samhällsskiktet. Det var\ndessa som i bästa Broderlighet skulle forma det bricollistiska Ljuset i den nystartade\n\n16"}, {"pdfPage": 18, "printedPage": null, "text": "Vari磁•Tea`119\n\n\n\n                                              咄血磁瓜•\n\n\n\n\n                       ba田 fM山a唸•\n\n\n\n\numde•f 和1血紐krame1111'leo.              •\n      Ing匹 V•占 U磁0沖·\n珈血•                                           心1 珈•函3\nS沖•~     h•••e                       ~\n\n                            krop四呼叫•               •血 d血叩ptddande',6m\n                      h•“ぷ匹叩四•nu                                    oeb — i 血し\n\n                 till•FJlgiao•\n\n\n\n\n                                       ,—\n,..•仕伍 O{md血oa\n\n\n\n\n                                                                   oauti•r\n\n\n                           Teateraffisch i P.B, 27 oktober 1885.\n\n\n                                                                                 17"}, {"pdfPage": 19, "printedPage": null, "text": "logen. Det gick ju inte så bra av vad vi förstår av Barbaratalaren Engström, som fort-\nsätter sin kritik:\n\n     ”I forna dar jag dröjde här så gärna\n     då skämtet sprudlade i yster dans,\n     då alltid klar hon lyste, P.B:s stjärna,\n     då Par Brikoll stod än i all sin glans,\n     då Brodern ”Jonas” ännu C. M. klubban förde\n     och ”mine Bröders” hurrarop man hörde.\n\n     Sedan kom en tid med strider, split och tvister,\n     som trängde ock till P.B:s lugna härd,\n     då frihandlare och protektionister\n     av alla krafter rörde upp en värld.\n     Då börjar mina Bröders iver mattas\n     och P.B av kalmucker att utskrattas”.\n\nI slutet av talet får dock Styrande Mästaren Friedländer en kärvänlig hälsning av\nMoster. Det får också teaterdirektören Janne (Harald Theodor Uddén), som hon tycker\nsköter sig alldeles utmärkt. Man kan säga att det trots allt andas en viss tillförsikt inför\nframtiden. Även Henrik Karnell, som då började uppträda på vers, hyste tilltro till\nkommande dagar även om situationen i Par Bricole kändes mörk just då. Trots Moster\nBarbaras brandtal och uppmaning till uppryckning blev följande år lika slött som tidi-\ngare. En gång i maj 1891 fick man på ett ”PAR BRICOLE allmänt” dra sig fram med\nett provisoriskt Guvernement. När man samlades i oktober fanns det inga recipiender\noch bara 20-talet Bröder närvarande. Ett svaghetstecken var väl också att inga hyll-\nningar till Moster Barbara förekom. Man försökte få Bröderna att skriva något genom\natt utlysa en tävling om det bästa Barbaratalet. Trots detta så visade det sig att ”ingen\nkänt sig manad” varför Jonas Karling tog sig för att orera på Barbaradagen, något som\nhan gjorde med den äran enligt protokollet. Karling berättade att han låtit sig\n”hypnotiseras av Brikollbrodern och medikusen Frans Edvard Velander och fick i detta\ntillstånd göra ett besök i Bacchi stora tempelsal. Där vilade Moster Barbara på en\nunderskön bädd av violer och camelior, medan det under hennes fötter porlade en\nrubinröd bäck av skummande vin och hulda genier fyllde gnistrande pokaler med\nädlaste nektar”. Den audienssökande gjorde som gammal Ceremonimästare tecknet\noch gumman tryckte då en puss på Jonas kind. Det är väl knappast nödvändigt att\ntillägga att hon därefter inte var särskild mild i omdömet om Jönköpings Par Bricole.\nHon påtalade att ”arbetsgradernas leder hade glesnat” och hon trodde att felet låg i\n”en sjuklig tid” och ”i brist på verklig vänskap”. Kanske hade också pelaren Ordning\nfått sig en ordentlig törn. Moster manade till tyglad glädje och sann vänskap och fällde\ntill avslutning några skämtsamma ord. Hon tyckte det skulle vara roligt om Ceremoni-\nmästaren (Alvar Muntzing) någon enda gång kunde skämta och att ”hin skulle heta\n\n18"}, {"pdfPage": 20, "printedPage": null, "text": "..—―＾ー さ\n                                  ~-\n          Självporträtt av H.T. Uddén i ”Kludderier av Sudden”, troligen från 1870.\n                                             Foto: Jönköpings läns museums arkiv.\n\n\nWahlin och vara permanent intendent”. Sånganföraren Olle Lindegren hade ”förtjänt\nsin Literis, men brikollsångarna lite ris”. Sedan sporde hon om Olle Blank (teater-\ndirektören) vänt ”blankan” (ryggen) åt Par Bricole.\n\nVändningen\nVändningen skedde när Sällskapet firade sin 20-åriga tillvaro 1899. Vår förste\nStyrande Mästare Carl Friedländer lade på grund av ålder och ohälsa ner sitt Höga\nÄmbete och ersattes av den dynamiske tändstickschefen Bernhard Hay. Lektorn vid\nläroverket Per Brahe C. O. von Porat, blev Deputerad Styrande Mästare och till\nStyrande Kansler utsågs hovrättsassessorn August Th. Meyer. Han avled dock innan\nhan tillträtt sitt ämbete och som ny Kansler installerades disponent Karl Hård af\nSegerstad. 20 år hade gått och Bröderna hade delat många glada och bricollistiska\nstunder, men tiden hade varit prövosam och många gånger var det nog nära att man\nfunderade allvarligt på att lägga ner verksamheten i Jönköping. Det bricollistiska\nLjuset vid Vätterns Södra Strand hade dock kommit för att stanna. Det har brunnit\ni styrka och glans i 125 år när denna Jubileumsbok skrivs. De första 20 åren bars fram\nav många starka viljor och av många sångare, musikanter och teaterbröder. Till-\nsammans med ceremoniel och Styrande ska dessa tillskrivas ett stort tack för denna\nderas gärning. Man brukar inte framhålla någon person i sådana här sammanhang,\n\n                                                                                      19"}, {"pdfPage": 21, "printedPage": null, "text": "eftersom det är de många som gjort det tillsammans i gemenskap och samförstånd.\nFrågan är dock om Jönköpings Par Bricole hade kunnat fira sina 125 år i år om inte\nBoråsaren Jonas Karlings okuvliga bricollistiska målmedvetenhet hade hållit samman\ngemenskapen under de första 20 åren.\n\nJönköpings Par Bricole 20 år\nNär Jönköpings Par Bricole firade sin 20-åriga tillvaro kunde man läsa följande i\nSmålands Allehanda:\n   ”Tvenne tiotal av år ha i vinter förrunnit sedan å stadshuset bildades för Jönköping\nen dotterloge av det högt lysande sällskapet PAR BRICOLE. En värdig minnessten på\nden lyckosamma 20-åriga vägen satte Sällskapet genom en anslående fest, som den 30\napril var arrangerad i Stora Hotellets festvåning. Festen hade ock en annan och större\nanledning än den ovannämnda, nämligen den att vara ett uttryck för ordensbröders\ndjupt kända tacksamhet mot den man, som allt sedan logens tillkomst varit dess ledare\noch alltid vetat att under alla förhållanden föra dess runor med den äran och upprätt-\nhålla de goda traditioner, som sedan ett århundrade tillbaka gjort PAR BRICOLE:s\nnamn känt och välkänt. Denne man är bruksägare Carl Friedländer. Och att den hyll-\nning, som ägnades honom, var lika odelad som oskrymtad, kände i sitt sinne envar av\nde närvarande. Sedan sjunde graden i sluten loge utdelats till ett tiotal riddare, samlades\nfestdeltagarna till gemensam middag i stora salen, som dagen till ära var dekorerad\nmed grönt och med riddarebrödernas sköldar. På ena långväggen mitt framför hedersgäst-\nens plats var uppsatt herr Friedländers porträtt i helfigur, målat i olja i naturlig storlek\nav artisten V. Holmgren från Stockholm. Under hurtig sång intågade Bröderna med\nsångarna i spetsen i festsalen och snart sutto de bänkade i ro och gamman kring det\nstora hästskoformade bordet. Redan från första stund gjorde sig den angenäma stäm-\nningen rådande, vartill i sin mån bidrog dels den präktiga taffelmusik, som utfördes av\nAndra Göta Artilleriregementes musikkår, dels att gång efter annan fulltonig sång\nklingade genom salen. Då middagen fortgått en stund, äskade disponenten Hay, som\nfrån detta års ingång bekläder ordförandeskapet, ljud och utbringade konungens skål,\nvilken åtföljdes av folksången, hurrarop och fanfarer. Nästa skål gällde hedersgästen\noch föreslogs även den av disponenten Hay, som i ett av varmaste känslor präglat tal\nframförde Brödernas tack till hr Friedländer för allt vad han under de gångna 20 åren\nverkat såsom den sammanhållande och framdrivande kraften inom Jönköpingslogen.\n”Och därför att vi i dig se en värdig Par Bricole-broder” yttrade talaren, ”en som bör för\noss stå som en förebild, är det som vi låtit måla det porträtt, som du nu ser framför dig\noch vid vilket vid våra kommande samkväm skall pryda ordenssalen. Men även vi å vår\nsida hava velat bliva bevarade i ditt minne och hågkomst, varför vi samlat våra porträtt\ni detta album, som jag härmed har äran att överlämna”. Talaren slutade med att höja sitt\nglas för hedersgästen, varpå skålen dracks under jubel, hurrarop, fanfarer och sång.\nOmedelbart efter det sången tystnat vände sig ordföranden ånyo till hr Friedländer,\ndenna gång på moderlogens i Stockholms vägnar, och överlämnade till hr Friedländer\nordens högsta utmärkelser, insignierna till Tionde graden, R. S. K. samt jubel-\n\n20"}, {"pdfPage": 22, "printedPage": null, "text": "kommendörstecknet. Nya hurrarop, fanfarer och sång. (Vår nuvarande Nionde Grad\ninstiftades först år 1925 vilket förklarar att RSK omnämns som den högsta Tionde gra-\nden år 1899. Red:s anm.) I ett fyndigt tal, där lekande skämt och djupaste allvar med\nverklig mästarhand blandades om vartannat, tackade hedersgästen för den hyllning som\nbrödraskapet ägnat honom. Han hade härför mycket att tacka de män som inom orden\nstått honom närmast och när han nedlade sin befattning hade det skett i den fullaste\növertygelse, att han till efterträdare fått en man, som efter allas mening vore fullt vuxen\nsin uppgift och med känd energi kommer att ägna sig åt densamma. Återigen reste sig\nordföranden och överlämnade efter ett kort tal å moderlogens vägnar RGK gradens\ninsignier till lektor Carl Oskar von Porat, ingenjör Jonas Karling och sparbankskassör\nLudvig Wahlin. Härefter beträddes talarstolen av Ordens Ceremonimästare ingenjör\nJonas Karling, som i ett längre anförande tecknade Jönköpings PAR BRICOLE: s\nhistoria. Den glada middagen fick liksom allt annat roligt sitt slut, men ännu i ett\npar timmar fortsatte samkvämet i de till stora salen gränsande rummen under tal och\nsång. I Par Bricoles annaler - slutar Smålands Allehanda sitt referat - skall länge den 30\napril 1899 intaga ett bemärkt rum och festdeltagarna skola i den minnas en av de\nangenämaste dagar de njutit inom det högt lysande sällskapet, vilket otaliga gånger\nförut samlat dem till glada fester, där skämtet spelat vid sidan av allvarsfulla förhand-\nlingar, sången ljudit och där de materiella njutningarna alltid varit och äro av mer\nunderordnad betydelse”.\n\nNågra märkesår i vår tidigaste historia\n”Tiderna ha växlat, förluster och missräkningar har skiftat med glada förhoppningar.\nGautier sänder inte längre ut sina brokiga affischer och Jannes gröna lykta har slock-\nnat”. Så inledde Jonas Karling sitt tal vid Sällskapets 20-årsdag och fortsatte påminna\nom att minnet av många klingande skratt fyller hjärtat med vemod men att detta inte får\nhindra oss att fortsätta vår vandring med sång och harmoni i hjärtat och på tungan till\nglädje och gamman för oss och för alla de Bröder vi ha omkring oss både på höjd och i\ndal. Den andra stora perioden i Jönköpings Par Bricole började med det nya seklet, den\nperiod under vilken Bernhard Hay förde spiran. Logen var på tydlig uppgång och miss-\nmodets ande var bortdriven av en ljusare uppfattning om framtiden. Ernst L. Hartmann,\nen blivande Styrande Mästare, upptogs för första gången som ämbetsman och blev\nProvidör. Vid samma tillfälle utsågs ytterligare en blivande Styrande Mästare till äm-\nbetsman, nämligen Henrik Karnell som blev teaterdirektör.\n   Redan 1901 blev Henrik Karnell Ceremonimästare. Protokollen från den här tiden\ntalar om ett livligt intresse för Par Bricole och många nya Bröder anslöt sig till Sällska-\npet. Befordringarna och omsättningen inom graderna gick raskt. Det var således under\nen vänlig stjärna som Sällskapet år 1904 i april beredde sig på att fira sitt 25-års jubi-\nleum. Bernhard Hay författade själv ritualen för högtidslogen och med sin lite petiga\nmen tydliga handstil gav han klara besked om hur det skulle vara: ”efter middagen tåga\nBröderna in i samlingssalongen med angränsande rum, der starkt, hett och godt kaffe\nmed tillbehör af konjak och likörer jemte cigarrer serveras. Under samqvämet efter\n\n                                                                                        21"}, {"pdfPage": 23, "printedPage": null, "text": "middagen skall tillhandahållas pounsch i wår silverbål, konjak, whisky och watten jemte\ncigarrer, så att allt finnes tillräckligt och ingenting fattas”. Till festligheten sände Moder-\nlogen tre Deputerade. Förmodligen var det inte Stormästarna utan representanter för\ndessa. Vidare fanns representanter från Göteborg, Borås och Malmö här. En av Sällska-\npets stiftare, postmästare Paul Billing, som då var 88 år, var inbjuden som hedersgäst.\nHan tackade för inbjudan i ett skämtsamt brev där han betygade sin ”hänförelse för det\nlysande Bricolleriet” och tackade nej på grund av ålder och kroppslig skröplighet.\nHögtidslogen var förlagd till nuvarande Rådhuset och den sal som kallades för Solenni-\ntetssal under den tid läroverket fanns i huset. Sångarna sjöng en festkantat med ord av\nHenrik Karnell och högtidstalet hölls av Riddareceremonimästare Jonas Karling. Han\nskildrade Jönköpings Par Bricoles uppkomst och historia och vem visste bättre än\nKarling. Det är intressant att ta del av Karlings beskrivning av teater och sång under vår\nförsta tid. Han konstaterar skillnader i den anständiga munterheten som under tidens\nlopp kännetecknat Bricolleriet. ”Den burleska parodien, som i början fröjdade oss av-\nlöstes av cirkusimitationer och menageriföreställningar under Axel Ekelunds och Olle\n\n\n\n\nValhallasalen i nuvarande Rådhuset omkring 1920. Salen är iordningställd för en Gradgivning i\nPar Bricole. Salen, som senare byggts om till flera lokaler, användes ofta för konstutställning.\nFoto: Rylanderska fotosamlingen, S Ljung Jönköpings läns museum.\n\n\n22"}, {"pdfPage": 24, "printedPage": null, "text": "Blanks klangdagar, då däremot Janne Uddén förnöjde oss med uppskattade skådespel\noch vågade skuggspel, under det Hampus Holm genom karaktärsmålningar och effekt-\nfulla tablåer sökte giva innehåll åt glädjen och sålunda bildade en övergång till de rea-\nlistiska konstnjutningar, som Tor Almén förstår att genom användandet av den nya\ntidens uppfinningar på optikens och akustikens områden framlocka till Brödernas för-\nnöjelse och beundran”. Även sångarna fick sin hyllning i Karlings tal när han vände sig\ntill dem och sade: ”Sången är bricolleriets pulserande liv, den friska girland som\nsammanflätar och sirar dess fyra pelare. Det är den som bidragit till att under de nu\ngångna 25 åren hålla vårt PAR BRICOLE livskraftigt. Må därför I, som haven sångens\ntoner i edra strupar, sjunga in mandom, heder och godhet i våra hjärtan, mod och kraft\nåt oss och alla Bröder.” Efter högtidslogen gick samtliga Bröder till Viktor Rydbergs\nbyst som på den tiden var placerad längs Västra Storgatan. Bernhard Hay höll ett kort\ntal till minnet av den store ”skalden och tänkaren som brikollist”. Sångarna sjöng ”Vårt\nland” och ”Hör oss Svea”. Många åskådare var närvarade vid denna ceremoni.\n    Måltidskalaset ägde rum i Spegelsalen som var prydd med Konung Oscars byst,\nsamt det stora porträttet av Friedländer. Bellmans byst fanns också med och salen var\nkringgärdad av lagerträd och palmer. Musikdirektör Josef A Jacobsson hade kompone-\nrat och tillägnat Jönköpings Par Bricole en festmarsch och den spelades när Bröderna\ntågade in i den rikt belysta salen. Kalaset blev högtidligt och festligt.\n\nBernard Hay slutar som Styrande\nMästare\nDen 1 september 1906 lämnade Bernhard\nHay sitt ämbete som Styrande Mästare på\ngrund av ålder och försvagad hälsa. Han\nefterträddes av Major Bror von Geijer. Gei-\njer hade överflyttats från Moderlogen till\nJönköping 1904 och hade alltså bara varit\nmed i Jönköping i två år när han blev Sty-\nrande Mästare. Förmodligen blev det en\nganska besvärlig situation för Geijer. Det\när beklagligt att arkivhandlingarna från\ndenna tid i stort sett är obefintliga. Många\nav de tal som hölls vid den här tiden, hade\nkanske kunnat bringa vetskap om vad som\nhände, men det finns inga. Dessutom är\nprotokollen mycket knapphändiga och inne-\nhåller bara kortfattade notiser om intag-\nningar eller befordringar. Det är alltså\nganska märkligt att det inte finns ett enda\nord skrivet om en så pass viktig händelse\n\n\n                                                                                      23"}, {"pdfPage": 25, "printedPage": null, "text": "som major Geijers avgång som Styrande Mästare. Han lämnade sitt ämbete i september\n1909 och ersattes av dåvarande Deputerad Styrande Mästare, hovrättsrådet Henrik Wrede,\nsom för övrigt var gift med Bernhard Hays dotter. Det mesta av intresse från protokol-\nlen från denna tid är namn på Bröder som senare har spelat väsentliga roller i vårt\nSällskap. En av dessa var apotekare Carl Gustaf Roos af Hjelmsäter som så småningom\nblev en mycket uppskattad Ceremoni- och Humormästare. En annan betydande bricollist\nhittar man i ett protokoll den 25 januari 1908. Då planterades den blivande Styrande\nMästaren Gösta Pantzerhielm in i vingården och den 30 januari 1909 togs vår förste\nOrdförande i Arbetsgraderna in i Sällskapet. Det var civilingenjör Wilhelm Graneli.\nHenrik Karnell inträdde samma år som Riddareprelat.\n\n\nNy nedgångsperiod\nVid 25-års jubileet stod Jönköpings Par Bricole i sitt fulla flor, men när Bernhard Hay\nlämnade som Styrande Mästare började tydligen en avmattning att göra sig gällande.\nBåde under Bror von Geijers och under Henrik Wredes ledartid talades om ett ”alltmer\nslappnande intresse”. Detta var också en trend man märkte inom andra Ordenssällskap.\nSammankomsterna besöktes ytterst sparsamt och det blev allt svårare att rekrytera nya\nmedlemmar. Man gick med ljus och lykta för att leta recipiender och det var inte ovan-\nligt att man recipierade endast en person i Den Första Graden. Detta skedde vid flera\ntillfällen under åren 1910-1912. Vid ett tillfälle i Första Riddaregraden (Sjätte Graden)\nhölls parentation över sju Bröder. Logen besöktes vid det tillfället förutom av De\nStyrande och Ämbetsmännen endast av en enda Broder. Vid Gåsakalaset efter Logen\ndeltog - fyra Bröder! Det diskuterades då att lägga ned Sällskapets arbete under ett eller\nett par år. Somliga tyckte att Par Bricole var föråldrat och efterblivet i förhållande till\ntidsutvecklingen. Andra menade att sången inte klingade som förr i tempelsalen. De\nsom fortfarande var intresserade hade det både motigt och besvärligt och inte minst var\narbetet otacksamt. En januarikväll 1911 gavs en varietéafton på vilken Bröderna hade\nlagt ner ett otroligt repetitionsarbete. Vid framförandet infann sig endast 24 Bröder.\nVisserligen ökades antalet något fram på nattkröken, när några middagar, supéer och\ndanstillställningar hade slutat på stan.\n    Teatergruppen lät sig dock inte nedslås utan arbetade glatt och troget året därpå i tron\natt Bröderna då skulle infinna sig. Tyvärr blev resultatet ännu sämre och det var nog\ninte långt ifrån att samtliga medlemmar av teatertruppen tappat modet för gott. För-\nutom det sorgliga faktum att publiken svek, så slocknade också det elektriska ljuset.\nEfter en halvtimma kunde spelet börja på nytt, men ett milt raseri hade då kommit över\nsamtliga aktörer och den ene efter den andre kom av sig. Man kan ana sig till\nTeaterdirektörens tankar och känslor.\n    Det ljusnade omsider och så småningom började Sällskapet rycka upp sig ur sin\nförsoffning och sången började åter klinga under Ordenskantor Josef A Jacobssons\nsäkra ledning. Visserligen pågick det första världskriget men man lyckades ändå hålla\nigång en relativt livaktig verksamhet på Stora Hotellet. Den 28 oktober 1916 hade man\n\n\n24"}, {"pdfPage": 26, "printedPage": null, "text": "t ex 14 recipiender till Fjärde Graden och 1917 intogs eller uppflyttades 23 Bröder i de\ntre första graderna.\n\nMedaljhistoria\nDen 27 januari 1917 var en bemärkelsedag på flera sätt. Då utdelades för första gången\n25-års tecknet (Hederskommendör) till ett stort antal Bröder i Jönköping. För första\ngången utdelades också Jönköpings Par Bricoles Förtjänstkors. De första Bröder som\nerhöll Förtjänstkorset var Styrande Mästaren, friherre Henrik Wrede, kapten Frans Olof\nAsk, bankkamrer Per Magnus Hultquist, kassör Carl Ludvig Wahlin, direktör Henrik\nValfrid Karnell, tandläkare Axel Jonsson, apotekare C G Roos af Hjelmsäter och bank-\ntjänsteman Oscar Millqvist. Vid detta sammanträde recipierades inte mindre än 24 nya\nBröder. År 1917 utdelades också Jönköpings Par Bricoles Eklöfskrans för första gången.\nDet var Ordens Kantor och körledare, Musikunderlöjtnant Josef Jacobsson som förära-\ndes denna uppskattning. Förtjänstkorset gavs på den tiden endast till Bröder i Styrande-\nkretsen eller till andra med hög ämbetsfunktion. Eklöfskransen kunde ges som ett bevis\npå De Styrandes uppskattning.\n\nNy glansperiod\nDen 28 februari 1917 nedlade helt oförmodat friherre Wrede sitt ämbete som Styrande\nMästare. Samtidigt avflyttade Deputerad Styrande Mästare kapten Ask från Jönköping\noch Sällskapet stod plötsligt utan Styrande Guvernement. Likväl gav man den Sjunde\nGraden den 13 maj under Direktör Henrik Karnells ledning. Karnell var då Riddare-\nprelat och genomförde enligt protokollet ”ett ståtligt sammanträde”. Därmed kan man\nsäga att man satte punkt för ett skede i Jönköping som medfört mycken glädje men\nockså stora bekymmer och mycken besvikelse. Man stod nu inför en ny epok, en ny\nglansperiod som kanske saknar motstycke i Sällskapets historia. Den 2 oktober 1917\nsamlades ett 20-tal Bröder till ett sammanträde på Stora Hotellet för att diskutera den\nkris som hade uppstått och sannolikt skulle Jönköpings Par Bricoles saga ha varit all\nom man låtit missmodet ta överhand den gången. Först gällde det att skaffa ett nytt\nGuvernement, vilket visade sig vara ganska svårt eftersom den ene efter den andre\ntackade nej. Man kan förmoda att ingen var villig att ta tag i den svåra situation som\nrådde. Det krävdes både mod och styrka. Slutligen kom man dock fram till ett resultat\nsom hälsades med stor tillfredställelse av samtliga Bröder. Till Styrande Mästare valdes\ndirektör Ernst L Hartmann, till Deputerad Styrande Mästare disponent Oscar Roempke\noch till Styrande Kansler direktör Henrik Karnell.\n   Arbetet började med beslutsamhet. Det blev fart på rekryteringen av nya medlemmar\noch medlemstalet ökade i takt med Sällskapets muntra och anständiga tidsfördriv. De\nStyrande skötte sina bricollistiska plikter entusiastiskt och samvetsgrant och inte minst\nRoos af Hjelmsäter utvecklade ceremonielet med en humorfylld elegans som man inte\ntidigare hade sett. Trots krigsårens stränga ransonering av ”det synliga fluidum” levde\nden Bacchanaliska glädjen frisk. Detta talar för att ”det osynliga fluidum” spelar en\nminst lika viktig roll inom bricolleriet, om inte större. Vältaligheten och poesin var\n\n                                                                                      25"}, {"pdfPage": 27, "printedPage": null, "text": "Spegelsalen vid Barbaradag på 1910-talet. Salen är dekorerad med Par Bricoles vapensköldar och\nen orkester spelar på musikbalkongen. Salen hade ommålats i mörkare ton år 1903 och då tillkom\nden nuvarande takmålningen av Vilhelm Holmgren. Fotot kan vara det äldsta bevarade, som visar\nen av Par Bricoles högtidligheter. Foto: Jönköpings läns museum.\n\n\nkanske i början inte så lysande, men Moster Barbara hyllades på regelbundna tider och\nkvinnan fick överhuvud taget sin skyldiga tribut av oratoriska hyllningar. Styrande\nMästarens ”Klang Bacchi Barn” hade som oftast festivitas över sitt utrop och även om\nbålen led av restriktionssjukan uttömdes enligt traditionen både pokaler och floribussar\nenligt ceremonin. Parentationerna vid Sjätte Graden samlade många Bröder och både\nGåsen och Våren hyllades med ökad värme och fler deltagare. Det blev något glatt och\nintimt över bricollerikalasen.\n   På Barbaradagen den 8 december 1917 installerades det nya Guvernementet av Den\nHögst Upplyste Brodern C O von Porat. Det var ett av von Porats sista bricollistiska\nuppdrag och den reslige och ståtlige koryfén från vårt bricolleris första dagar\npresiderade med grandessa. 120 Bröder närvarade vid högtiden då fyra Guvernörer\ndubbades och 24 nya Bröder togs in i Första Graden. von Porat och Jonas Karling erhöll\nFörtjänstkorset och tre Bröder blev Hederskommendörer. Redan i februari 1918 antogs\nytterligare 24 nya Bröder och Logen bevistades då av 170 Bröder. Den 16 mars reci-\npierades inte mindre än 32 Bröder i Fjärde Graden. I februari 1919 gav teatern ett\nspex som bevistades av 150 Bröder. Dagen efter gav man samma spex för damerna.\nDet var trångt i lokalen och man kan nog påstå att det hade skett en del sedan spexet\n1911 då man spelade för 24 Bröder. Man samlades också ganska ofta i sammanhang\n\n26"}, {"pdfPage": 28, "printedPage": null, "text": "utan gradgivningar. Så kan man läsa att över 100 Bröder samlades på restaurang\nAlphyddan och fröjdades åt en munter cabaré ovanpå kräftorna. Det var den 31 augusti\n1920.\n\nJonas Karling avgår\nDen 2 november 1923 avgår Jonas Karling som Riddareceremonimästare, ett ämbete\nsom han burit i med och motgång sedan 1884, alltså i nästan 40 år. Man kan förmoda att\ndet är en mycket lycklig och nöjd Riddareceremonimästare, som kan se tillbaka på åren\ni Jönköpings Par Bricole. Det hade hänt mycket sedan Billing och Karling, från Borås\nPar Bricole, satte in annonsen 1879 i Jönköpings Tidning och kallade ”de för saken\nintresserade” till ett sammanträde i Stadshuset i Jönköping.\n\nOrdförande i Arbetsgraderna\nDen 5 oktober 1925 togs ett mycket viktigt och för Sällskapet betydelsefullt beslut.\nMan beslöt då att också i Jönköping utse en särskild Ordförande, som skulle leda arbe-\ntet i Arbetsgraderna. Den första Ordföranden blev ingenjör Wilhelm Graneli och han\ninträdde i sitt ämbete 1926. 1925 avgick disponent Oscar Roempke som Deputerad\nStyrande Mästare och ersattes av Henrik Karnell. Doktor Axel Jonsson inträdde då som\nStyrande Kansler. Par Bricole och Stora Konseljen antog en ny grad 1925. Det är vår\nnuvarande Nionde Grad (PB***) Konung Magnus Riddarekapitel. Den gavs i Jön-\nköping samma år, alltså 1925 den 25 oktober. Det var arton Bröder som dubbades\ntill Riddare. 1926 gavs graden igen och då antogs tio nya Riddare.\n\nEkonomi\nI jubileumsboken 1879-1929 kan man läsa att Sällskapets ekonomi inte var av det sla-\nget som ”samlar skatter, dem rost och mal förtära”. Revisionsberättelsen från sekelskif-\ntet 1800-1900 säger ”att det lysande sällskapets affärer aldrig har varit riktigt lysande,\nmen att man dragit sig fram”. Flera donationer avsattes i fonder för bestämda ändamål.\nEn byggnadsfond skapades i början av 1900-talet för att man så småningom skulle\nkunna bygga ett eget Ordenshus, men ”sällskapets ekonomi à-la-hand-i-mun gjorde, att\navsättningarna till detsamma snart nog avstannade”. 1929 fanns det 1100 kronor i den\nfonden och drömmen om ett eget hem är alltjämt blott en dröm. Sällskapets ekonomi\ntyngdes de första åren av stora inventarieköp och senare av att det var trögt att få in\nmedlemsavgifter.\n\nMedlemstal\n1929 hade 1024 medlemmar skrivit in sig i medlemsboken. Från sekelskiftet höll man\nsig ganska konstant vid 400-450 medlemmar vilket var mycket med tanke på att det\ninte bodde mer än ca 20 000 människor i Jönköping. 1917 steg medlemstalet markant\noch 1921 var det över 600 medlemmar. 1929, alltså 50 år efter bildandet, var det 560\nmedlemmar av vilka man räknade blott 250 som aktiva.\n\n\n\n                                                                                       27"}, {"pdfPage": 29, "printedPage": null, "text": "1929\nDet Styrande Guvernementet hade inriktat sig på att fira 50 årsjubileet på våren 1929.\nDessvärre avled Styrande Mästaren Ernst Hartmann den 12 januari vilket rubbade pla-\nnerna. Hartmann tjänstgjorde för sista gången vid Barbarahögtiden den 9 december\n1928 och fick aldrig uppleva den dag han så ofta talade om. Den sjätte Styrande Mästa-\nren i Jönköpings Par Bricole blev Henrik Karnell. Som Deputerad Styrande Mästare\ninträdde Kanslären Axel Jonsson och som ny Kansler invaldes Arbetsgradernas Ord-\nförande W Graneli. Henrik Karnells tid blev en mycket framgångsrik tid. Han var med\ni Styrandekretsen hela det lyckliga 20-talet. Nu tog han steget upp som Mästare och\nsom sådan blev han mycket uppskattad för sin vältalighet och för sin varma humor.\n\n\n\nDe senaste femtio åren\nÅr 1954 inledde direktör Anders Graab sin sjuttonåriga period som Styrande Mästare\ni vårt Sällskap (1954 - 1970). Anders Graab var chef för Jönköpings Mekaniska Verk-\nstad och uppges ha varit en skicklig ledare. Han verkade under en tid, då det var vanligt\natt de Styrande rekryterades ur de högsta skikten i samhället, en tid, då avståndet till\n”överheten” också var större än idag. Det var en tid då varje almanacka med självakt-\nning redovisade inte bara kungliga familjens alla medlemmar och medlemmarna i re-\ngeringen, utan också räknade upp alla Sveriges biskopar och landshövdingar. Det lades\ninom Sällskapet vid denna tid - mer än idag - vikt vid vad en Broder hade för social\nställning ute i samhället. Idag har en Broders ställning i den kalmuckiska världen inte\nlika stor betydelse. Det läggs idag, får man nog säga, större vikt vid vederbörande\nBroders bricollistiska talanger och bricollistiska intresse.\n   Under större delen av Anders Graabs tid som Styrande Mästare var också umgänget\ninom Par Bricole enligt tidens sed mer formellt än det är idag. Stämningen var sanno-\nlikt inte mindre hjärtlig för det, men även Bröder emellan följde man de umgänges-\nregler, som generellt gällde i världen utanför Par Bricole. Inte bara i Kalmuckien utan\nockså inom Par Bricole titulerade man varandra. Yngre Bröder titulerade äldre Bröder\noch man väntade med att säga Du till dess en äldre Broder hade föreslagit titelbort-\nläggning. Om någon av de Styrande lade bort titlarna med en Broder i lägre Grad upp-\nfattades detta som en stor heder.\n   Detta umgängessätt ändrades i slutet av 1960-talet. Bror Rexed, generaldirektör vid\nMedicinalstyrelsen, lade bort titlarna med alla sina anställda och år 1968 utgick\n signaler från regeringen om att alla chefer inom offentlig förvaltning borde göra samma\nsak. En Du-reform genomfördes i samhället och säkert infördes vid ungefär samma\ntid denna nymodighet inom Par Bricole.\n   Under 1950- och 1960-talen hade man sammankomster på söndagarna. Vid denna\ntid arbetade man och gick i skolan på lördagarna och det var inte möjligt för intendenturen\natt hinna förbereda en Grad till lördagskvällen. I skolan infördes lediga lördagar i\n\n28"}, {"pdfPage": 30, "printedPage": null, "text": "mitten av 1960-talet och inom arbetslivet ungefär vid samma tid. Par Bricole införde\nGradgivning på lördagar år 1973. Innan denna sedvänja infördes hade man inte heller\nsom idag möjlighet att vila upp sig den påföljande dagen. Ändå hade man senare vanor\ndå än nu, eller snarare tidiga vanor, då man oftast hade nattsexa efter kapitelmötena.\n   Det var under Anders Graabs tid som Styrande Mästare som reglerna för klädseln\nändrades. Förutom ämbetsmännen kunde Bröderna nu närvara i mörk kostym. Detta\ngällde dock inte på Barbarahögtiden, då bars det endast högtidsdräkt, d v s frack med\nvit väst och dekorationer. Det ligger nära till hands att gissa att detta var ett resultat av\ndet dramatiska året 1968 med studentdemonstrationer och kårhusockupationer.\n   Det kan tilläggas att 1950-talets och nog också 1960-talets Gradgivningar säkert var\nmycket rökiga tillställningar. Nästan alla rökte vid denna tid och begreppet ”passiv\nrökning” var ännu inte uppfunnet. Vid middagar hörde det till att värdfolket såg till att\ndet alltid fanns rökverk och askfat på middagsbordet. Om man var väluppfostrad vän-\ntade man med att röka till desserten, men det är väl knappast troligt att Bröder Bricollister\nkunde tåla sig så länge. Numera är Par Bricoles sammankomster i stort sett rökfria.\n   Under Anders Graabs första tio år som Styrande Mästare var direktör Thure Öberg\nDeputerad Styrande Mästare. Också han hade, som chef för Husqvarna Vapenfabrik, en\nhög ställning i samhället. Thure Öberg var en god talare. Han efterträddes av ingenjör\nSixten Arensten, som också han var vältalig. Hans dotter har berättat hur barnen satt\ngömda i trappan och lyssnade medan deras far vandrade runt och högt repeterade sina\ntal inför Par Bricole. Många av de tal, som han har hållit, finns samlade i vår Gyllene\n\n\n\n\nBarbarahögtiden 1967. Jubelkommendörerna Gottfrid Milton och Benkt Norelius hedras av St.M.\nAnders Graab i mitten, D.St.M Sixten Arensten t.v och t.h St.K Carl-Wilhelm Lothigius.\n\n\n                                                                                          29"}, {"pdfPage": 31, "printedPage": null, "text": "bok för perioden 1945 -\n                                                                 1997.\n                                                                    Styrande Kansler 1954\n                                                                 - 1964 var tandläkaren\n                                                                 John Koch, som beskrivs\n                                                                 som ”den sanne Bricol-\n                                                                 listen”. Han var talare,\n                                                                 sångare och spexare, han\n                                                                 sjöng till luta och han var\n                                                                 också bl.a. teaterdirektör.\n                                                                 Anders Graabs och John\n                                                                 Kochs olika person-\n                                                                 ligheter ledde till en\n                                                                 öppen schism mellan de\nNya Styrande 1970. St.K Jan-Erik Berggren, St.M Carl-Wilhelm     Styrande. John Koch av-\nLothigius och D.St.M Waldemar Sjöberg.\n                                                                 gick och efterträddes av\n                                                                 Carl Wilhelm Lothigius.\n   Men trots allt så fungerade denna period inom Par Bricole bra. Kören var bra som\nalltid, men framförallt var detta en period då teatern utmärkte sig. Man framförde årliga\nspex under den uppslagsrike Teaterdirektören, inredningsarkitekt Karl Erik Gemfeldt.\n   I januari år 1957 började man på lördagarna i Sveriges enda TV-kanal sända ett TV-\nprogram kallat ”Tiotusenkronorsfrågan”. Programmet var en kunskapstävling. Om en\ntävlande klarade frågorna på alla nivåer i sitt ämne, vann han tiotusen kronor, vilket var\nmycket pengar vid denna tid. Programmet leddes av litteraturdocenten Nils Erik\nBaehrendtz och hela svenska folket följde med spänning de tävlande lördag efter\nlördag. Flera av vinnarna blev folkhjältar och det är möjligt att ”den från TV riksbekante\nBellmanspecialisten Göran Lindahl” var både tiotusenkronorsvinnare och folkhjälte.\nAtt han år 1961 upptogs i vårt Sällskap med vice Guvernörs rang, ansågs i alla fall\nvärt att särskilt framhålla i protokollet.\n   År 1970 efterträddes Anders Graab som Styrande Mästare av riksdagsman Carl\nWilhelm Lothigius. Hans ämbetsperiod varade till 1983. Under samma period var\ntandläkare Waldemar Sjöberg Deputerad Styrande Mästare och skogsmästare Jan-Erik\nBerggren Styrande Kansler. 1974-1983 var kommunfullmäktiges ordförande Torsten\nWelander Arbetsgradernas Ordförande.\n   Carl Wilhelm Lothigius var på grund av sitt riksdagsarbete i veckorna bunden till\nStockholm, men på måndagarna var han ledig och på måndagskvällen fattades många\nviktiga beslut inom Par Bricole. På grund av Lothigius riksdagsuppdrag och vistelse i\nStockholm fick dock mycket av Styrandearbetet skötas av Styrande Kanslern Jan-Erik\nBerggren. Både Carl Wilhelm Lothigius och Jan-Erik Berggren var charmerande per-\nsonligheter och goda talare. Båda uttryckte sig gärna i bunden form. Carl Wilhelm\nLothigius har hållit talet till Bellman vid Bellmanfirandet på Djurgården. I sitt tal för-\nsökte han göra Bellman till Smålänning men lyckades på sitt mycket eleganta sätt åter-\n\n30"}, {"pdfPage": 32, "printedPage": null, "text": "börda Carl Michael till huvudstaden,\ndär han hör hemma.\n   År 1972 fyllde ”Den gamle Bricol-\n                                                         0\nlisten” Gustaf Lorenz 85 år. Teatern\ntackade honom för hans arbete som\nmaskör och Anders Graab tackade ho-\nnom för det enastående intresse han\nhade visat under sina 58 år i Sällska-\npet.\n   Flera initiativ till förändring togs,\n                                                         :\nmen alla blev inte lyckade. År 1974\nprovade man att förlägga Andra Gra-\nden med spex till A 6 marketenteri.\n                                                          >\nDetta gav enligt protokollet ”en fadd\neftersmak”. Enligt rapport från i festen\ndeltagande Bröder urartade festen på ett\n                                          Avgående St.M Anders Graab lyckönskar\npinsamt sätt. Detta till trots upprepa- efterträdaren Carl-Wilhelm Lothigius och St.K Jan-\ndes försöket 1990. Broder Ingemar Erik Berggren år 1970.\nBoman ledde då arbetet med att bygga\nupp sitt stora projekt Nya A6 och Bröderna inbjöds att på nytt förlägga Den Andra\nGraden till gamla ”markan”. Om 1974 gav en ”fadd eftersmak” så kan man nog med\nfog påstå att 1990 blev om möjligt än värre. Deputerad Styrande Mästare Torsten\nWelander såg sig nödsakad att avhysa en person, som dessutom uteslöts ur Sällskapet\nmed omedelbar verkan. Mycket var naturligtvis bra också, men att sälja snapsar för tio\nkronor och dessutom ha tombola med whisky som vinst var nog ingen bra idé.\n   Bröderna Mac och Gerhard Mattus var respektive generalceremonimästare och\nriddareceremonimästare. De hade många idéer till förändring av ritualen. En episod,\nsom det berättas om, avser ”vaktombytet” vid Barbarahögtiden då Generalsgradernas\nämbetsmän går in medan Arbetsgradernas ämbetsmän går ut ur Spegelsalen. Bröderna\nMattus hade utbildats vid Karlberg. De möttes mitt i Spegelsalen i preussisk marsch\nmed hög benlyftning och huvudvridning. Detta krigiska inslag i Par Bricole ogillades\nav många och upprepades inte.\n   År 1976 återupplivades efter 30 år i malpåse ritualen i Fjärde Graden med ”de fyra\nrummen”. Det blev ett uppskattat inslag, som sedan dess regelbundet har återkommit.\nVid nypremiären agerade Bröderna Lucas Stahre, Sune Winald och Gustaf Lorenz\niklädda gustavianska dräkter och med stor inlevelse.\n   År 1979 genomfördes Sällskapets 100-årsjubileum. Det blev ett pampigt firande,\ndär John Kochs högtidstal utgjorde en av höjdpunkterna. Talet återges i sin helhet under\nkapitlet om Avisa.\n   John Koch hyllar och namnger i detta högtidstal många framstående bricollister,\nsom under åren har spridit glans över Jönköpings Par Bricole. Hade dessa Bröder levat\nidag hade de säkert haft bringan fullbehängd med medaljer. Men det är inte säkert att de\n\n                                                                                       31"}, {"pdfPage": 33, "printedPage": null, "text": "Landshövding Sven af Geijerstam med St.M Carl-Wilhelm Lothigius sittande och tidigare St.K\nJohn Koch stående. Året var 1979.\n\n\ntrots sina strålande insatser hade så många.\nDet medaljregn, som idag stilla faller över\nhög som låg, uppges vara av ganska sent\nursprung. Sen mitten av 1980-talet har\nmedaljframställningen och utdelningen\nenligt mångas uppfattning fått lite för stort\nutrymme och dessvärre bär många Brö-\nder medaljer, som inte är godkända av\nSällskapet. Redan Carl Wilhelm Lothigius\nprotesterade mot denna utveckling genom\natt uppträda helt utan medaljer vid flera\ntillfällen. En bidragande orsak till denna\nutveckling kan vara att alla talang-\ngrupperna låtit göra egna vedermälen.\nIdag har medaljutdelandet blivit en insti-\ntution och en viktig företeelse inom Par\nBricole.\n    Barbaradagen 1981 var nästan 200 Brö-       Ordens Talare och Skald Miles von Strokirch\n                                                firas som Jubelkommendör år 1982.\nder närvarande. Då framfördes i stället för\n\n32"}, {"pdfPage": 34, "printedPage": null, "text": "ett högtidstal en sånglig hyllning till\nMoster Barbara. Hyllningen framfördes\nav Sune Winald och PG Karlberg. För\ntexten svarade Gunnar Gårdmark och för\nmusiken W. A. Mozart.\n   År 1982 gavs för första gången i\nJönköpings Par Bricoles historia den\nSjunde Graden utomhus. Den gavs på\nVästanå slott hos Broder Rolf von Otter\noch hans hustru Charlotte. Att ge Graden\nutomhus har härefter blivit en fin tradi-\ntion. Jönköpings Par Bricole är ensam\ninom bricolleriet om detta. Sjunde Gra-\nden är också den Grad som har flest be-\nsök från vår Moderloge och våra Syster-\nloger. Numera ges Graden i Alvastra klos-\nterruin, det kloster som Konung Sverker\nen gång lät uppföra. Med tanke på att\nAlvastra kloster är så nära förknippat med\n                                              St.M Carl-Wilhelm Lothigius talar vid Barbara-\nKonung Sverker är det en mäktig känsla högtiden 1982.\natt ge hans Riddarekapitel i den gamla\nklosterruinen. Graden har nu givits utomhus i över 20 år och många Bröder har under\ndessa år upplåtit sina gods och lantliga egendomar för firandet av PB**. Graden har\nockså genomförts i Vadstena klosterkyrka och på Tempelgården på Visingsö. Med få\nundantag har vädrets makter alltid stått Sällskapet bi.\n   Redaktionskommittén trodde länge med utgångspunkt från bevarade fotografier att\nden Sjunde Graden första gången gavs utomhus under 1930-talet. Både år 1933 och\n1939 samlade Styrande Kanslern Länsjägmästare Wilhelm Lothigius bricollister om-\nkring sig på Skogsvårdsstyrelsens kursgård Trollebo söder om Vetlanda.\nBesöket år 1933 finns dokumenterat i form av härliga skioptikonbilder. På en av bil-\nderna står Bröderna uppställda i munderingen för Sjunde Graden. Dock nämns det inte\nnågot om Gradgivning i protokollen. Men det finns en muntlig tradition om en sådan.\nWilhelm Lothigius efterträddes som länsjägmästare av Åke Hallander, vilken i sin tur\nefterträddes av Broder Sven Sandell. Åke Hallander skall enligt uppgift ha visat Sven\nSandell var i parken runt huvudbyggnaden på Trollebo, som altaret vid Gradgivningen\nbyggdes upp. Vid ett besök på Trollebo våren 2004 visade Sven Sandell också platsen\nför ledamöterna i Arkiv X, som är en grupp Bröder vilka regelbundet träffas för att\nunder gemytliga former katalogisera och sortera foton m.m.\n   Ja, så trodde redaktionen ända till dess att dess ögon föll på en artikel skriven av\nBroder Ernst Greén i boken ”Sällskapet Par Bricole - Historik och Porträttgalleri med\nBiografier” (tryckt i Stockholm år 1946).\n\n\n                                                                                         33"}, {"pdfPage": 35, "printedPage": null, "text": "Procession in vid Barbara 1992. GB Bertil Palmé-Johnsson under banéret och RH Gunnar\nEriksson under hattten.\n\n\n\n\n1983. O Sune Winald. Från vänster D.St.M Waldemar Sjöberg, St.M Carl-Wilhelm Lothigius och\ntidigare St.K John Koch.\n\n\n34"}, {"pdfPage": 36, "printedPage": null, "text": "Nytt Styrande\nGuvernement år 1983.\nSt.M Jan-Erik Berggren\nflankerad av D.St.M\nTorsten Welander och\nSt.K Gerhard Mattus.\n\n\n  Där berättas att ovanstående händelse var ett bricollistiskt upptåg och ej en ”äkta”\nSjunde Grad.\n  År 1983 tillträdde Jan-Erik Berggren som Styrande Mästare. Deputerad Styrande\nMästare blev Torsten Welander, som 1991 efterträddes av Anders Hugoson. Styrande\nKansler under Jan-Erik Berggrens tid var Gerhard Mattus. Arbetsgradernas Ordförande\nvar fram till 1989 adjunkt Sune Winald, som därefter ersattes av direktör Perolof Kallings.\n  Torsten Welander var Mästare i att hålla korta tal och man visste inte riktigt om han\nhade börjat när han hade slutat. Torsten Welander var oerhört effektiv med en finstämd\nhumor. Han satt under flera år i Jönköpings Kommunfullmäktige som dess ordförande\noch vice ordförande. Styrande Kanslern Gerhard Mattus var full av idéer och hade en\n\n\n\n\n                                                                 D.St.M Torsten Welander\n                                                                 håller tal vid Barbarahög-\n                                                                 tiden 1988.\n\n\n                                                                                          35"}, {"pdfPage": 37, "printedPage": null, "text": "Värdparet Gunilla och Carl-Göran Gustafsson överlämnar Lyckås till St.M Jan-Erik Berggren.\nAnders Lindell blåser fanfar.\n\n\nelegans i sitt uppträdande, som förde tankarna till Gustaf den III: s dagar. Sune Winald\nvar den Ordförande man minns, som mannen med den mäktiga barytonstämman. Sune\nWinald hade förmodligen tagit steget upp i Styrandekretsen om det inte hade varit för\nhans funderingar kring Riddaregradernas koppling till den Allsmäktige. Dåvarande statu-\nter sade att man skulle ha en kristen tro. Idag säger statuterna att man ska respektera de\nkristna värderingarna och vår nutidshistoria kunde kanske ha skrivits annorlunda om\nstatuterna hade ändrats tidigare. Sune avled samma år han skulle gå i pension och många\nminns fortfarande hans framförande av Kommendörsvisan som en av höjdpunkterna\nvid måltidskalaset. Han var också en strålande aktör inom teatern och tillika dess direk-\ntör under några år.\n   Jan-Erik Berggren lyckades knyta mycket nära kontakter med moderlogen i Stock-\nholm, sannolikt närmare än vad Jönköpings Par Bricole någon gång tidigare har haft. I\ndessa sina strävanden hade han ett stort stöd hos Gerhard Mattus och Knut Erik Jahnke.\nUnder Jan-Eriks tid startade, trots motstånd från moderlogen, talanggruppen Luculli\ngille. Jan-Erik Berggren lyckades också genomföra att det år 1994 startades en\nBacchanalisk akademi i Jönköping.\n   År 1984 gavs Sjunde Graden på Lyckås herrgård hos Broder Carl-Göran Gustafsson\noch hans hustru Gunilla. Bröderna fick lyssna till en intressant resumé om slottets\n\n\n36"}, {"pdfPage": 38, "printedPage": null, "text": "RP Per-Axel Jonzon och 1RO Lars Löfstedt (närmast) medaljeras av\n                     St.M Jan-Erik Berggren vid Barbarahögtiden 1988.\n\nhistoria från 1500-talet och fram till våra dagar. Kapitlet och måltiden gavs respektive\navnjöts i det fria, medan kaffe och punsch serverades i de vackra salarna. Men 1984 var\ninte ett i allo lyckosamt år för Par Bricole. Då Fjärde Graden skulle ges meddelade\nendast 4 av 35 kallade att de önskade bli recipierade, varför den inställdes.\n    År 1985 genomförde man en arbetsgrad på restaurant Maxim inom Tändsticks-\nområdet. Teaterdirektör var då den talangfulle majoren vid A6, PG Karlberg. I sitt tal\ntill talanggrupperna glömde Torsten Welander att nämna teatern, vilket blev droppen\nsom fick bägaren att rinna över. Karlberg gick till de Styrandes bord, tog av sig sitt\ndirektörsband och la det på bordet. I ett brev till De Styrande bad han om sitt utträde.\nJan-Erik Berggren besvarade brevet. Båda breven finns bevarade och arkiverade. Mycket\nhar hänt som har glatt Bröderna under 125 år, men även det negativa måste ju nämnas.\nPG Karlberg var en oerhört duktig och idérik teaterperson med en fantastisk sångröst.\nHan genomförde också spexet ”Ulla den Tredje” i Stadsparken vid Jönköpings 700-\nårsfirande.\n    År 1985 hittades också Par Bricoles sedan länge försvunna ”teateråsna” på Stora\nHotellets vind. Åsnan, som vid återfinnandet var i dåligt skick, hade tidigare använts i\nAndra Graden. Återfinnandet ledde inte till att ”åsnetraditionen” återinfördes. Dock lär\nåsnans Bröder leva i högönsklig välmåga i bl. a Göteborg, Vänersborg och Borås.\n    I december 1985 gick den f.d. Styrande Mästaren Carl Wilhelm Lothigius bort. ”För-\nsynt och vänlig och med en poetisk ådra, som åtskilliga gånger har lyst upp vår\nbricollistiska tillvaro.” Hans minne hyllades med en minnesstund vid det ljusskimrande\nkalaset (Fjärde Graden) i februari 1986. Bland andra talade då Stormästaren i moder-\nlogen Hans Kjellgren.\n\n\n                                                                                        37"}, {"pdfPage": 39, "printedPage": null, "text": "År 1986 gavs Sjunde Graden på Ramsjöholm hos Broder Karl Gustaf Kindberg och\nhans hustru Vera. Ett stritt vårregn gjorde att ceremonin måste avkortas och måltid-\nskalaset avnjutas inomhus.\n   Med anledning av Styrande Mästaren Jan-Erik Berggrens 60-årsdag uppförde\nteatern i oktober samma år spexet ”Här är ditt liv JeJe”, sannolikt inspirerat av en vid\ndenna tid populär serie på TV vid namn ”Här är ditt liv”, där olika kidnappade kändisar\nfick se sitt liv spelas upp, möta gamla skolkamrater osv. Sjätte Graden gavs detta\når i Hakarps församlingshem, där det knappa utrymmet ledde till verklig ”förbröd-\nring”, medan parentationen hölls i Hakarps kyrka.\n   Det kan nämnas att den första parentationen i Sjätte Graden i Jönköping i en kyrka\ngenomfördes så tidigt som 1948. De Styrande beslöt detta år att delar av Graden skulle\nförläggas till Ljungarums kyrka. Riddareprelaten Tage Löf, som var kyrkoherde i\nBottnaryd, höll parentation över de Bröder som avlidit under året. Ljungarums kyrka\nfylldes till bredden och man beslöt att förlägga nästa års parentation i Kristine kyrka.\nDär blev det en aning tomt i bänkarna, man återgick till Ljungarums kyrka, men flyt-\ntade 1959 till Järstorps kyrka. Jönköping var först i landet med att genomföra den Sjätte\nGraden på detta sätt. Numera har nästan samtliga Loger parentation med musik och\nminnesgudstjänst för allmänheten i någon kyrka. Utöver till Kristine kyrka och\nLjungarums och Järstorps kyrkor har minnesgudstjänster också förlagts till Hakarps\nkyrka och Slottskapellet. Sedan år 2000 har man återgått till ursprunget - medeltids-\nkyrkan i Ljungarum.\n\n\n\n\nPar Bricoles Högtidsdag 1995 med Parentation i Hakarps kyrka, agerande Lars Löfstedt och\nAnders Hugoson.\n\n\n38"}, {"pdfPage": 40, "printedPage": null, "text": "1988 på\nBarbaradagen:\nJohan, Farfar Eric\noch Far Lars-Eric\nLiljegrahn alla\naktiva bricollister.\n\n   Vid 1987 års Vårbal framträdde två framstående sångare, Frank Johnsson från Vän-\nersborg och Ordensskalden Martin Stugart. Frank Johnsson sjöng till luta och lyckades\nförflytta hela Vårbalen till Birger Sjöbergs Lilla Paris. Ordensskalden interfolierade\nGradgivningarna med valda delar ur Fredmans sånger och epistlar.\n   År 1988 firades den Sjunde Graden på Stora Hultrums gård hos Broder Casten von\nOtter och hans hustru Vera. Sångarbröder från Borås hördes från en höjd intill lunden.\nDå Gunnar Hofberg, Styrande Mästare i Göta Par Bricole, började sitt tacktal uttalade\nen kvinnlig stämma skarpt ”Håll tyst med dig”. Efter en kort förvirring återupptogs\ntalet då det visade sig att dagens värdinna inte hade vänt sig till talaren utan till husets\nhund.\n   1990 gavs Den Sjunde Graden på Dalskogs Herrgård hos Broder Per-Åke Löf och\nhans hustru Anita. Solen sken, blommor och träd stod i sitt vackraste flor och platsen\nvar en sannskyldig pastoral rapporterar vår inspirerade ordenssekreterare.\n   År 1991 uppmanade man Bröderna att åter bära högtidsdräkt vid Par Bricoles sam-\nmankomster. ”På grund av svårigheten att anskaffa högtidsdräkt har under ett antal\når obligatoriet att använda sådan uppmjukats”, heter det i protokollet. Möjligen var\ndet i verkligheten så att vindarna från 1968 också blåste in i Par Bricole, men att tids-\nandan nu hade ändrats så mycket att man åter kunde vandra genom stan i frack. Mörk\nkostym skall dock inte diskvalificera från att delta, heter det försiktigtvis i slutet av\nprotokollet.\n   År 1992 gavs Sjunde Graden i Alvastra klosterruin, där Brödernas förehavanden\nväckte viss uppmärksamhet bland ditlupna turister. Spridda regndroppar noterades. De\nBröder, som förtänksamt hade tagit med paraply avundades av övriga. Högtidstalet och\nrecipiendernas tacktal hölls i form av en medeltida rimkrönika av prosten i Vadstena\nklosterkyrka Göran Grefbäck, som i samband med Graden blev utnämnd till Ordens\nTalare och Skald. Måltidskalaset hölls på Ombergs Turisthotell.\n\n\n                                                                                         39"}, {"pdfPage": 41, "printedPage": null, "text": "I november samma år fick Par Bricole\n                                               besök av hedersmedlemmen Ignatij\n                                               Ivanovski från S: t Petersburg, som höll ett\n                                               tal om Bellman vid Barbarahögtiden. Dess-\n                                               utom ordnades detta år decenniets fest i Par\n                                               Bricole, en Operamaskeradbal i Stora Ho-\n                                               tellets Spegelsal. De Bröder, som inte an-\n                                               mälde sig och deltog, går fortfarande och\n                                               grunnar över varför de inte gjorde detta.\n                                               I början på 1990-talet trängde dator-\n                                               samhället också in i Par Bricole och i mars\n                                               1993 ordnades i Jönköping en Riks-\n                                               konferens för Datorisering i Par Bricole ock-\n                                               så kallad ”Mac Bricole”.\n                                                  År 1993 tillträdde chefen för den Odon-\nRecipienderna Anders Jonzon och Johan Thor     tologiska Institutionen i Jönköping Anders\ni väntan på tillträde till Bricoles rum. 1994. Hugoson posten som Styrande Mästare.\n                                               Hans Styrandeperiod varade till 1999. Han\nbiträddes under hela sin ämbetstid av den Deputerade Styrande Mästaren, miljövårds-\ndirektören vid Länsstyrelsen i Jönköping, Eric Haglund, Styrande Kanslern, Program-\nbolagets VD, Perolof Kallings och Ordföranden i Arbetsgraderna, universitetsadjunkt\nDan Ekström.\n   År 1994 gavs Sjunde Graden i Haurida\nkyrka och på Sandviks gård hos Broder Jan-\nErik Berggren och hans hustru Mari-Anne.\nI kyrkan inledde Jan-Erik med att berätta\nom kyrkans historia. Efter ceremonielets\nslut åkte Bröderna till Sandviks gård, där\nvärdparet gav Par Bricole tillstånd att dis-\nponera gården. På gårdsplanen ner mot sjön\nhade byggts en kapitellund och i stilla bris\noch lätt regn fullföljdes Gradgivningen.\nStormästaren i Moderlogen Hans Kjellgren\nblev salig, då två vita sångsvanar flög över\nlunden, och mången Broder trodde sig nog\nsitta vid sjön Roines i stället för vid Ylens\nstrand. Det lyckade måltidskalaset ägde\nmed hänsyn till väderleken lämpligt nog\nrum under tak i en stor lada. Måltiden ack-\nompanjerades av de i ladan häckande ladu-\nsvalornas glada kvitter. Svalbon ingick Konung Magnus Ladulås i Lars Löfstedts\ndock inte i menyn.                               skepnad.\n\n\n40"}, {"pdfPage": 42, "printedPage": null, "text": "Barbaratalaren Gunnar Åkerskog får telefon    St.K emeritus Gerhard Mattus år 1993.\nfrån Moster år 1993.\n\n\n\n\n                                      -~-s\n                              Det Styrande Guvernementet 1993.\n\n\n\n\n                                                                                      41"}, {"pdfPage": 43, "printedPage": null, "text": "Dambricolleri 1995. DStM Eric Haglund dekorerar Styrande Mästarens kärälskeliga Margareta\nHugoson under övervakning av OMI Ingemars kärälskeliga Yvonne Boman.\n\n\n   År 1996 anordnades Sjunde Graden hos Broder Birger Axelsson och hans hustru\nBirgit på Renstorps säteri i Månsarp. Akten inleddes i Månsarps kyrka varefter man\nförflyttade sig till Renstorp. Miljön var pastoral och solen sken, i alla fall inledningsvis.\nDå värdparet skulle hälsas av den Styrande Mästaren dränktes den bricollistiska välta-\nligheten av en nyfiken pilot, som med sitt flygplan oavlåtligt snurrade runt över gårds-\nplanen för att närmare studera den märkliga samlingen av människor där nere. Den fina\nGradgivningen i en Helig lund strax intill gården interfolierades av åskans muller och\njust då Gradgivningen var slut öppnades himmelens portar. Åtskilliga Bröder kunde ta\nsin tillflykt till ett tomt garage, där PB-kören förljuvade tiden i väntan på att regnet\nskulle upphöra med att bland annat sjunga ”Dåne liksom åskan Bröder”. Den för de\nuppdukade borden i den vackra trädgården förberedda måltiden fick på grund av me-\nteorologiska omständigheter intas i Månsarps församlingshem. Då i denna lokal endast\nalkoholfria drycker fick inmundigas ordnade Providören Berno Wessman och den som\nvanligt driftige Styrande Kanslern Perolof Kallings en improviserad bar på gården.\nServeringen skedde från bakluckan på en bil. Ett förnämligt tacktal hölls av Brodern,\nskådespelare Per Norelius. Festen blev mycket lyckad och länge i de deltagandes\nminne bevarad.\n   År 1998 år gavs Sjunde Graden vid Vadstena klosterkyrka. Värdpar var Broder\nGöran Grefbäck och hans hustru Birgit. Akten inleddes med samling i kyrkan, där\n\n42"}, {"pdfPage": 44, "printedPage": null, "text": "De Trenne Styrande från\nvänster Perolof Kallings,\nAnders Hugoson och Eric\nHaglund i glädjedans efter\nrevisionen 1996.\n\n\nkören inledningsvis sjöng och Göran berättade om kyrkans historia. I Tempellunden\ntäcktes marken av vita klosterliljor i sitt finaste flor. Måltidskalaset ägde rum i\nKungssalen i Bjälboättens palats.\n   Anders Hugoson efterträddes år 1999 som Styrande Mästare av Dan Ekström.\nDeputerad Styrande Mästare blev direktör Leif Thor och som Styrande Kansler till-\n\n\n\n\nStormästare Sven-Olof Forselius gratulerar det nya Guvernementet 1999. Från vänster D.St.M Leif\nThor, St.M Dan Ekström och St.K Sigvard Brännström\n\n\n                                                                                             43"}, {"pdfPage": 45, "printedPage": null, "text": "Director i Bacchanaliska Akademin Charles Petruson talar vid 7 graden i Vadstena år 1998.\n\n\nträdde säkerhetschef Sigvard Brännström. Leif Thor och Dan Ekström, som hade\narbetat tillsammans både inom teatern och i Arbetsgraderna, visade sig ha olika upp-\nfattningar om Sällskapets syfte och verksamhet. Leif Thor, som förespråkade en\nöppnare och mer utåtriktad verksamhet, valde att lämna sitt höga ämbete med omedel-\nbar verkan 2001. Arbetsgradernas Ordförande Gert Karlsson insattes då som Depute-\nrad Pro Tempore att fungera vid de Gradgivningar, där ämbetet krävde medverkan.\nVid installationen 2003 installerades Gert Karlsson som Deputerad Styrande Mästare\noch advokat Lars Oscarsson efterträdde Sigvard Brännström som Styrande Kansler.\nTeaterchefen vid Smålands Musik och Teater, Bernt Lindqvist, efterträdde Gert Karls-\nson som Ordförande.\n   År 2000 gavs Sjunde Graden på Tempelgården på Visingsö. Från lunden hade man\nen härlig utsikt över Vättern och fåglarna sjöng. En munk vid namn Benedictus\nLindqvistus framförde Gradens historia. Efter Gradgivningen deltog alla i en guidad\nbusstur runt ön, varefter måltidskalaset inleddes med sill och brännvin i Visingsborgs\nslottsruin. Per Brahe d.y. med maka hälsade Bröderna välkomna till slottet. Var det\ndock ej äkta Brahar, utan Anders Ruberg samt Helene Lomstad, som hälsade. Själva\nmåltidskalaset ägde rum på restaurant Hjorten i Gränna. Det lär ha gått livat till.\n\n\n44"}, {"pdfPage": 46, "printedPage": null, "text": "År 2001 infördes frack som normal klädsel\nvid Par Bricoles begivenheter - några till glädje\noch andra till förargelse.\n    År 2002 flyttades Andra Graden tillfälligt\ntill QV-center vid A 6 golfbana. Spegel-\nsalens parkett byttes för en kväll mot en\ngymnastiksals gröna golv.\n    Samma år gavs den Sjunde Graden hos\nBroder Olof Björklund och hans hustru\nMarianne på Hällestorps gård. Sedan Sällska-\npets flagga hissats för att markera att gården\nnu ”intagits” av Par Bricole tågade Bröderna\ntill Gradgivning. Från ett jakttorn skallade\ntrumpetstötar och en gammal munk från\nAlvastra (Göran Grefbäck) undervisade de\nokunniga. Mellan Graden och måltidskalaset\nunderhöll den mästerlige trubaduren Frank\nJohnsson från Vänersborg. Frank sjöng Bell- Bernt Lindqvist tillträdde som\nman och Taube, göktytan tytade, solen sken Ordförande i Arbetsgraderna 2003.\noch måltidskalaset var i allo lyckat. Det var en\nminnesvärd dag.\n    Men Det Lysande Sällskapet Jönköpings Par Bricole kommer säkert att skänka sina\nmedlemmar flera sådana dagar. Vi behöver inte oroa oss för Sällskapets framtid. Som\n\n\n\n\nVärdparet på Hällestorps gård, Marianne och Olof Björklund tillsammans med St.M Dan Ekström\n\n\n                                                                                          45"}, {"pdfPage": 47, "printedPage": null, "text": "Den Gamle Bricollisten sa: ”Oroa Dig inte för morgondagen - i övermorgon är den\nförbi!”\n   Det Styrande Guvernementet år 2004 består av Styrande Mästare Dan Ekström,\nDeputerad Styrande Mästare Gert Karlsson och Styrande Kansler Lars Oscarson.\n\n\n\n\nDe Trenne Styrande Jubileumsåret 2004.\nF.v. D.St.M Gert Karlsson, St.M Dan Ekström och St.K Lars Oscarsson.\n\n\n\n\n46"}, {"pdfPage": 48, "printedPage": null, "text": "Tre Jönköpingsbricollister\n\nJohan Axel Stedt - Jönköpings förste bricollist\nVem var Jönköpings förste bricollist? Frågan väcktes vid Stormästare Gösta Söder-\nbergs högtidstal 1954, då Jönköpings Par Bricole firade 75-årsjubileum. Stormästaren\nanspelade på att tankar funnits om att starta ett bricolleri i Jönköping innan Kexél stad-\nfäste Moderlogen 1779. Vad menade han? I August Kindbergs bok ”Par Bricole”, utgi-\nven 1903, upptas överraskande nog i vårt Sällskaps (Moderlogens) första inskrivnings-\nbok tre bricollister från Jönköping. I den äldsta sammanställningen, som registrerades\nföre sammanträdet på Stadshuset i Stockholm den 15 maj 1779, finns namnet på en\nJönköpingsbo. Ledamoten ifråga har av Olof Kexél fått medlemsnumret 38 och var vid\nintagningen i Sällskapet kapten vid Jönköpings regemente.\n   Hans namn var Johan Axel Stedt, född den 20 juli 1756 och död den 7 april 1805.\nHan var gift med en dotter till överdirektören för Husqvarna faktori, Fredrik Ehrenpreuss.\nStedt ligger begravd i familjegraven på Svenarums kyrkogård. Stedt beskrivs av många\nsom en hetlevrad herre, men energisk och gladlynt. Det är troligt, att han under sina\nStockholmsbesök sammanstrålade med Bellman, Kexél och Bröderna Gustaf och Adrian\nStiernecrantz. Kanske också med greven Johan Gabriel Oxenstierna som stod Bellman\nmycket nära och var en stor beundrare av hans ordenskapitel. Förmodligen var denne\nhetlevrade kapten beredd att starta någon form av orden i Jönköping och drev förmod-\n\n\n\n\n                                                                     ofverseen cle•\n                                                                 •\n\n\n\n\n                             I—Iofsecreterare.                            •skade-\n                        swycke• ,\n\n\nUr Moderlogens äldsta matrikel. (A. Kinberg: Par Bricoles Gustavianska period, Stockholm 1903).\n\n\n                                                                                            47"}, {"pdfPage": 49, "printedPage": null, "text": "ligen frågan ganska frispråkigt i kretsen kring de omnämnda Bröderna. Nu blev det inte\nså och det är väl både tur och otur, för nog hade det varit en bricollistisk klimax om det\nhade funnits en dotter till en moder som ännu inte var född. I Par Bricoles inskrivnings-\nmatrikel ser man vidare att Kexél fick nummer 2 efter Adolph Barnekow till Björnstorp\nsom fick nummer 1, förmodligen på grund av hans höga samhällsställning. C.M.Bellman\nfick nummer 29 i matrikeln där vi alltså hittar Jönköpings förste bricollist med nummer\n38. En annan ledamot av Par Bricole, som var född i Småland och åtminstone tidvis\narbetade i Jönköping, var nr 187 Adam Stålhammar. Han var vid intagningen den 29/11\n1779 musiker vid Jönköpings regemente. Han var född i Småland, blev Bankofull-\nmäktig i Stockholm och var en av Pechlins anhängare.\n   1785 intogs i Moderlogen Fiscalen och sedermera Protonotarien i Svea Hovrätt Olof\nHortulan med matrikelnummer 327. Han var mycket nära vän med sångaren Jacob\nLundström som dog 1800 och som finns präglad på ett av Moderlogens förnäma\nvedermälen med band i rött. Hortulan dog i Jönköping 1811. Matrikeln upptar även\nunder perioden t o m utgången 1809 sådana för vår bygd kända namn som Schånberg,\nOlbergs, Lothigius och Ulfsparre. För övrigt kan sägas att häradshövding Ulfsparre var\ngift med en Stedt, som förmodligen var dotter till Jönköpings förste bricollist, lands-\nhövdingen Johan Axel Stedt med matrikelnummer 38.\n\n\n\nGustaf Lorentz - Jönköpings ”meste” bricollist\n\n                                                     Gustaf Lorentz (1887 - 1980) var\n                                                     frisör med en egen salong i staden\n                                                     och älskade teater. Han skrevs in i\n                                                     vårt Lysande Sällskap redan 1914\n                                                     och blev med åren något av en le-\n                                                     gend. Han medverkade i flera år som\n                                                     kunnig sminkör vid Teaterns spex\n                                                     innan han blev medlem i Sällskapet.\n                                                     Han var aktiv medlem åren\n                                                     1914-1980. 1964 blev han Jubel-\n                                                     kommendör och 1975 förlänades\n                                                     han Sällskapets Högsta grad (RSK).\n                                                     Gustaf Lorentz eminenta talang och\n                                                     hans stora intresse för teaterkonsten\n                                                     gav honom en given plats på de til-\n                                                     jor som skall föreställa världen. Han\n                                                     medverkade vid åtskilliga teater-\nGustaf Lorentz som ”Den Gamle Bricollisten” år       framträdanden under många decen-\n1979.\n\n48"}, {"pdfPage": 50, "printedPage": null, "text": "Lundströmska medaljen deciderad till Gustaf Lorentz.\n\n\nnier och han tjänade som teaterns kunnige och alltid villige maskör fram till sin död.\nHans insatser har varit enorma. Brödernas uppskattning av denne vår äldste Ordens-\nbroder var ovationsartad vid flertal tillfällen och redan 1954 erhöll han Eklöfskransen\nsom är Jönköpings Par Bricoles förnämsta utmärkelse. Denna utmärkelse tilldelas den\nsom gjort sig alldeles särskilt bemärkt genom talangfullt bidrag till våra anständiga\ntidsfördriv och Gustaf Lorentz var en av våra värdigaste mottagare. Gustaf Lorentz var\nallt sammanfattad i det vi menar med en riktig bricollist.\n   Inom Arbetsgraderna finns historiska texter för teatern att förvalta. Ett sådant stycke\när ”Den Gamle Bricollisten”, som Gustaf Lorentz under många år framförde sittande\nvid ett litet bord med stearinljus. Iklädd en vit skjorta utan krage och med ärmar av\nspets och lösa band återgav han minnen från sitt långa liv med en tillbakahållen över-\ntygelse. Hans spel var lågmält och klart, med stor närvaro och tydlig artikulation. Lorentz\nframförde inte rollen, han var den gamle Bricollisten med stort B. Han berörde alla\nsinnen och frammanade bilder som ingen gjort senare. Gustav Lorentz kan anses\nsom ”Jönköpings mesta bricollist” och har en alldeles särskild plats i Jönköpings Par\nBricole.\n\n\nKnut-Erik Jahnke - Jönköpings mest ”ihärdige”\nbricollist\nKnut-Erik Jahnke (1915 - 1990) var skåning. Vid slutet av 1930-talet kom han till Jön-\nköping där han etablerade sig som optiker med mycket stor framgång. Tre butiker i\n\n\n                                                                                        49"}, {"pdfPage": 51, "printedPage": null, "text": "Jönköping och Huskvarna kom att\n                                                      bära hans namn. Han blev en mycket\n                                                      aktad yrkesman och anlitades ofta av\n                                                      centrallasarettet.\n                                                         Inom Par Bricole organiserade\n                                                      och administrerade han det mesta\n                                                      och han hade förmågan att delegera\n                                                      och sprida idéer om förbättringar av\n                                                      Sällskapets ekonomi. Många sköna\n                                                      slantar sägs ha tillförts vår kassa\n                                                      genom hans försorg. Han var både\n                                                      envis och energisk, en bra kombina-\n                                                      tion för en entusiastisk och brin-\n                                                      nande bricollist.\n                                                      Som skribent var han rolig och un-\n                                                      derhållande. Han hade en sällsynt\n                                                      förmåga att leverera både kvicka och\n                                                      dräpande repliker. Han var den själv-\nStormästaren Hans Kjellgren dekorerar Knut-Erik       klara medelpunkten där hans humor\nJahnke år 1983.\n                                                      och berättarkonst flödade. Han pra-\ntade ofta själv om källan för sitt stora teater- och revyengagemang, nämligen vänska-\npen med skådespelaren Nils Poppe. Knut-Eriks gode vän var en ganska ofta återkom-\nmande gäst i Jönköping, dock inte inom vårt Sällskap.\n    En dramatisk händelse inom teatern inträffade år 1947. I en sketch skulle en världs-\nberömd hypnotisör, Dr Diabolo Eisensten, försätta en klient i trance för att därefter få\nhonom att sväva fritt över golvet. Den som spelade hypnotisörens klient var Knut-Erik\nJahnke. Vid generalrepetitionen hade man kommit överens om att Jahnke skulle falla\nbakåt redan vid den första hypnotiska gesten och precis före fallet mot golvet fångas\nupp av Dr Diabolos betjänt. Emellertid hade medspelaren i betjäntrollen omedelbart\nföre entrén drabbats av stor nervositet och lugnat sig med ett par extra supar, vilket fick\ntill följd att han helt glömde bort att ta emot den bakåtfallande klienten. Knut-Erik\nJahnke lär ha utfört det mest perfekta trancefallet i teaterhistorien och slog huvudet i\ngolvet med en smäll, som väckte berättigad beundran. Han bars ut helt avsvimmad och\nunder stormande applåder. Att han fritt skulle kunna sväva över golvet var det i alla fall\ningen som hade trott på.\n    Knut-Erik lyckades att tillsammans med hotellets direktör få till en fungerande scen\ni Spegelsalen. Därtill fick han teaterns medlemmar att börja ta sina uppgifter på allvar\noch att stärka sitt självförtroende med fler repetitioner istället för whisky. Att stå på\nscenen i skjortärmarna och göra sig till inför kompisarna ansågs ibland både löjligt och\nonödigt. Så när det kom till föreställning överfölls man av stora skälvan och behövde\nnågot att stärka sig med. Knut-Erik Jahnke fick teatern att skärpa sig. Färdiga manus\nfrån början samt planerade och regelbundna repetitioner påbjöds. Sedan 40-talet har\n\n50"}, {"pdfPage": 52, "printedPage": null, "text": "också den konstnärliga standarden höjts, även om det fortfarande några årtionden framåt\nkunde anses ”fegt att repetera”.\n   Signifikativt för Knut-Erik Jahnke var hans sista jordiska resa. Då ambulansen kom\nför att hämta honom efter en hjärtinfarkt envisades han med att ambulanspersonalen\nskulle leta reda på den portfölj, där han hade allt sitt Avisa-material. Han planerade ju\nför nästa utgåva av Avisa. Tyvärr varade planeringen bara något dygn, sen slutade det\nhjärta att slå, som i mer än 50 år bultat så varmt för Jönköpings Par Bricole i allmänhet\noch för Avisa i synnerhet. Knut-Erik Jahnke avled den 18 augusti 1990. Han var då\nRiddare av Svarta Korset och Jubelkommendör.\n\n\n\n\n                                                                                      51"}, {"pdfPage": 53, "printedPage": null, "text": "Dokument från gångna tider\n\nDe Gyllene Böckerna\nAtt undan vardagslivets besvär rädda några glada ögonblick i vänskapens famn, så\nlyder ett vackert gammalt talesätt inom Par Bricole. Men ögonblicken är just ögonblick\noch är snart förgätna. Men några ögonblick har räddats åt eftervärlden. Inom Jönköpings\nPar Bricole har ända från Sällskapets grundande samlats tal och skrifter, brev och be-\nrättelser m.m. inbundna i böcker med skinnomslag på pärmarna. I fem ”Gyllene Böcker”\nhar ett urval av Barbaratal, vårtal, parentationer osv. från 119 års bricolleri i Jönköping\nsamlats.\n   De Gyllene Böckerna förmedlar inte bara glimtar av gångna tiders talekonst utan\nockså intressant lokal personhistoria genom de ofta detaljerade parentationerna över\nbortgångna bröder. Tyvärr fattas dock parentationer för vissa perioder. Böckerna ger\noss också intressanta tidsbilder och en inblick i hur man tänkte anno dazumal. I äldre\ntider återkom ofta samma talare år efter år. Många av dessa var framstående vältalare i\ngammal akademisk tradition. Vi kan se hur katastrofer och svåra tider, som första och\nandra världskriget, påverkade talen. Vi kan också notera att många tal på ett annat sätt\nän idag speglar en kristen livssyn. Under en lång tid firades Martin Luthers minne varje\når med mycket långa och inte särskilt ”bricollistiska” tal.\n   I samband med Styrande Mästare Jan-Erik Berggrens 70-årsdag insamlades medel\noch instiftades en fond för att möjliggöra framställning av ännu en Gyllene bok. Akade-\nmin fick uppdraget och en mindre grupp bildades för arbetet. Den bestod av Gunnar\n\n\n\n\n                                                              De Gyllene Böckerna.\n\n\n52"}, {"pdfPage": 54, "printedPage": null, "text": "Åkerskog, Ragnar Jonsell och Harald Wigstrand, tillika sammankallande. Arbetet\nblev omfattande men också mycket intressant och framgångsrikt. Den femte Gyllene\nBoken, omfattande åren 1945 - 1997, kunde överlämnas till De Styrande vid Barbara-\ndagen år 1999. Därefter har arbetet med att samla material till en sjätte Gyllene bok\npåbörjats.\n   De Bröder, som gjort det möjligt för oss, att idag ta del av vår historia är\nDirektör Ernst L. Hartmann, Styrande mästare 1917 - 1928, som har sammanställt två\nGyllene Böcker för åren 1879 - 1927.\nCivilingenjör Gustaf Emil Lundholm, Riddare-Intendent 1937 - 1945, som har sam-\nmanställt två Gyllene Böcker för åren 1927 - 1944.\nSkogsmästare Jan-Erik Berggren, Styrande mästare 1983 - 1993, som tog initiativ till\natt sammanställa en Gyllene Bok för åren 1945 - 1997.\n   De Gyllene böckerna förvaras i Bellmanssalen, där den som vill kan sitta och studera\ndem. I framtiden är det tänkt att man i första hand skall kunna läsa och bläddra i kopior.\nF.n. har två Gyllene böcker kopierats. För säkerhets skull är Den Gyllene Boken 1945 -\n1997 försedd med följande besvärjelse:\n      Den som denna boken stjäl\n      Honom går det inte väl\n      Han skall äta halm och hö\n      Och på tredje dagen dö\n\n\n\nAvisa - En tidning i tre akter\n”Att undan vardagslivets besvär rädda några glada ögonblick i vänskapens famn”, så\ninleddes den allra första Avisa som utkom i december 1948. Initiativtagare var stadens\npopuläre skribent redaktören Ernst Greén. Han anade att utgivandet av en medlems-\ntidning i ett Ordenssällskap på 40-talet förmodligen skulle tas emot med blandade känslor\noch han skyndade sig därför att tillägga; ”Omkring Bricolls hus stryker kalmuckerna,\nett vrångt släkte med ful uppsyn och utan förmåga till glädje i sina hjärtan. Till dem har\ndetta blad inget ärende, de kan inte begripa dess mening”. Detta till trots var det många,\nsom protesterade när den första Avisa gavs ut och inte minst höjdes röster från Moder-\nlogen och från Systerloger, som menade, att det var olämpligt att i tryck förmedla Säll-\nskapets ”hemligheter”. Det var kanske därför redaktör Greén försvarade sin första ut-\ngåva med följande ord; ”Denna Avisa vill vara en sådan hälsning på samma gång som\nett föreningsblad inom sällskapet. Den vill då och då ge nyttiga besked, glimtar om\nsällskapets liv, växt och glada stunder. Med andra ord en nyttig och bra ”avis”. Stick\nden gärna i handen på någon bekant eller vän, som kan antagas ha lust att dela våra\nmödor och nöjen. Men låt kalmuckerna gå förbi tomhänta! Trots att P.B. är ett uteslu-\ntande maskulint sällskap, må avisan gärna läsas av damerna - de skall därav finna, att\n\n\n                                                                                       53"}, {"pdfPage": 55, "printedPage": null, "text": "brikolleriet är en hemvist för\n                                                       idealitet, humanitet och vidsynt-\n                                                       het... Flyg så ut, Avisa, till dem\n                                                       som har det rätta sinnelaget”!\n                                                          En medlemstidning i en för-\n                                                       ening är för modligen dess\n                                                       förenings historia eftersom det\n                                                       ofta är de mest betydelsefulla\n                                                       händelserna som det skrivs om.\n                                                       Avisa har getts ut i tre omgångar\n                                                       och berättar om viktiga händel-\n                                                       ser under tre epoker.\n\n                                                       Avisa 1948-1957\n                                                       Huvudredaktörer: Ernst Greén\n                                                       och Knut-Erik Jahnke\n\n                                                       Avisa 1980-1991\n                            DECEMB~:H 食ヽV• 1ユ\n                                                       Huvudredaktörer: Knut-Erik\n                                                       Jahnke och Gerhard Mattus\n\n                                                       Avisa 1996-\nPremiärnumret av Avisa.                                Huvudredaktör: Dan Ekström.\n                                                       F o m 2002 Bo Fjaestad\n\nAvisa speglar stora delar av Sällskapets verksamhet under tre tidsperioder, 1948 - 1957,\n1980 - 1991 och 1996 - 2004. För idé och utgivning för åren 1948-1957 bör vi förutom\nDe Styrande nämna redaktören Ernst Greén, Riddareintendenten Knut-Erik Jahnke och\nRiddareprelaten Tage Löf. Varför Avisa inte kom ut 1958 och de följande 23 åren har vi\ninte funnit något svar på. De första 12 numren av Avisa finns bevarade, dock är delar av\nnågra nummer sönderklippta, troligtvis av Knut-Erik Jahnke, eftersom de enda numren\nfrån den första perioden är de tidningar som fanns i hans dödsbo.\n\nJönköpings Par Bricole under jubileumsåren saxat ur Avisa.\n1879\nJönköpings Par Bricoles födelseår\n\nUtdrag ur Jönköpings Tidning i februari:\n”Den 1:sta dagen i denna månad hölls sammanträde rörande frågan om inrättande af en\nfilialloge af Par Bricole här i Jönköping. Detta var besökt af omkring 40 personer, alla\nför saken warmt intresserade. Det beslöts att ingeniör Karling skulle sätta sig i förbin-\ndelse med moderlogen i Stockholm och dessutom widtaga alla de förberedande åtgär-\n\n54"}, {"pdfPage": 56, "printedPage": null, "text": "der, wilka äro nödiga. För betäckande af omkostnaderna till den första uppsättningen\nfann man lämpligt, att hwar och en af de närwarande answarade för ett belopp af 25\nkronor. Stiftelsebrev utfärdades den 25 ds”.\n\n• H.M. Konung Oscar II fyller 50 år. Jönköpings P.B sänder telegram.\n• Jönköpingssonen Viktor Rydberg utnämns till riddare av Kungliga Nordstjärneorden\n\n1904\nJönköpings Par Bricole firar 25 år\n\n• Grännasonen, överingenjören och polarforskaren S. A. Andrée förklaras vid Stock-\n  holms rådhusrätt för rättsligt död.\n• Upptäcktsresanden Fil dr Sven Hedin introduceras som nr 2344 adliga ätten Hedin.\n  Hans vapensköld upphänges bredvid den senast introducerade ätten Pantzerhielm\n  (Gösta Pantzerhielm var Jönköpings Par Bricoles sjunde Styrande Mästare)\n\nI Jönköpings Tidning kunde man hitta följande annonser:\nStora Hotellet. Gåsamiddag, inkl snaps, öl, vin och kaffe. Kronor 6.\nAlphyddan i Stadsparken. Restaurant 1:sta klass.\nSmörgåsbord och 4 rätter. 2 Kr\nFest-Soupé. Kr 2:50\nKräftor levereras i större och mindre partier till 38 öre tjog mot efterkraf af Gustaf\nBolander, Braås.\n\n1929\nJönköpings Par Bricole firar 50 år. Det Lysande Sällskapet Jönköpings Par Bricole\nfirar sin 50-åriga tillkomst med pompa och festivitas i Stora Hotellets Spegelsal och\nHenrik Karnell installeras som Styrande Mästare.\n• Den värsta snöstormen i mannaminne drar fram över Jönköpingstrakten. Isbarriär på\n  bangården. Tågtrafiken inställd.\n• Författaren Birger Sjöberg avlider\n• Gränna får hembygdsmuseum i Franckska 1600-talsgården\n• Ljudfilmen har premiär i Sverige. I Jönköping visas ”Vilda orkidéer” med Greta\n  Garbo i huvudrollen. Filmen går på Biografen China som drivs av PB-brodern John\n  Weimer.\n• De småländska ”utvandrarna” besöker Småland och Jönköping och hälsas av Par\n  Bricoles manskör.\n\nI Jönköpings Tidning kunde man hitta följande annonser;\nGustaf Lorentz, Rak- o Frisérsalong. Shingel och Bobb. Pris 2 kronor. Särskilt Dam-\nrum.\n\n                                                                                    55"}, {"pdfPage": 57, "printedPage": null, "text": "Så mycket kostade det i Jönköping då:\nPrenumeration på Smålands Allehanda 13:-/Helår\nHyror: 2 rum och kök med värme och vatten. 300:-/År\n      5 rum och kök. 1.400:-/År\n\n1954\nJönköpings Par Bricole firade 75-års jubileum.\n\n   Under sedvanligt solenna former hölls i Brahesalen högtidssammankomst i närvaro\nav över 250 bröder samt representanter från Moderlogen i Stockholm och Systerlogerna\ni Göteborg, Vänersborg, Borås och Malmö. Sedan alla de Styrande under tonerna av\nPar Bricoles festmarsch införts av Generalceremonimästaren Mac Mattus och jubileums-\nhögtiden öppnats av Styrande Mästaren Gösta Pantzerhielm, höll Sällskapets Riddare-\nprelat och Talare Tage Löf högtidstalet. En till ett tidigare jubileum författad och tonsatt\nkantat, som omarbetats av Gustaf Lorentz och kantor Calle Carlsson, framfördes av\nden för dagen förstärkta orkestern och kören med bröderna Dustin och Helge Ottosson\nsom solister. Då Styrande Mästaren Gösta Pantzerhielm i och med jubileet avgick från\nsin post fick han av Stormästaren mottaga Par Bricoles högsta förtjänsttecken, den\nWesterstrandska medaljen. Sedan installationen av de nya Styrande, Anders Graab, Thure\nÖberg och John Koch ägt rum, avslutades högtiden i Brahesalen för att därefter fort-\nsätta med jubileumsmåltid i Stora Hotellets festsal. Högtiden blev ett gott och inspire-\nrande minne för det Lysande Sällskapet Jönköpings Par Bricole.\n\n1954\n• FN:s generalsekreterare Dag Hammarskjöld väljs in i Svenska Akademin som den\n  ende, som någonsin har efterträtt sin far (Hjalmar Hammarskjöld)\n• Konung Gustaf VI Adolf åker på Eriksgata. Den 10 september kl. 11.05 skakar Kon-\n  ungen hand med vår blivande Styrande Mästare C-W Lothigius i Örserum\n\nReferat från 75-årsfirandet saxat ur Avisa nr 9 1954\nNär Jönköpings PB den 4 april i år firade sitt 75-årsjubileum, hade allt av bricollistisk\ngrädda i Sveriges land infunnit sig i den småländska metropolen för att hedra och\nbevittna det celesta skådespel, som i samband härmed försiggick efter hävdvunna ritu-\nella ceremonier. Ett omfattande festprogram hade utarbetats och alla medagerande Bröder\nhade i detalj inövat sina roller. Resultatet blev också i stort sett mycket gott och fest-\nkommittén kunde dra sig tillbaka efter väl förrättat värv. Av de i jubileumsarbetet delta-\ngande Bröderna skall här särskilt omnämnas RI Knut-Erik Jahnke, GI Carl-Gustaf\nHörberg och Brodern Bernt Storm , vilka under ett årslångt förberedelsearbete nedlagt\nen avsevärd ospard möda. St.K. emeritus Malte Erichs hade signerat den jubileumsvin-\njett, som sedan blev en genomgående litografisk detalj. GCM Mac Mattus, som hade\nhaft en intensiv dag, kunde vid dess slut ånyo införa en framgång i protokollet. CM\nGerhard Mattus hade ansvaret för ordningens upprätthållande liksom också för proces-\n\n56"}, {"pdfPage": 58, "printedPage": null, "text": "sionerna, vilka vid ett tillfälle som detta givetvis äro många och komplicerade, ett upp-\ndrag, som han fullgjorde med precision och elegans. En särskild eloge bör slutligen\nriktas till körledaren Calle Carlsson och musikanföraren Melin med tack för konstnär-\nlig insats och effektfull påpasslighet. Jubileumsfestligheterna var uppdelade i ett hög-\ntidssammanträde, förlagt till Brahesalen i Per Brahe-gymnasiet och i ett måltidskalas,\nsom framdukats i Stora Hotellets festvåning. Sammanträdet i Brahesalen kunde inledas\nprogramenligt kl. 15 precis, vilket skedde med de högtidliga processionernas intåg. Det\nvar emellertid fullkomligt häpnadsväckande hur få Bröder av lägre grader som infunnit\nsig till denna unika och högtidliga del av programmet. Här i Brahesalen var antalet\nplatser obegränsat. Man frågar sig med oro, om intresset för Par Bricole verkligen är så\nstort, som antalet medlemmar låter förmoda. Sedan St.M. Gösta Pantzerhielm ritual-\nenligt öppnat logen och med några ord hälsat bröderna, framförde orkestern Sinfonia\nav Roman. Om Sinfonian är intet annat att säga än att den är mycket vacker och att den\ngenomfördes utomordentligt väl av orkestern och att den angav en välberäknad stäm-\nningsfull ton åt det jubilerande Sällskapets högtidssammanträde. Arrangörerna borde\ndock inte ha förbisett att i programmet ha angivit vilket musikstycke som spelades. Nu\nvar det ytterst få Bröder som kände igen musiken och troligtvis var det heller ingen som\nuppfattade det logiska sammanhanget mellan gustavianska tidens Par Bricole och 1700-\ntalskomponisten Roman. De andäktigt lyssnande Bröderna voro emellertid så gripna\nav musikens välljud, att de inte förmådde röra en hand till applåder vid Sinfonians slut.\nSå tystnade musiken och de bricollistiska klubbslagen dånade åter genom salen. D.St.M.\nAnders Graab reste sig och hyllade i några studentikosa ordvändningar den bricollistiska\nsläktgemenskapen. Han riktade sig till vördad Moder och till älskliga Systrar och\nslutade med att uttrycka lillflickans stolthet och glädje över att se den bricollistiska\nfamiljekretsen sluten vid detta lusteliga födelsedagskalas.\n   Så följde ett rätt teatraliskt inslag, i det en härold inträdde, förebådad av smattrande\nfanfarer. Med raska steg trippade denne gustavianskt kostymerade bricollist fram till\npodiet och uppläste Moderlogens stiftelseurkund för det Lysande Sällskapet Jönköpings\nPar Bricole, daterad den 14 april 1879. Effekten var ganska god, särskilt med tanke på\nden efterföljande programpunkten, som var högtidstalet. Det historiska tillbakablick-\nande innehållet i detta tal fick sin logiska introduktion genom häroldens meddelande\nom händelsen för 75 år sen och om det sålunda inträffade jubileet. Ordens Talare och\nSkald, RP Tage Löf, framträdde alltså med sitt anförande, som blev längre än beräknat.\nTalet präglades av stor konstnärlighet och var dessutom synnerligen innehållsrikt.\nTalaren ägnade sig till största delen åt den sista 25-årsperioden och framhävde de\nBröder, som under denna tidrymd särskilt verkat för P.B. här i Jönköping och han\nredogjorde för deras insatser. Namn som Henrik Karnell, Gösta Pantzerhielm, Malte\nErichs, Gustaf Emil Lundholm, Sixten Arensten och Knut-Erik Jahnke nämndes ofta\noch säkert var det ingen överdrift i det bestickande omdömet beträffande den nyligen\nupphöjde RI Jahnke när någon sade ”Riddareintendenten måste ha en mycket för-\nstående hustru”. Efter högtidstalet framfördes jubileumskantaten med solo, kör och\norkester. Det var krävande partier för de båda solisterna Helge och Dustin Ottosson,\n\n                                                                                        57"}, {"pdfPage": 59, "printedPage": null, "text": "men alltsammans fördes i hamn på ett utmärkt sätt under Calle Carlssons säkra ledning.\n    Uppenbarligen låg ett betydande förarbete bakom och det fordrades stor yrkesskick-\nlighet att genomföra det hela. Kantaten har framförts vid tidigare jubileum. Texten var\nvid detta tillfälle helt omarbetad av Gustaf Lorentz. Därmed var jubileumshögtidlig-\nheterna framme vid sin höjdpunkt. Stormästaren Gösta Söderberg framträdde och\nhyllade den småländska dottern. Han gratulerade till de lyckosamma framfarna 75 åren\noch uttryckte Moderlogens förhoppning om ett fortsatt gott bricollistiskt arbete i\nJönköpings PB. Stormästaren skildrade några historiska forskningsresultat, vilka\navslöjade ett tidigt försök att upprätta en PB-loge här nere i Småland redan innan Moder-\nlogen hunnit få lagstadgad form i Stockholm. En annan talare berörde vid ett senare\ntillfälle under kvällen denna revolutionerande nyhet, varvid han uttryckte sin stora\ntillfredställelse över naturens sinne för ordning genom att inte låta Modern vara yngre\nän sin dotter.\n    Avslutningsvis överlämnade Stormästare Gösta Söderberg trenne antika vinglas av\nsällsynt skönhet. Därefter framträdde St.M. i Göta Harry Lindberg, som på systerlogernas\nvägnar överlämnade en ordförandeklubba i silver och ebenholts. Lindbergs tal var ut-\nomordentligt elegant och härligt spirituellt. Broder Lindbergs vältalighet belönades med\nen spontan applåd (den första för dagen!). Sist i raden av gratulanter var ordföranden i\nBacchi Börn från Köpenhamn, Eric Weilskov, som på sitt välgörande gemytliga dansk-\nsvenska tungomål hyllade jubilaren och överlämnade en originell statyett i dansk kera-\nmik. Därmed var den första delen av jubileumsfestligheterna slut och nu vidtog en\nannan ceremoni. St.M. Gösta Pantzerhielm tog av sig sina Mästarinsignier och Stor-\nmästaren Gösta Söderberg insatte nya Styrande i sina ämbeten vid Jönköpings Par\nBricole, St.M. Anders Graab, D.St.M Thure Öberg och som St.K. John Koch.\nDärmed var högtidligheterna i Brahesalen till ända och en halvtimma senare satt\nBröderna samlade kring de festligt dukade borden i Stora Hotellets festvåning. Den\nglada och den uppsluppna delen av jubileet tog vid och utanför den fastställda ritualen\nhöjdes ett flertal skålar, tal på vers och prosa. Telegram upplästes från H.M. Konungen.\nSången och musiken klingade med ett välljud, som man förmodligen aldrig tidigare\nhört i Stora Hotellets festvåning. Fram emot midnatt var det omfattande programmet\ngenomgånget. Många Bröder fortsatte sitt muntra tidsfördriv vid nattsexan, varvid\ndagens händelse stöttes och blöttes och kritiserades. De erfarenheter som gjorts, goda\nsom dåliga, får nu läggas till handlingarna, till ledning och glädje för den kommitté,\nsom får hand om P.B:s 100-årsjubileum år 1979.\n\n1979 Jönköpings Par Bricole firade 100-årsjubileum.\nJönköpings Teater strålade med en glans, som förde tankarna tillbaka till gångna tider.\nMed pompa och ståt, men under muntra och angenäma former firade Jönköpings Par\nBricole sitt sekularjubileum. Hundra år i ett historiskt perspektiv är inte särskilt impo-\nnerande, men hundra år av sällskaplig samvaro, som överlevt tidens strömningar och\nfortfarande lockar människor av skilda åldrar, det är i dag något unikt. Jubileums-\nprogrammet inleddes med en presentation av gäster från moder och systerloger. De\n\n58"}, {"pdfPage": 60, "printedPage": null, "text": "Arne Linnarsson som ”Bacchus på Tunnan”      Anders Ruberg som ”Bacchus på Tunnan”\n1960-tal.                                    1970-tal.\n\nordensprydda frackarna bländade den förväntansfulla brödrapubliken, för att inte tala\nom de hustrur och väninnor som trängdes på balkongerna. En brilliant historik framför-\ndes av Broder John Koch (se särskilt stycke). Den omspände tiden från det gustavian-\nska 1700-talet fram till dags dato och illustrerades med hjälp av PB-teaterns skåde-\nspelare i korta scener där Lars och Anders Ruberg på sitt oefterhärmliga jönköpings-\nidiom samtalade med en stockholmsk lutsjungande trubadur i Sune Winalds skepnad.\nSamtalet mynnade ut i den typiska slutrepliken: ”Den dö! Han va la inte veti”. I nästa\nscen sjöng Hugo Ramsten och Bo Berntsson duetten ur Mozarts Don Juan med speci-\nalskriven text. Anders Ruberg återkom som den unge Bacchus dragen på en stor tunna\nvarefter den historiska kavalkaden avrundades med Bo L Spångs hornsolo ”Vila vid\ndenna källa”. Spelet på scenen leddes på sedvanligt perfekt sätt av Generalceremoni-\nmästaren Gerhard Mattus (sedermera Styrande Kansler) och den Bacchanaliska kören\noch musiken gav den Bellmanska inramningen utan vilken inget bricollerikalas är\nfullödigt. Efter teatern samlades bröderna på Stora Hotellet i dess Spegelsal där spiri-\ntuella tal, omväxlande med solosång, flödade och PB-kören som så många gånger förr\ntycktes överträffa sig själv i sitt framförande.\n\n\nJönköping 1879-1979. Högtidstal av Broder John Koch\nJönköpings Par Bricoles 100-årsjubileum 1979.\n(J.Koch var St.K 1954-1964)\n\n   Året 1779 har en sällsam klang för varje upplyst Bricollebroder. Och den som vet att\nfölja med sin tid, vet också att Par Bricoles 200-årsjubileum firades med utomordentlig\nståt och pompa i vår vördade Moderloge den 12 maj 1979 i Stockholms vackra stads-\n\n                                                                                     59"}, {"pdfPage": 61, "printedPage": null, "text": "hus i Majestäters höga glans. Men hur såg\n                                             månne Jönköping ut 1779? Det kan sägas\n                                             mycket kort och utan omsvep: en liten obe-\n                                             tydlig bondhåla med icke fullt 3000\n                                             invånare, kippande efter andan, på grund\n                                             av en lång rad av epidemier i tät följd så-\n                                             som kolera, pest, svartsot, rödsot osv., och\n                                             därtill helt ödeläggande eldsvådor. Något\n                                             underlag för bricollistiska, andelyftande\n                                             tidsfördriv fanns förvisso ej. Icke dess min-\n                                             dre har ur källor framkommit att Det Ly-\n                                             sande Sällskapet Par Bricole mycket väl\n                                             kunde ha fått sin födelseort just här i den\n                                             fagra Vätterbygden. Och att så icke blev\n                                             fallet, torde ha berott på en ren tillfällig-\n                                             het. En viss tacksamhet bör emellertid till-\n                                             skrivas ödet härför. Det är väl knappast tro-\n                                             ligt, att Par Bricole skulle ha överlevt ti-\nJohn Koch högtidstalar vid 100 årsjubiléet.  dernas strömningar, sådana som under\n                                             1800-talet svepte fram över Jönköpings län\noch över Smålands Jerusalem. Jönköping är och var beläget vid den urgamla kungs-\nvägen, som leder söderut från Djurgården och Haga, från Fiskartorpet och Urväders-\ngränd. Då och då drog resenärer förbi, de flesta snabbt skyndande förbi. Några\nämbetsmannafamiljer slog sig dock ner vid Hovrätt eller Länsstyrelsen. En och annan\nhantverkare, mest invandrare, stannade kanske för gott. För övrigt livnärde sig befolk-\nningen, den övervägande delen, huvudsakligast på snustillverkning. Någon enstaka gång\nkom även en vandrande trubadur förbi, stannade till för ett ögonblick, antingen vid\nvindbron eller kanske ute vid Österbrunn, ett kärt och mycket uppskattat tillhåll, något\nav ett Djurgården för samtida Stockholmare.\n   Så vandrar Jönköpingsbygden vidare och når så småningom in i 1800-talet, som\nonekligen skapade ljusare tider för folk och stad. Icke så att eldsvådorna upphörde, nej\ndå, eller att svåra epidemier försvann, ack nej! Förödande härjningar av allehanda slag\ndrabbade staden av och till. Men ändå. Förhållandena förbättrades enormt. Göta kanal\nbyggdes, järnvägen drogs fram genom nejden, tidningarna började utgivas, till och med\nett teaterhus uppfördes, dock inte det nuvarande, och slutligen men inte minst det vik-\ntiga i sammanhanget. Stora Hotellet kom till. (Från början hette det Jönköpings Hotell.\nNamnet ändrades någon gång kring 1890-talet. Red:s anm.) Och när vi kommer fram\nmot 1870-talet var icke mindre än ca 7000 mantalsskrivna inom själva stadsförsamlingen.\nDet började nu dyka opp personer i staden, som inför minsta förevändning visade sig\nförete tecken på vad man sedermera skulle vilja kalla - bricollistiskt sinnelag. Och\nplötsligt, en bister januaridag år 1879, sammanträffar av en tillfällighet - par bricole -\ntvenne glada herrar på en servering i staden. Efter några inledande artighetsfraser av-\n\n60"}, {"pdfPage": 62, "printedPage": null, "text": "slöjar sig de båda herrarna vara ivriga och intresserade Bricole-Bröder från Borås, ny-\ninflyttade till Jönköping, den ene som nyutnämnd postmästare, Paul Billing, den andre\nlikaledes nyanställd, som ingenjör, Jonas Karling. Den januaridagen blev betydelsefull\nför det lysande bricolleriet här i södra Vätterbygden. De båda herrarna kom överens om\natt här i Jönköping söka starta en filialloge av Par Bricole. Och redan den 25 februari\n1879 förelåg Stora Konseljens höga beslut och stiftelsebrevet undertecknat av Moder-\nlogens Stormästare i Stockholm. Den 14 april 1879 förrättades invigningen av Jönköpings\nPB. Carl Friedländer, brukspatronen på Stensholm och Ebbes bruk, blev Sällskapets\nförste Ordförande Mästare som det hette på den tiden. Innan året 1879 hade gått till\nända, hade samtliga Par Bricoles arbetsgrader givits. Moster Barbara visade sig för\nförsta gången inför Jönköpingsbricollisterna på Barbaradagen den 6 december och lät\nsig hyllas.\n   100 år efter det första bricolleriets tillblivelse 1779 i Stockholm hade alltså nu också\nSmåland begåvats med sitt Lysande Sällskap. Tidigare under 1800-talet hade minsann\nVästergötland blivit synnerligen gynnat av den Milde Faderns välvilja med inte mindre\nän tre filialloger, i Göteborg, Vänersborg och Borås. Och nu senast, året före Jönkö-\nping, nämligen 1878 hade Malmö fått sin. Ytterligare försök hade gjorts på skilda håll.\nOch för 25 år sedan (1954) hade vi minsann ett Bacchi Börn i Köpenhamn, som även\nde voro våra gäster vid vårt 75-årsjubileum.\n   Att uttrycka sig som så att Bricoles öden är dess Styrande Mästares, vilket man ju\nbrukar säga om Sverige och dess konungar, det är ett talesätt, som knappast skulle\nkunna hålla streck. Vårt Sällskaps Lysande uppgångsperioder, liksom mörka depressions-\ntider, är säkerligen att knyta till enstaka medarbetares förmåga eller bristande förmåga\natt skapa något lockande till Brödernas bästa av Sällskapets oändligt stora begivenhe-\nter. Möjligen kan sägas, att oinvigda Mästare med föga bricollistiskt sinnelag utövat\nhämsko på glada och muntra tidsfördriv, liksom att strålande eldsjälar med nära släkt-\nskapsförhållande till Den Milde Fadren, kunnat inspirera talanger till oanade prestatio-\nner inom bricolleriets förgårdar och inom dess inre planering. Vid en tillbakablick gör\nman några reflektioner.\n   Troligtvis har den förste Styrande Mästaren haft enormt stor betydelse för Sällska-\npets befästande under de första 10 åren här i Jönköping. Men den som f ö kanske var\nden som gjorde PB under åren fram till sekelskiftet, var säkerligen Jonas Karling,\nboråsaren, Riddarceremonimästare från första början och faktiskt ända fram till 1923.\nEn otrolig prestation (44 år). Annars är det enligt min uppfattning, Ordförande och\nCeremonimästare i Arbetsgraderna, som har varit och alltjämt är de allra viktigaste\npersonerna, vilka skapar den atmosfär inom Sällskapet, som i sin tur ger stimulans åt\nhela Par Bricole. Förutom Jonas Karling kan nämnas Henrik Karnell, Helge Kolthoff,\nCarl-Gustaf Roos af Hjelmsäter, Gösta Pantzerhielm, Nils-Erik Rodling (en gudabenå-\ndad CM, alltför tidigt bortgången) samt Gerhard Mattus. Att en eldsjäl som Henrik\nKarnell, i alla de ämbeten han beklätt, haft en oerhörd betydelse för Sällskapet, är väl\nställt utom allt tvivel. Utan överdrift kan sägas, att han under sin krafts dagar, höjde den\nbricollistiska nivån till toppen av det möjliga. Stor betydelse har naturligtvis också\n\n                                                                                         61"}, {"pdfPage": 63, "printedPage": null, "text": "andra enskilda bricollister haft under de gångna 100 åren. Intendenter som Ludvig\nWahlin, Gustaf-Emil Lundholm, Knut-Erik Jahnke och Yngve Lovrin. Sånganförare\nsom Olof Emil Lindegren, Josef. A. Jacobsson och Calle Carlsson. Och orkestern, vad\nvore vi utan den, framför allt en dag som denna, men självklart också vid bricolleriets\nvardagsarbete. Den Bacchanaliska Teatern får för ingen del glömmas i denna historie-\nskrivning. Skämtens kvalitativa nivå, liksom definitionen av humor skiftar betydligt\ngenom åren. Tydligen har svårigheter förelegat under gångna år, men trots det synes\nbricolleriets s.k. ”spexaftnar” ha varit de mest bidragande krafterna att viktmakthålla\nglädjen inom Sällskapet under de skiftesrika 100 åren. Därför bör en särskild eloge\nriktas till samtliga arbetsamma teaterdirektörer, ingen speciellt nämnd, men heller ingen\nglömd. Dock må det tillåtas mig att göra ett undantag: Gustaf Lorentz har deltagit i\nteaterns arbete i 60 av dess 100 åriga historia och han finns där minsann ännu idag.\n(Svårigheterna som John Koch talar om syftar förmodligen på att flera förgrundsge-\nstalter inom teatern blev mindre aktiva i Sällskapet, när de valde att starta Sällskapet\nKommunalskratt i Jönköping, idag en etablerad revyförening som ger över 40 föreställ-\nningar varje år på Jönköpings teater. Red:s anm.)\n   Vältalande ordensskalder har funnits många. Vår första Ordens Talare och Skald var\nAxel Printzensköld, Jönköpings borgmästare vid tiden för instiftandet 1879. Efter ho-\nnom kom apotekaren Carl Falk och senare under många år läroverkslektorn Oscar von\nPorat. En annan av de stora talarna var under 20-, 30- och även 40-talet redaktören\n                                             Ernst Greén. I och med att kyrkoherde Tage\n                                             Löf, den store poeten och stilisten åtog sig\n                                             att vara Ordensprelat, tillika Ordens Talare\n                                             och Skald, inleddes den period som är för-\n                                             härskande, då våra högtidliga parentationer\n                                             kunde hållas i kyrkan. Bland idogt verk-\n                                             samma bröder, ivrigt och framgångsrikt på-\n                                             tande i Den Milde Fadrens Vingård, skall\n                                             ännu en broder nämnas. Till följd av svår\n                                             konkurrens från tongivande massmedier har\n                                             stora krav kommit att ställas på den\n                                             Bacchanaliska kören. Berättigade förhopp-\n                                             ningar om en god bricollistisk klang i sången\n                                             tycks kunna ställas på den nuvarande sång-\n                                             anföraren, Hugo Ramsten. Må han ej för-\n                                             tröttas. Det låter bricollistiskt skönt när han\n                                             leder sin kör. Bricollistiskt känns det även-\n                                             ledes när han ackompanjerar vår guda-\n                                             benådade Ordensbalettmästare Hans Svartz.\n”Bacchus på Tunnan” utformad till 75-års-       När nu därför alla Milde Faderns goda\njubiléet av Malte Erichs O och St.K under    krafter, alltifrån det gångna seklets fram till\nmitten av 1940-talet.                        nuets ekande pelargångar, församlats denna\n\n62"}, {"pdfPage": 64, "printedPage": null, "text": "jubelstund, i kretsen av en älskad Moder, liksom kära Systrar, då manar jag till festlig\nfröjd och gamman, att efter traditionens ordning höja våra breddade festpokaler. Träd\nin du vinets vackre gud, vi väntat länge nog att våra strupars törst utsläcka med Bacchi\nbästa brygd!\n\nDokumentation i Avisa\nUnder Jubileumsåret 1979 beslöts att festligheterna skulle dokumenteras i en Avisa och\nskickas till samtliga Bröder. Det var Knut-Erik Jahnke och Gerhard Mattus som ge-\nnomförde detta. I mitten på 80-talet tillbringade Knut-Erik många och långa dagar och\nkvällar på Tändsticksområdet och företaget Kreativ Reklam som ägdes av PB-bröderna\nPeter Hult och Claes Ljungström. Det lär ha gått åt en och annan whisky vid dessa\nträffar, men vad gör det, Avisa var pånyttfödd och skulle komma med 16 nummer under\n11 år. Nummer 16 kom ut 1990. Charles Petruson gjorde ett försök i början av 90-talet\natt återuppväcka tidningen och gav ut ett lösnummer som han kallade: Avisa - ett\nlösnummer - det var som 17. Det visade sig dock vara svårt att hitta en lämplig redaktör\nefter Knut-Erik Jahnke. Gerhard Mattus drog ett ganska tungt lass men hade svårt att\nhinna med Avisa eftersom han också var Styrande Kansler. Nummer 17 blev bara ett\nlösnummer och det skulle dröja till 1995 då nästa steg togs i Avisans historia. Jan-Erik\nBerggren, Styrande Mästare emeritus hade tagit initiativ till bildandet av Jönköpings\nBacchanaliska Akademi och en av Akademins uppgifter som Berggren såg det, var att\nfå igång utgivandet av Avisa. En vinterdag\n1995 inbjöd Jan-Erik Berggren Leif\nThor, som var ledamot av Akademin och\nArbetsgradernas Ordförande Dan Ekström\nför att samtala omkring Avisas framtid. Vid\ndetta möte beslöts att det skulle bildas en\nredaktionskommitté med Dan Ekström som\nhuvudredaktör. Leif Thor skulle ansvara för\nekonomi, Peter Hult på Kreativ Reklam för\ntryck och Fredrik Bonde skulle stå för bil-\nderna. Detta var startskottet till en ny tid\noch ett nytt format på Avisa, som nu kom\natt tryckas i fyrfärg och ha formen som en\nkvällstidning. Reaktionerna var delade.\nMånga tyckte det var svårare att förvara\nAvisa men idén med det nya formatet var\natt den skulle ligga framme och fungera\nmer som en kvällstidning.\n   Avisa kom med sitt första nummer 1996                   BRICOLE•戸:.~    ”..ょ℃••ニ\n                                                                           9●纏~n\n\n\n\noch har sedan dess kommit en gång per år,\nett par år vid två tillfällen. Kreativ Reklam\n                                               Avisa i nytt stort tabloidformat.\nhar genom Bröderna Peter Hult och Claes\n\n                                                                                      63"}, {"pdfPage": 65, "printedPage": null, "text": "Ljungström ställt upp med stor generositet och ställt resurser och tryckpressar till Säll-\nskapets förfogande. Sen 2002 har Bo Fjaestad tagit över som huvudredaktör och sam-\nordnare och numera är skribenterna både många och flitiga. Avisa speglar fortfarande\nSällskapets arbete, utan att för den skull avslöja några hemligheter enligt Ernst Greéns\nförord till den allra första Avisa som gavs ut 1948. I 28 år har Avisa ”flugit ut till dem,\nsom har det rätta sinnelaget”.\n\n\nSällskapets handlingar\nJönköpings Par Bricoles samlade tal och skrifter, medlemsregister, kallelser,\ninbjudningar, protokoll, årsredovisningar, brevväxlingar mellan enskilda medlemmar\noch loger m.m. har under årens lopp samlats i huvudsak i Ordenskansliet. Åtskilligt\n                                                  material fanns - och finns sannolikt\n                                                  fortfarande - i tidigare tjänande Bröd-\n                                                  ers bostäder, på vindar och i källarut-\n                                                  rymmen. Det fanns ett stort behov av\n                                                  att samla, registrera och katalogisera\n                                                  materialet. Ordensbibliotekarien Ha-\n                                                  rald Wigstrand och hans medhjälpare\n                                                  Bröderna Ragnar Jonsell och Gunnar\n                                                  Åkerskog har ägnat mycket av sin fri-\n                                                  tid till att sortera, läsa och dokumen-\n                                                  tera en mängd handlingar. Numera är\n                                                  alla kända äldre handlingar arkiverade\n                                                  och katalogiserade i Jönköpings läns\n                                                  folkrörelsearkiv, beläget i Jönköping.\n                                                  I Ordenskansliet finns handlingar som\n                                                  är högst 10 år gamla. De yngre, mer\n                                                  aktuella finns i själva Kansliet och de\n                                                  något äldre i husets källare.\n                                                     De flesta böckerna på Kansliet har\nGunnar Åkerskog visar noter från körens tidiga år registrerats och finns nu i biblioteks-\nför andra arkiv- och jubileumsboks-kommitterade:  skåp i Bellmanssalen. Kompletterande\nF. v. Harald Wigstrand, Ragnar Jonsell och Eric   inköp har gjorts av bl.a. Bellmans-\nHaglund i Folkrörelsearkivet år 2004.\n                                                  sällskapets samlade skrifter. Äldre fo-\n                                                  tografier håller på att ordnas årsvis och\nförses med en förklarande text med uppgifter om tidpunkt, plats och avbildade personer\nmed namn och funktion inom Sällskapet. Detta värdefulla arbete genomförs av med-\nlemmar i Arkiv X, varvid särskilt skall nämnas åldermännen Lars Löfstedt och Bror\nNätt.\n\n\n64"}, {"pdfPage": 66, "printedPage": null, "text": "Sällskapets rum och salar\n\nDe lokaler som Det Lysande Sällskapet Par Bricole har brukat under sin 125 - åriga\nverksamhet har i första hand funnits på Stora hotellet. Under årens lopp har även andra\nkommit att tas i anspråk om än i mer begränsad omfattning. Under de första åren var det\ngamla Stadshuset vid Hovrättstorget en samlingsplats. Gradgivningar har även ägt rum\ni Rådhuset. Idag används de egna lokalerna på Östra Storgatan 6 för många samman-\nkomster. Då rummen där inte rymmer några större grupper äger de flesta större sam-\nlingar numera rum i Stora Hotellets lokaler. Vid receptioner för högre Grader har, sär-\nskilt under de senare åren, en rad andra lokaler använts. Det har dock varit mer tillfäl-\nligt. De miljöer, som haft den största betydelsen för Sällskapet och som här kommer att\nbeskrivas, är därför Stora Hotellet och det gamla ”Stadshuset”, som brann ned 1965.\n   Stora Hotellets festvåning har i över 140 år varit Jönköpings och länets förnämsta\nfestlokal.\n   Hotellet har kunnat erbjuda en magnifik ram för festligheter av skilda slag. Redan på\n1860-talet firades i samband med järnvägens invigning en storslagen fest. Festlighe-\n\n\n\n\nStora Hotellet. Under 1800-talet var namnet Jönköpings Hotell. Hotellet avbildas från sydväst\nmed Hamnkanalen och dåvarande Järnbron i förgrunden. Träsnitt publicerat i Svenska\nFamiljejournalen 1874 efter teckning av Emil Libert. Foto: Jönköpings läns museum.\n\n\n                                                                                                65"}, {"pdfPage": 67, "printedPage": null, "text": "terna fortsatte genom åren med Oscarsbaler och med baler och middagar vid andra\nhögtidliga tillfällen. Ramen var magnifik med gnistrande kristallkronor upplysta av\nflammande gas, spegelväggar som gav illusion om bakomliggande rum och dekoratio-\nner som förflyttade besökaren till en slottslik miljö!\n\n\n\nStora Hotellet\nStora Hotellet eller Jönköpings Hotell, som det först kallades, är ett av landets äldsta,\noch mest kända hotell utanför huvudstaden. När det byggdes i slutet av 1850-talet var\ndet en mycket stor satsning. Då det öppnades 1860 räknades det till de största i landet.\nStadens strategiska läge som vägknutpunkt, näringslivets expansion, den planerade järn-\nvägen, där Jönköping blev övernattningsstation på den sedermera färdigställda Södra\nstambanan var anledningar till detta storslagna hotellbygge.\n    Hotellet uppfördes efter ritningar av arkitekterna Helgo Zetterwall och Birger\nOppman. Oppman var den ansvarige medan Zettervall, som senare skulle bli en av\nlandets mest kända arkitekter, vid denna tid ännu var elev och därför inte fick signera\nritningarna. Han har tidigare inte heller omnämnts i samband med bygget. Stilen kan\nkaraktäriseras som en blandning av olika klassiska stilar. Renässans- och barockmotiv\när de dominerande inslagen. De ursprungliga fasaderna är i stort bevarade, förutom att\nvindsvåningen fått större fönster och att mellanvåningens fönster gjorts lägre. Husets\nfärg var från början gul. Den nuvarande röda färgen tillkom år 1960.\n    Hotellet inrymde redan från början en rad funktioner. I bottenvåningen fanns\nrestaurangrum, schweizeri, biljardrum, gästgiveri, banklokaler och en badanläggning.\nMellanvåningen upptogs till största delen av resanderum och den översta våningen av\nfestlokaler, klubbrum och några resanderum. I vindsvåningen hade då som nu frimurarna\nsina lokaler med bl.a. den stora ordenssalen, kallad S:t Johannessalen.\n    Under årens lopp har många förändringar genomförts. Det gäller främst lokalerna\n i bottenvåningen. Den stora huskroppen mot norr, som idag inrymmer en restaurang i\nbottenvåningen och i huvudsak resanderum i de övre våningarna, stod klar år 1932.\nPå denna del av tomten låg fram till 1920-talets slut den välkända hotellträdgården,\nsom anlagts redan när hotellet byggdes.\n\nFestvåningen och Spegelsalen\nDen ur kulturhistorisk synpunkt mest intressanta och bäst bevarade delen av hotellet är\nfestvåningen belägen två trappor upp. Den stod klar 1864 och ingick från början i en\nännu större svit av salar. Spegelsalen, som upptar en stor del av byggnadens mittparti,\när en av landets bäst bevarade festsalar från 1800-talets mitt. Den ritades av arkitekten\nJohan Fridolf Wijnbladh från Örebro. Han gav salen en rikt dekorerad dräkt. Stilen är\nnyrenässans, som var tidens främsta modestil. Formerna bygger på arvet från den gre-\nkiska- och romerska antiken, som vid medeltidens slut togs upp igen främst av de ita-\n\n\n66"}, {"pdfPage": 68, "printedPage": null, "text": "Stora Hotellets Spegelsal vid Barbarahögtiden under sent 1990-tal.\n\n\nlienska arkitekterna under renässansen. Det var en pånyttfödelse av de antika idealen\noch nyrenässansen var den nya pånyttfödelsen under 1800-talet.\n   Spegelsalens väggar är indelade i stora fält, som avdelas av pilastrar. De kan sägas\nvar kolonner som tryckts samman och placerats intill en vägg. Pilastrarna bär upp den\nkraftiga takfrisen och taklisten. Dessa bär i sin tur upp det väldiga taket med sin stora\nplafond där de stora dekorationsmålningarna är utförda.\n   Alla dörrarna och de fyra stora speglarna på salens kortsidor har kraftfulla\nomfattningar, vilka kan ses som små triumfbågar. De stora speglarna ger ett starkt\nillusoriskt intryck av att salen fortsätter - ja nästan in i ett oändligt perspektiv. På den\nsödra sidan finns en mindre musikläktare med ett räcke i gjutjärn, men någon fast scen\nhar inte funnits. Den strategiskt placerade balkongen har på grund av salens svåra akus-\ntik inte kunnat användas som det var tänkt. Uppvärmningssystemet utgjordes från bör-\njan av varmluft. Därför har det aldrig varit några kakelugnar i salen.\n   Salens väggar var, liksom idag, ursprungligen målade i en marmorimitation, men\nhade då en ljusare färgskala än i nutiden. De första dekorationsmålningarna i taket, som\nvar av enklare slag än idag, utfördes som gesällarbete av den senare kände konstnären\nNils Forsberg. Redan från början utrustades salen med de stora kristallkronor, som\nlyste upp salen med hjälp av gas. Det var då en stor nymodighet.\n   Salen målades om år 1903 i en mörkare färgskala. Då tillkom den nuvarande plafond-\nmålningen i taket, utförd av konstnären Vilhelm Holmgren, liksom vapensköldarna\n\n\n                                                                                         67"}, {"pdfPage": 69, "printedPage": null, "text": "utmed väggarna. Holmgren anställdes år 1889 som lärare vid den lägre tekniska skolan\ni staden. Han fick med åren många uppdrag i Jönköping. I början av seklet målade han\näven stora dekorationsmålningar i hotellets café. Holmgren har bl.a. målat en mängd\nporträtt över stadens fäder. Porträtten hänger i Rådhuset. Han har också gjort dekorations-\nmålningar i Stugan i Stadsparken och de stora målningar, som hänger i hallen utanför\nBrahesalen på Per Brahegymnasiet. Målningarna visar stadens äldre skolor. Festsalens\nmålningar restaurerades senast inför Jönköpings 700- årsjubileum 1984.\n    Dekorationsmålningarna i taket, som visar blomsterbärande kvinnogestalter, är in-\nspirerade av den då rådande jugendstilen. Vapnen över huvuddörrarna är Götalands och\nSmålands. Vidare finns över dörrarna mot väster till den Röda salongen en rad målade\nvapen över Smålands dåvarande residensstäder Jönköping, Växjö och Kalmar samt\nJönköpings läns dåvarande övriga städer Eksjö och Gränna.\n    Spegelsalens golv var från början ett brädgolv. Den nuvarande ekparketten tillkom\nvid 1900-talets början. Möbleringen har bestått av lätt flyttbara stolar, bänkar och bord.\nFrån början fanns längs salens sidor podier, där det stod långa stoppade bänkar. Några\nsådana bänkar finns ännu kvar på andra platser i hotellet. Den nuvarande uppsättningen\nav stolar av betsat trä i klassisk chippendalestil tillkom på 1930-talet och har omsorgs-\nfullt renoverats.\n    Den intilliggande Röda salongen utgör en väsentlig del av festvåningen och idag\nfinns norr om denna även den Blå salongen. Röda salongen kallades tidigare för Dam-\nsalongen och är välbevarad. Den har inte haft en lika påkostad inredning som Spegel-\nsalen, men har varit dekorerad med förgyllda speglar. Tidigare stod även några stora\nförgyllda karmstolar placerade i dess fond.\n    Den storslagna festvåningen med den välbevarade och rikt smyckade Spegelsalen\nhar ända sedan slutet av 1800-talet varit Det Lysande Sällskapets Högtidssal. En mer\nmagnifik inramning för detta ändamål är svår att tänka sig. De, som vuxit upp i staden,\nhar egna minnen från Spegelsalen i form av dansskoleavslutningar, studentbaler, firma-\nfester eller andra evenemang av skilda slag. För alla dem, som i skilda sammanhang\nfår uppleva en festkväll i Spegelsalen, ger själva salen oftast ett bestående minne och en\npåminnelse om de dekorationsideal, som bär på mångtusenåriga traditioner.\n\n\n\n”Stadshuset”\nUnder 1700-talets slut och under 1800-talets förra hälft skaffade sig ståndspersoner\noch det högre borgerskapet tillgång till samlingslokaler med utrymme för både vardag-\nligt umgänge och stora fester, så kallade assembléer. De bildade olika typer av Sällskap\noch skaffade sig även egna byggnader med i en del fall storslagna lokaler. Dessa kunde\nbenämnas Societets-, Assemblé-, Stads- eller Spektakelhus.\n   Det Stedtska huset vid Hovrättstorgets västra sida var sedan slutet av 1700-talet den\nstörsta privata gården i staden. Den ägdes 1818 av landshövding Boijes änka och hon\n\n\n68"}, {"pdfPage": 70, "printedPage": null, "text": "Stadshuset vid Hovrättstorgets västra sida bakom Gamla Rådhuset var byggt på 1780-talet och\nbrann ned 1965. Detta hus kallades ”Stadshuset” under 1800-talets senare del och 1900-talets\nbörjan. Det inrymde då bland annat restaurang, samlingslokaler och café. Foto omkring 1900.\nFoto: Rylanderska fotosamlingen, Jönköpings läns museum.\n\nville sälja fastigheten. När detta blev känt beslöt en vänkrets att bilda ett bolag för att\nköpa in huset. Bolaget fick snart sitt officiella namn: ”Assemblée- och stadshusbolaget”.\nByggnaden kallades senare ”Stadshuset”.\n   Gårdarna, som låg på denna dubbeltomt, Torg kv 17-18, hade brunnit ned vid den\nstora stadsbranden 1785. Tomten inköptes 1788 av majoren, tillika bruksägaren och\nsedermera landshövdingen Johan Axel Stedt, som lät bygga upp den stora gården. Stedt\nvar även en tidig medlem, nummer 38, i Par Bricole i Stockholm, långt innan Säll-\nskapets etablering i staden. Då Stedts gård ansågs som stadens förnämsta uppläts den\näven som logi åt kungliga personer.\n   År 1801 utnämndes J A Stedt till landshövding. Gården kom därefter att tjäna som\nresidens i staden, även när familjen Stedt officiellt bodde på landshövdingegården Ryhov\nutanför staden. Där avled han 1805 och 1806 inköptes gården vid torget av hans efter-\nträdare landshövdingen Eric Gustav Boije. Funktionen var under dennes landshövdinge-\ntid samma som tidigare fram till hans frånfälle 1815. Hans änka hyrde senare ut lokaler\nför offentliga föreställningar. Gården fick härigenom efterhand en allt tydligare prägel\nav offentlig byggnad, trots att den var i privat ägo.\n\n\n                                                                                               69"}, {"pdfPage": 71, "printedPage": null, "text": "Dess läge vid hörnet av Storgatan och Torget gjorde att den räknades till stadens\nmest värdefulla tomter. Här uppfördes under åren 1788-1790 flera stora byggnader,\nsom tillsammans med några senare tillbyggnader brann ned 1965. Vem som var bygg-\nnadernas arkitekt och vem som var ansvarig byggmästare är okänt. Gatuhuset bestod av\ntvå våningar. Fasaden var slätputsad och hade enkla fönsteromfattningar. Huset täcktes,\nliksom även gårdslängorna utmed Torget, av ett högt, brutet tak med tegel. Interiören\nbestod i bottenvåningen av en genomgående förstuga, tolv rum med bl.a. sal och två\nförmak samt kök. I den övre våningen, som var den egentliga representationsvåningen,\nfanns 10 rum. Av den fasta inredningen nämns bl.a. dubbeldörrar och kakelugnar.\n    Sammanbyggd med denna byggnad låg mot torget en flygelbyggnad, utförd i samma\nhöjd och med samma enkla fasadutformning utan några särskilda markeringar. Den var\nfrån början ämnad att inredas till teaterlokal eller, som det står i beskrivningen, ”opera-\nhus” med inredning, men den var 1790 oinredd. Senare inreddes denna flygel till en\nbostad i två våningar. Som fortsättning av denna länga, med en avslutning mot Smedje-\ngatan, fanns ytterligare en flygelbyggnad inredd i tre våningar och likaså huvudsakli-\ngen avsedd för bostäder. Vidare fanns utmed Smedjegatan, på tomtens västra sida, en\nstallbyggnad och inne på gården ett vagnshus.\n    När det nybildade bolaget 1818 övertog fastigheten företogs en del förändringar. De\nberörde endast delar av interiören och får närmast ses som en enkel anpassning till den\nnya funktionen. Societetslokalerna förlades till huvudbyggnaden mot Storgatan och\nkällarlokalerna till den södra delen mot Smedjegatan. Här fanns enligt Allvin 1839 bl.a.\n”rymlig danssal, sällskaps- och läsrum, klubb- och restaurationsrum”.\n    ”Stadshuset”, som det sedan kallades, såldes 1845 till det då nybildade ”Societets-\nbolaget”. 1863 såldes det vidare till en privatperson. Restaurangrörelsen fortsatte i fast-\nigheten fram till början av 1900-talet.\n    Etableringen av ”Stadshuset” visar, att stadens innevånare fått kontinuerlig tillgång\ntill lokaler för ett ståndsmässigt sällskapsliv - såväl för det vardagliga umgänget som\nför de större festligheterna. Det var i ”Stadshusets” lokaler som man beslöt att bilda Det\nLysande Sällskapet Jönköpings Par Bricole.\n\n\n\nKansli med Bellmansal och Barbarasalong\nUnder bortåt 100 år svarade Stora Hotellet för alla Par Bricoles lokalbehov, även kansli-\ndelen i den mån den inte fanns hemma hos De Styrande eller hos Protonotarien eller\nnågon annan officiant. Gradgivningarna har till allra största delen skett på hotellet.\n  Någon gång på 1970-talet flyttade Par Bricole successivt in i egna kanslilokaler på\nÖstra Storgatan 6, i ett vackert bankpalats byggt år 1900. Ursprungligen var lokalerna\nen bostadslägenhet med väl tilltagen takhöjd och djupa fönsternischer. I likhet med\nmånga andra stadsvåningar blev det kontor även av denna. Den siste innehavaren före\nPar Bricole var vår numera bortgångne Styrande Mästare emeritus Jan-Erik Berggren.\n\n\n70"}, {"pdfPage": 72, "printedPage": null, "text": "Invigning av det nyrenoverade kansliet 1999. Från vänster tillträdande Guvernementet D.St.M Leif\nThor, St.M Dan Ekström och St.K Sigvard Brännström, avgående D.St.M Eric Haglund, S.M Sven-\nOlof Forselius från Moderlogen, avgående St.M Anders Hugoson och St.K Perolof Kallings.\n\nTill att börja med hade Sällskapet andrahandskontrakt på två rum samt köket. Numera\nhar Sällskapet ett eget kontrakt på hela lägenheten med undantag av ett vackert hörn-\nrum, som det dock har option på att hyra när nuvarande innehavaren flyttar.\n   Lokalerna renoverades och byggdes om åren 1987 och 1999. Under de första åren\nanvändes ett av rummen för kansliet och det andra för sammanträden och ibland för\nmåltider. Efter Luculli Gilles tillkomst 1983 fick köket och matsalen ökad användning.\nVid 1987 års renovering var det framförallt köket som rustades upp, vilket naturligtvis\nskedde med tanke på Luculli Gilles behov. Tolv år senare, 1999, gjordes en mera\ngenomgripande ombyggnad och Par Bricole fick då tillgång till ytterligare ett större\nrum för sammanträden och tre mindre kontorsrum för uthyrning. Vid båda tillfällena,\nmen isynnerhet vid den senaste stora ombyggnaden, har Broder Ingemar Boman lagt\nned ett mycket engagerat arbete både som idégivare och arbetsledare. Tack vare gene-\nrösa sponsorer och många arbetsamme och nitiske Bröder har kostnaderna kunnat\nhållas nere.\n   Efter den senaste ombyggnaden består entrén av ett par gallergrindar och strax\ninnanför dem, i en liten korridor, blir man välkomnad av en bugande - men mycket\ntystlåten och stillsam - bricollist klädd i den svenska dräkten, en gång i tiden skapad av\nGustav III. På väggen bredvid honom sitter en liten Bellman-medaljong och ovanför\nden ett litet fönster med Par Bricoles logotyp. Bakom en dörr som leder till Par Bricoles\negna lokaler ligger en entréhall med direkt anslutning till kansliet.\n\n\n                                                                                              71"}, {"pdfPage": 73, "printedPage": null, "text": "Lennart Sjöblom och\n                                                                      Herbert Ljungdahl\n                                                                      belönas år 1991 för\n                                                                      ovärdeliga insatser\n                                                                      under många år.\n\n\n\n   I samband med ombyggnaden 1999 utrustades kansliet med moderna möbler, skåp\noch hyllor samt telefonsvarare, kopieringsutrustning och dator. Men allt blev inte nytt!\nI ett kassaskåp med minst 50 år på nacken finns ritualerna och i ett plåtskåp bland\nmycket annat det gamla medlemsregistret i Agrippapärmar som backup till datorns\nregister. Under de första åren fram till mitten av 1990-talet var det Bröderna Lennart\nSjöblom och Herbert Ljungdahl som skötte kansliet. De var där så gott som varje dag,\noch vad de inte visste om Sällskapet var inte värt att veta. Nu är det Bröderna Ingvar\nLarsson och Tore E. Meijer som vakar över ordningen på kansliet och ser till att\nallt fungerar som det skall.\n   Från entréhallen leder en kort korridor till Bellmansalen, köket och två toaletter, den\nena för Barbara och den andra för Par Bricole. I korridoren finns en ”vällingklocka”,\nsom klingar när det är dags att samlas till måltid eller sammanträde. Vidare finns en\ntavla som rymmer fyra akvareller med motiv från det gamla Jönköping av Gustaf\nFogelberg, en konstnär som i många bilder skildrat vår stad. Tavlan är en gåva inför\n125-årsjubiléet av en ofta sedd och kär gäst som har sina rötter i Huskvarna, Brodern\nThomas Carlén, Göta Par Bricole.\n   Från korridoren kommer man till Bellmansalen, som i den tidigare lägenheten var\nmatsal. Den invigdes av Stormästare Sven-Olof Forselius dagen före Installationshögti-\nden vid Barbara 1999 och är en stilfull sal i ljusgrönt, med parkettgolv, renoverade\nljuskronor och ett antikvitt matsalsmöblemang i gustaviansk stil. Runt bordet finns\nplats för 14 stolar med guldornamenterade ax. För riddarsalsmöblering finns också\nfyra karmstolar. I salen finns en sällskapsgrupp bestående av två Chesterfieldsoffor\noch ett butlers tray-bord. I salen finns flera bokhyllor dels med litteratur av och om Carl\n\n\n72"}, {"pdfPage": 74, "printedPage": null, "text": "Registrator Ingvar Larsson och Kanslirådet Tore E. Meijer.\n\n\nMichael Bellman och litteratur med anknytning till vårt Sällskap, bland annat kopior av\nde Gyllene Böckerna, och dels ett antal fotografialbum, uppslagsböcker och kokböcker.\nI en inbyggd belyst glasmonter förvaras gåvor och olika minnessaker. I salen förvaras\nockså den stora silverbålen, som används vid Barbarahögtiden.\n    Väggarna pryds av ett 80-tal sköldar. På en av väggarna hänger alla Styrandes sköl-\ndar från Carl Friedländers 1879 till Dan Ekströms 2004. På denna vägg finns också en\nmedaljong av Carl Michael Bellman samt en litografi som Brodern Peter Gadh skapat\ntill minne av den operamaskeradbal, som Jönköpings Par Bricole anordnade 200 år\nefter balen då Gustav III sköts år 1792. På de andra väggarna hänger sköldar som har\ntillhört Bröder, vilka på något sätt representerar Jönköpingsbygdens utveckling inom\nbland annat handel, hantverk, industri och myndigheter. Därutöver finns porträtt eller\nfotografier på kungarna Oscar II, Gustav VI Adolf och Carl XVI Gustaf, litografier på\nBellman och Gustav III samt en grupp små bilder från 1700-talet.\n    Bellmansalen/Riddarsalen används för kammarreceptioner, främst i de båda\nGuvernörsgraderna, som representationsmatsal, sammanträdesrum och sällskapsrum\nsamt som matsal inte minst av de många medlemmarna i Luculli Gille.\n\n\n\n\n                               Carl Michael Bellman i profil.\n\n\n                                                                                     73"}, {"pdfPage": 75, "printedPage": null, "text": "Köket är litet och ganska trångt, men välutrustat. Förutom en modern spis finns kyl,\nfrys, diskmaskin, mikrovågsugn och flera köksmaskiner. Då det är flera kockar som\nanvänder köket, blir det ofta med ordningen som med soppan. Men Luculli Gilles\nInSPISient, Tore Palmqvist, ser till att det är ordning och att allt finns på plats.\n    Det senaste tillskottet i våra lokaler, förutom de tre uthyrda rummen, är Barbara-\nsalongen. Av namnet att döma skulle man kunna vänta sig att få träffa vår kära Moster\ndär, men så lyckligt är det inte. Det tämligen stora rummet är i första hand avsett att\nvara sammanträdesrum. Därför finns moderna möbler i form av ett konferensbord med\ntillhörande stolar och ett par soffor för sällskaplig samvaro. På ena väggen hänger fyra\nsköldar med symboler från de fyra arbetsgraderna. Oljemålningar av Gustaf V och\nav de tidigare Styrande Mästarna Henrik Karnell och Anders Graab pryder också\nväggarna.\n\n\n\n\n                   Stig Skoglund. En i Vingården idogt arbetande Broder.\n\n\n\n\n74"}, {"pdfPage": 76, "printedPage": null, "text": "Sällskapets rekvisita och inventarier\nGradgivningarna i Det Lysande Sällskapet Par Bricole förutsätter en inramning som\nger logerummet ett festligt och högtidligt intryck som svarar mot ritualernas innehåll\noch utformning. Spegelsalen på Stora Hotellet är den första förutsättningen och våra\ninventarier och vår rekvisita är den andra och lika viktiga delen av den yttre ramen.\nDe är också en konkret del av Sällskapets historia och i många stycken något av ett\nkulturarv.\n   Jönköpings Par Bricole har under alla sina 125 år haft i stort sett alla sina samman-\nkomster på Stora Hotellet. Där har också Sällskapets alla inventarier förvarats. 1913\nskrivs det om garderoben, rekvisitavinden och kulissvinden som förvaringsställen och\n1945 skrivs det om rekvisitavinden, gamla trapphuset till frimurarlogen, arkivvinden\noch mittersta garderoben. Vi är inte säkra på vad man menar med dessa utrymmen, men\natt det fanns en omfattande uppsättning inventarier är alldeles klart, något som\ninventarielistorna ger besked om. Många av de stora och tunga inventarierna har bytts\nut mot lättare och enklare, men mycket av det gamla finns fortfarande kvar och det\nmesta förvarar vi på hotellvinden. Det var på initiativ av dåvarande Riddareintendenten\nSten Erik Henriksson, som det byggdes ett avskilt utrymme på vinden 1989. Den\nBacchanaliska Teaterns klädförråd finns dock numera i utrymmen som teatern dispo-\nnerar inom Tändsticksområdet.\n   När man läser i de gamla inventarielistorna häpnar man över hur mycket rekvisita\nsom fanns. Utöver regalier och rekvisita fanns tempel med valv, bakstycken och föns-\nter. Det fanns podier och material för teaterns scenbyggen och mycket kläder, t ex 31\ndamdräkter och ännu fler herr- och teaterdräkter. Modern teknik förekom i teater-\nsammanhang redan 1910 i form av ett aeroplan! Att akustiken i Spegelsalen är svårbe-\nmästrad, är inte något nytt. 1945 hade Sällskapet en AGA-Baltic högtalareanläggning\nmed förstärkare, högtalare, mikrofon och sladdar samt instruktionsbok. Allt en gåva\nav Dir. O Ljungbergh.\n   Bland gamla inventarier kan nämnas de vackra transparanger på de pelare, som an-\nvänds vid Den Första Riddaregraden, vår nuvarande Sjätte Grad. Troligtvis fanns de\nmed redan när graden gavs för första gången 1884.\n   1941 beslöts att ge Den Tionde Graden för första gången och att ”genom insamling\nanskaffa medel för givande av RGK”. Brodern J. Hjelme-Lundberg förklarade sig ge-\nnast villig att bidra med 500 kronor. Samtidigt beslöts att anskaffa nya inventarier till\nDen Fjärde Graden, som den 25 oktober 1941 gavs för första gången enligt en ny ritual.\nI 1945 års inventarieförteckning redovisas ”X: e gradens tempel och altare tillsammans\n24 delar”. Ett helt billass enligt Broder Erik Gustavsson, som var Intendent på 1960-\ntalet. För utformningen av detta svarade arkitekten Malte Erichs, senare Ordförande i\narbetsgraderna, Styrande Kansler och mannen som utformade vår logo Bacchus på\ntunnan. Dagens rekvisita är i dag inte lika omfattande som då.\n\n                                                                                      75"}, {"pdfPage": 77, "printedPage": null, "text": "Att rekvisitan på 1940-talet var så omfattande och av allt att döma i gott skick, var\nGustaf Emil Lundholms förtjänst. Han var under många år Sällskapets Intendent. Vid\nparentationen efter hans bortgång 1947 framhöll riddareprelaten Tage Löf hans insatser\noch nämnde särskilt att han vid sin avgång efterlämnade sällskapets yttre habitus i en\nomsorgsfullt renoverad eller nyskapad form. Ett uttryck för Sällskapets stora uppskatt-\nning av Lundholms insatser var den pokal, som han uppvaktades med på sin 50-årsdag\noch som nu utgör en mycket värdefull del av Sällskapets inventarier. Ett ytterligare\nbevis på uppskattningen av hans arbete utgör den gravvård som Sällskapet reste på\nÖstra kyrkogården i samband med minnesfesten 1952.\n   En stor del av rekvisitan försvann 1954. Bakgrunden till detta var att det fanns planer\npå att göra om Spegelsalen till resanderum. Till vår och många andras lycka blev inte\ndessa planer förverkligade. Men inskränkningar hade redan gjorts i de utrymmen som\nSällskapet av ålder disponerat på Stora Hotellets vind. De hade resulterat i att hotell-\ndirektören gjort en vindsröjning och kastat ut en stor del av rekvisitan, så på vinden var\nolyckan ett faktum! Ett faktum som delvis kan förklara att dagens rekvisita inte är lika\nstor som förr.\n   Ansvaret för att ställa i ordning logelokalen före Gradgivningarna liksom vården av\nvåra inventarier har Intendenterna. Många av inventarierna är gamla, gedigna och\nstabila pjäser som skall bäras ner från Stora Hotellets vind och sedan bäras upp igen.\nFram till någon gång på 1960-talet anlitades stadsbud för att på lördagsförmiddagen\nbära ner inventarierna. Det berättas att intendenten Knut Erik Jahnke, ledde stads-\nbudens arbete iförd frack. Enligt räkningar från stadsbuden på 1940-talet kostade deras\narbete 50 kronor. Under tidigare år anlitades utomstående till många av de uppgifter,\nsom bröderna eller ämbetsmännen nu gör själva. Det har fört med sig att många stora\noch tunga föremål bytts mot lättare och att en del förenklingar, som kräver mindre\nomfattande rekvisita, införts. Detta kan väl också ses som en följd av den allmänna\nutvecklingen mot rationalisering som skett under de senaste 50 åren.\n\n\n\n\n                                                                    Sven Malmborg och\n                                                                    klättrande Yngve\n                                                                    Lovrin i riskfyllt arbete\n                                                                    inför Installationen av\n                                                                    nya Styrande 1983.\n\n\n76"}, {"pdfPage": 78, "printedPage": null, "text": "Vid transporterna till och från vinden\nutsätts rekvisitan för ganska hårdhänt be-\nhandling, den slits och får större eller\nmindre skavanker. Det har alltid varit\nbråttom att bära undan inventarierna från\nspegelsalen för att bereda plats för\nmåltidskalasets bord och då händer det\natt vår rekvisita lever farligt. Inte bara\ntransporterna utan också miljön uppe på\nvinden kan många gånger vara påfres-\ntande med hetta på sommaren och kyla\npå vintern samt ibland också läckande\ntak. Därför var det 1990 dags för en väl-\nbehövlig ådrings- och marmorerings-\nmålning av våra träföremål. Arbetet be-\nräknades till en kostnad av 50 000 men\növerskreds med råge. Den faktiska kost-\nnaden blev ca 82 000 kronor. Finansie-\nringen blev ett problem som löstes dels\nmed hjälp av medel från silverskölds- RI Ulf Larsson dekoreras 1991. Benno Holm i\nfonden dels med ett lån, som det tog flera hedersvakten.\når att återbetala. Under dessa år fick Säll-\nskapet leva under ”knapphetens kalla stjärna”, men glädjas åt fräscha och fina föremål\nvid Gradgivningarna.\n\nVåra gradband\nVåra gradband utgör en viktig del i Par Bricole, vilket också avspeglas i att de regel-\nbundet förekommer i protokoll och räkenskaper. Fram till 1940-talet förekommer i rä-\nkenskaperna en post som kallas insamling och bandlån. Det senare antyder att bröder\nsom glömt sina band hemma, kunde mot en avgift få låna Sällskapets band. Numera har\nBröderna i Jönköpings Par Bricole inte några egna gradband att ta med sig hem, utan\nalla band förvaras på ett bandställ som vid Gradgivningarna tas fram från Sällskapets\nförråd på hotellvinden. Det gör att man klarar sig med ett färre antal band än vad som\nannars skulle vara fallet. Ur ekonomisk synpunkt lär det vara fördelaktigare att inte\nbinda ett stort kapital i banden. Det händer ju aldrig att Sällskapets alla bröder närvarar\nsamtidigt! Men slitaget blir större och det är ibland svårt att alltid ha rena och snygga\nband i tillräckligt antal. Det händer lite för ofta att banden får följa med sin bärare hem,\nsärskilt om det är ett snyggt band! Problemen dyker upp i protokollen med jämna\nmellanrum. Vid ett sammanträde 1952 påpekades att flera band var solkiga och trasiga.\nResultatet blev att ”föreståndaren för kansliet ålades tillse att samtliga band och in-\nventarier befinna sig i användbart skick”. En annan gång beslöts i Stora Rådet att\ngradbanden skulle låsas in efter Gradgivningen eftersom ”gradbanden i regel är på\n\n                                                                                         77"}, {"pdfPage": 79, "printedPage": null, "text": "Silverbålen\n\n\n\ndrift”. Dessa välkända och ofta återkommande problem gjorde att det under 1990-talet\ndiskuterades möjligheten att anskaffa band till alla bröder. Försök att skaffa billigare\nband hos tillverkare både i Sverige och utomlands har inte lett till något resultat.\nDå kostnaden för en övergång till ”individuella” band ansetts för hög, har det gamla\nsystemet tills vidare behållits.\n\nIntressanta inventarier och gåvor\nSällskapet har särskilt vid jubileer och särskilda högtider fått gåvor såväl från Moder-\noch Systerloger som från enskilda donatorer. Många gåvor som rör den rituella delen av\nvår verksamhet har under modern tid kommit från Brodern Anders Höök.\n  Vår äldsta och säkerligen förnämsta gåva är Silverbålen, som den 22 oktober 1900\növerlämnades till Sällskapet. Silverbålen är en gåva från vår förste Styrande Mästare\nCarl Friedländer. Bålen har alltså fyllt sin uppgift i mer än hundra år när denna jubileums-\nbok skrivs år 2004.\n\n\n\n\n                                                           t一\n                                                             • 出よ｝\n\n\n             Kristallservisen.\n\n\n78"}, {"pdfPage": 80, "printedPage": null, "text": "Lundholmska pokalen.\n\n\nVid Barbarahögtiden står två stora porträtt i Spegelsalen. De föreställer Sällskapets två\nförsta Styrande Mästare, Carl Friedländer och Bernhard Hay. Porträttet av Friedländer\navtäcktes vid Sällskapets 20-årsjubileum 1899, då den nyss avgångne Styrande Mästa-\nren var hedersgäst. Det har målats av V. Holmgren, som var lärare vid Jönköpings tek-\nniska yrkesskola och som också har utfört takmålningarna i Spegelsalen. Hays porträtt\när från 1907 och har gjorts av Ludvig Wahlin. Han var autodidakt som porträttmålare\noch han var Intendent och Ordensintendent i Jönköpings Par Bricole 1880-1899.\n   I en glasmonter i Bellmansalen förvaras några gåvor av särskilt intresse. Det är de så\nkallade kristallerna, en karaff med tillhörande pokaler i graverad Orreforskristall. Den\nmycket vackra servisen är en gåva från Moderlogen vid Jönköpings Par Bricoles 50-\nårsdag 1929. Där finns också de pokaler som Sällskapet fått vid sina 75- och 100-\nårsdagar och som också är gåvor från Moderlogen.\n   Den Lundholmska pokalen i silver är från 1940-talet. Den är smyckad med PB-\nsymboler och ädelstenar samt graverad med en lång text.\n   ”Det lysande Sällskapet Jönköpings Par Bricole vill med överlämnandet av denna\nhederspokal hylla sin mångårige RI, GI, I och allt i allo Den Högt Upplyste Brodern\nRGK Civilingenjören GUSTAF EMIL LUNDHOLM på hans femtioårsdag den 15 april\n1943 samt av hjärtat tacka honom för det hängivna arbete och de utomordentliga för-\ntjänster han nedlagt inom Sällskapet och för dess framgång. Henrik Karnell, St.M.,\nWilh. Lothigius, D.St.M, Gösta Pantzerhielm, St.K, Malte Erichs, O.”\n   Pokalen har utformats av Johan Färngren i Stockholm. Efter Lundholms bortgång\n1947 skänktes den av dödsboet till Sällskapet. Sedan dess har den - fylld med blommor\n- ofta stått framför Styrande Mästaren vid måltidskalasen. Pokalen stals vid ett inbrott\npå kansliet 1988, men återkom efter en månad. Den Lundholmska pokalen har varit ute\npå flera äventyr. Vid ett tillfälle under 1990-talet fann dåvarande Ordföranden i\n\n\n                                                                                      79"}, {"pdfPage": 81, "printedPage": null, "text": "Ordförandeklubban.\n\n\nArbetsgraderna, Dan Ekström den på en hylla i ett förråd hos blomsterhandlare Anders\nRuberg. Ruberg berättade att pokalen hade kvarglömts i Spegelsalen och att festvåningen\nhade nyttjat den då och då vid olika arrangemang. Anders Ruberg, som tillhör Jönköpings\nPar Bricole, tog vasen till sin affär och sedan glömdes den bort. Efter ca två år återfanns\nden och återbördades till Sällskapet.\n   I montern finns också den Ordförandeklubba som Sällskapet på 75- årsdagen 1954\nfick från Systerlogerna i Göteborg, Vänersborg, Borås och Malmö. Den vackra klub-\nban av ebenholts är prydd med symboler för Riddaregraderna och givarnas namn.\n   Där finns också en porslinsstatyett, Bacchi Børn, en gåva till Sällskapet vid 75-\nårsjubileet 1954 från Malmö PB. På bottenplattan står ”Bacchi Börn Köpenhamn* vid\n75 års jubiléet 1954 av ordföranden (oläsligt) RSK i Malmö PB”.\n\n*( Sammanslutningen Bacchi Börn kunde kanske närmast betraktas som en dotter till\ndotterlogen Malmö Par Bricole. Bacchi Börn konstituerades den 28 april 1948. I fort-\nsättningen synes dock Bacchi Börn ha fört ett tämligen tynande liv. (Sällskapet Par\nBricole 200 år, sidan 118) Red:s anm.)\n\nEtt mycket högt snapsglas finns också i montern. Det är graverat med ett datum, 13/1\n1959. Denna dag överlämnades glaset till dåvarande Styrande Mästaren Anders Graab\nvid en Bacchanalisk middag till Torsten Nothins ära. Glaset har donerats av sonen Jan\nGraab.\n   Aladdins lampa har en central roll vid våra Gradgivningar. Den är mycket vacker och\ngjord av gjuten brons. Den är tillverkad av Viktor Fongs gelbgjuteri i Gränna 1942.\n   Vårt Sällskap har tre banér: Det Röda Ordensbanéret, Sverkerska Banéret och Stora\nRiddarebanéret. Det Röda Banéret är äldst. I ett inventarium från 1913 omtalas Par\nBricoles standar, men om detta är samma som dagens Röda banér har inte gått att\nutröna. Däremot vet vi att Sverkerska banéret anskaffades 1964. I ett protokoll sägs det\natt ett nytt banér måste anskaffas och att Styrande Mästaren förordade att formatet\nskulle bli något större än förut och att stadens färger skulle användas. Stora\n\n80"}, {"pdfPage": 82, "printedPage": null, "text": "Sällskapets Lampa, tillverkad av Fong i Gränna 1942.\n\nRiddarebaneret anskaffades av allt att döma 1942 då fjärde riddaregraden gavs första\ngången här i Jönköping.\n   Förutom de tre banéren har Sällskapet en flagga, som skänktes 1990 av Broder Mag-\nnus Klingenstierna. När Den Sjunde Graden givs, hissas den under högtidliga former\npå den plats, där graden ges. Vid Gradgivningar på Stora Hotellet vajar den från hotel-\nlets flaggstång. Sällskapet har också en svensk fana som är en gåva från Stiftelsen\nSvenska Flaggans Dag.\n\n\n\n\nDet Röda Ordensbanéret.                         Det Stora Riddarebanéret.\n\n\n                                                                                     81"}, {"pdfPage": 83, "printedPage": null, "text": "Det Sverkerska Banérets båda sidor.\n\n   I samband med installationen av nya styrande 1999 anskaffade Sällskapet på förslag\nav dåvarande Styrande Kanslern Perolof Kallings en stor golvljusstake i en stil som för\ntanken till slutet av 1800-talet. De avgående Styrandes avsikt var att ljusstaken skulle\npryda spegelsalen vid våra Barbarahögtider, men på grund av ljusstakens konstruktion\noch storlek används den numera endast vid Installation av Nya Styrande. Däremellan\nförvaras den i Barbarasalongen. På foten finns en inskription på holländska: ”Joannes\nAdrianus Stigter eu Margaretha Gertruda Röling 1885 5 Mei 1910.” Ljusstaken är\nden ena av ett par. På den andra ljusstaken finns samma namn, men bara årtalet 1885.\nStigter och Röling är två holländska släkter, och det är troligt att ljusstaken kommer\n                                              från Holland. Den inköptes till vårt säll-\n                                              skap efter att ha varit i en Göteborgsfamiljs\n                                              ägo i cirka 40 år. Dess tidigare historia är\n                                              okänd.\n                                                  Bland övriga gåvor kan nämnas ett an-\n                                              tal årstallrikar med kulinariska motiv, som\n                                              skänktes 1989 av Brodern Mats Thorell.\n                                                  Moderlogen har genom National-\n                                              museums hjälp lyckats framställa en byst\n                                              av den tredje förgrundsfiguren bland vårt\n                                              Sällskaps grundare, nämligen Carl Israel\n                                              Hallman. Liksom Bellman hade både Hall-\n                                              man och Olof Kexél under 1770-talet sam-\n                                              lat vänner och umgängesbröder i små säll-\n                                              skap av mera löslig karaktär och utan be-\n                                              stämda ordensformer. Vid en sådan sam-\n                                              mankomst på källaren Kejsarkronan i\n                                              november 1777 höll Hallman en mycket\n                                              berömd parentation över Gottfried\n                                              Sackenhjelm. Det antas att man vid detta\n                                              tillfälle kom överens om att söka bilda en\nDen ”holländska” golvljusstaken.\n                                              verklig sällskapsorden genom att samman-\n\n82"}, {"pdfPage": 84, "printedPage": null, "text": "föra idéer och inslag från dessa små sällskap. Det är först då som ordensnamnet Par\nBricole förekommer. Bellman och Hallman var bohemnaturer och saknade organisato-\nrisk talang. Det blev Kexél som fick skapa formerna för Sällskapet. I och med tillkom-\nsten av Hallmansbysten, som Jönköpings Par Bricole anskaffade år 2004, kan vi be-\nskåda alla de tre män som kan sägas ha grundat vårt Sällskap. Bysten på Olof Kexél\nanvänds i Den Andra Graden, bysten på Carl Israel Hallman kommer från och med\njubileumsåret 2004 att användas vid Den Tredje Graden och bysten på Carl Michael\nBellman används ritualenligt sen länge vid Den Fjärde Graden.\n\n\n\n\n     Carl Michael Bellman.                          Olof Kexél.\n\n\n\n\n                             Carl Israel Hallman.\n\n\n                                                                                    83"}, {"pdfPage": 85, "printedPage": null, "text": "Sällskapets Talanggrupper\n\nDen Bacchanaliska Kören\nNär sången här fylligast klingar\nnär ljuvast adagiot dör\när Hon den som taktpinnen svingar\nfast Lindegren synligt den för\n(Ur Barbaratal år 1885 av advokatfiskalen Tomas Rosenqvist)\n\nÅren kring 1879 frodades nationalromantiken så in i Norden. Detta var en bördig gro-\ngrund för manskörer överallt i Sverige. I föreningar för studenter och arbetare, nyktra\noch onyktra, kristna och asadyrkare, vänster- eller högervridna hade manskörerna sina\nväxthus. Repertoaren var till stor del gemensam, men anpassad till den ideologi, som\ndrev verksamheten framåt eller bakåt.\n    Hos Moderlogen i Stockholm och Systerlogerna i Göteborg, Vänersborg, Borås och\nMalmö var körsången tongivande. Körerna uppträdde även vid konserter och celebra\ntillfällen utanför bricolleriets slutna rum. Då Par Bricole i Jönköping grundades var\nkören genast på plats.\n\nOm körens sångare och dirigenter genom tiderna.\nDe flesta nya sångare i PB-kören har redan sjungit i andra körer och många fortsätter\natt vara ”dubbelanslutna”. Andra får återfall i den sångarfeber, som legat latent från\nungdomens vår. Bröder med vana att hantera instrument transponerar sitt kunnande\noch fyller struparna med toner.\n   Många manskörer har på senare år tagit generalpaus till följd av att förste tenorer\neller andra basar falnat av. Yngre förmågor finns, men har inte kunnat prioritera kör-\nsång framför vaggsång eller påträngande plikter. Den Bacchanaliska Kören i Jönkö-\nping har också haft perioder med brist på sångare.\n\n     Och sången den tynar långsamt bort och dör,\n     Ej mer ni lyser nu med någon ståtlig kör,\n     Ett glesnat led, är vad som återstår\n     Av stora kören ifrån gångna år.\n\n     Är sångarne ej mera av den rätta rasen,\n     Sen Fritz tog avsked, och med honom Basen?\n     Har Bellmans sånger inga toner mer\n     Som locka kan förmågor upp till Er?\n\n84"}, {"pdfPage": 86, "printedPage": null, "text": "Och likväl ha’n I Stomberg, stor i sångens rike,\n   En ledare som få, man söka skall hans like!\n   Och Tyroler Frans den gamle Veteranen,\n   Nog kan han drilla än, om blott han blir i tagen.\n\n   Men med tenorer lär det vara klent beställt,\n   Förutom Axel Jonsson, som sjunger bra och snällt.\n   Men en tenor - kan väl ej räcka till\n   För hela PB-kören, så gärna än han vill.\n\n   Dock ej kan dessa alltid vara unga\n   Och uti evighet förmå att vackert sjunga.\n   Sök därför ungdom få i eder tropp\n   Så lever sången snart till liv ånyo opp!\n   (Ur Barbaratal år 1893 av Henrik Karnell)\n\nChoralintendenter inom Jönköpings Par Bricole\nFrämsta botemedlet mot sångarbrist heter skickliga ledare, som kan göra repetitioner\noch framträdanden levande, roliga och minnesrika. Många i den långa raden av\nchoralintendenter har spelat stora roller även i stadens övriga musikliv:\n\n1881-1885   Olof Emil Lindegren Vice Häradshövding\n1885-1889   Olof Emil Lindegren och Karl Karlberg Organist och Folkskolelärare\n1891-1893   Johan Victor Olsson Fil.stud.\n1893-1894   Alfred Stomberg Possessionat\n1894-1898   Johan Victor Olsson Lärare\n1899-1900   Eduoard G Lindh Musikdirektör\n1901-1902   Victor Nyström Fabriksbokhållare\n1903-1904   Johan Victor Olsson Skolförståndare\n1904-1905   Bror Adolf Beckman Kapten och Victor Nyström Fabriksbokhållare\n1905-1910   Gideon Peterson Musikdirektör\n1911-1933   Josef.A.Jacobsson Musikdirektör\n1934-1941   Gustaf Söderberg Kapten och Gustaf Engström Överlärare\n1942-1943   Torsten Sonnander Musikdirektör\n1943-1956   Carl (Calle) Carlsson Kantor Brukskassör\n1956-1962   Allan Carlsson Pianotekniker\n1963-1965   Tjelvar Hovstadius Musikdirektör\n1965-1973   Mats Bergling Försäljningschef. Carl Carlsson(aktiv hedersdirigent)\n1973-1981   Hugo Ramsten Musikdirektör\n1982-1987   Nils Norrsell Tandläkare\n1987-       Clas-Olof Lindquist Musikdirektör\n\n\n                                                                                  85"}, {"pdfPage": 87, "printedPage": null, "text": "Om körens repertoar\nI Par Bricole är Bellman hovpoet och huspoet. Fredmans epistlar och sånger låter höra\nsig vid varje gradgivning, måltid, utflykt och hyllningar till blomstrande moster eller\nbekransad broder. I kören fortlever det nationalromantiska arvet; Sånger såsom ”Dåne\nliksom åskan” eller ”Min stamfar hade en stor pokal” fyller fortfarande Bröderna till\nbredden. Kören medverkar vid minnestunder efter bortgångna Bröder och vid\nkyrkokonserter. Efterfrågan på vårsång ökar eftersom många gamla manskörer inte\nlängre går att tina upp. För att hålla kalasen flytande har Kören ett aldrig sinande sång-\nförråd med både styrka och smak. Kören har även nutidsorienterat sig med bland annat\nBeatles, Taube, Kalinka och Alf Henriksson.\n\nKörinsatser genom åren\nHär följer exempel från protokoll, årsberättelser och recensioner i lokalpressen. För de\nförsta decennierna citeras även anteckningar av Gustaf Ruuth. (Kantor och musik-\nrecensent och författare till ”Musikaliska nöjen i Jönköping 1620-1920” (Jönköping\n2001)).\n\nÅren 1879-1904\nInom Par Bricole uppträdde kören bland annat:\n1879 26 juli vid Bellmansfest på Stora Hotellet\n1880 25 april på Teatern. Jönköpings Gymnastikförening biträdd av Sällskapet PB:s\n     sångkör.\n1880 25 juli vid resa med s/s Per Brahe till Skemningsfors\n1882 24 september Högre Elementarläroverket. En Qvartett ur Jönköpings PB\n     Sångkör\n1886 26 juni Utvärdshuset vid Limugnen. PB firar Bellman\n\nAnnonseringen väcker fortfarande nyfikenhet:\n1886 9 mars Briljant Extra Parforce föreställning.\n     Uppträdande av P.B.sångkör. Obs 2:ne tenorer kunna erhålla fördelaktigt enga-\n     gement vid kören. Vidare meddelar sånganföraren.\n1886 16 maj Stor Beneficeföreställning till förmån för hela Sällskapet. Uppträdande\n     av P.B:s sångkör. Obs Barytonsolo utföres af den magre Mr Benjamin, som nu\n     efter fetetisdag väger 1/2 pund.\n1886 28 September Uppträdande av P.B sångkör. Obs Kören är icke blind. Det finns\n     icke så mycket som ”en blind höna” bland sångarne.\n1887 Oktober Stor Gala-Invignings-Representation. Uppträdande af PB Sångkör. Obs!\n     Musikaliska Akademien i Wernamo har tilldelat kören sin stora guldmedalj .Obs!\n1888 30 juli PB firades Bellmans minne med ångbåtsresa till Visingsö, sång och mu-\n     sik.\n1888 2 oktober Genom oerhörda kostnader har det lyckats Direktören att få engagera\n     PB-kören ytterliggare en saison.\n\n86"}, {"pdfPage": 88, "printedPage": null, "text": "1889 5 oktober Uppträdande av PB:s sångkör. Obs Tyroler Frans* tillhör kören\n      fortfarande. Kören hatar alla tuppar utom stekt tuppkyckling.\n(*Tyroler Frans var en framstående sångare med joddling som spetskompetens.)\n\nIntresset för PB och rekryteringen av nya Bröder sviktade efter de första framgångsrika\nåren. Sångkören fanns med - men inte alltid:\n   1890 26 april Inga recipiender. Brodern Cronholm anmälde ledsnad öfver PB:s\ntynande lifsverksamhet samt föreslog en uppryckningskommitté, hvilken anmodades\ninkomma med förslag till Ordens bästa. Trefligt samquäm efter logearbetet med god\nsång.\n   1890 26 juli Bellman firades med körsång under sin nye ledare kandidat Viktor Ohls-\nson.\n   1890 29 oktober Teatern. Dramatisk Musikalisk Soaré PB:s Sångkör och teatergrupp.\n”Rika morbror”, lustspel med sång av August Blanche. Quartettsång, Solosång, Dekla-\nmation.\n   1895 måste StM (OM) erinra sångarna om bristande nit och förehålla dem vad plik-\nten bjöd och tacksamheten för erhållna ynnestbevis ålade dem. Maningen föll tydligen\ni glömska för vid Gåskalaset 1898 utmärkte sig sångarna med sin fullständiga frånvaro!\n   1899 30 april PB 20 års jubileum i Stora Hotellets festvåning. Under hurtig sång\nintågade bröderna med sångarna i spetsen i festsalen och snart sutto de bänkade i ro och\ngamman kring det hästskoformade bordet. Redan från första stund gjorde sig den\nangenämaste stämning rådande, vartill i sin mån bidrog dels den präktiga taffelmusik,\nsom utfördes av Andra Göta Artilleriregementes musikkår, dels att gång efter annan\nfulltonig sång klingade genom salen.\n   1904 17 april. PB:s tjugofemårsjubileum i Allmänna Läroverkets Solennitetssal. Under\nlogen afsjöngs under Musikdirektör Carl August Johanssons ledning en af honom kom-\nponerad festkantat till ord af Handlanden Henrik Karnell. Efter högtidslogens slut\nbegåfvo sig bröderna till Viktor Rydbergs byst i Skolparken der sedan Sångarne sjungit\n”Land Du Välsignade”, St.M (O.M.) i ett tal egnade minnet af den frejdade Jönköpings-\nsonen Brödernas hyllning. Efter talet sjöngs ”Hör oss Svea”.\n   ”Sången är bricolleriets pulserande liv, den friska girland, som sammanflätar och\nsirar dess fyra pelare. Det är den som bidragit till, att under de nu gångna 25 åren hålla\nvårt PB livskraftigt. Må därföre I, som haven sångens toner i edra strupar sjunga in\nmandom, heder och godhet i våra hjärtan, mod och kraft åt oss och alla våra bröder.”\n(Ur högtidstal av RCM J Karling vid PB:s 25 årsjubileum 17 april 1904)\n\n\n  En fonografrulle med en kvartett ur Den Bacchanaliska Kören från 1890.\n  Första gången man lyckades fånga, bevara och återge ljudet av en mänsklig röst\n  var, sägs det, år 1877, då den amerikanske uppfinnaren Thomas Alva Edison talade\n  in orden Mary had a little lamb på en fonografrulle. Året därpå, 1878, förevisades\n\n\n                                                                                       87"}, {"pdfPage": 89, "printedPage": null, "text": "fonografen för första gången i Sverige av ingenjör A O Leffler. Å 1879 gav Leffler\n också en förevisning på Stora Hotellet i Jönköping.\n År 1888 hade Edison förbättrat fonografen och redan följande år reste dansken\n Gottfrid Ruben, som var Edisons generalagent för Skandinavien, genom Sverige\n för att förevisa den nygamla uppfinningen. I januari 1890 hade han nått Stockholm\n och på vaxkabinettet Panoptikon kunde man mot en krona i inträde höra inspel-\n ningar med svenska operasångare och skådespelare. Man lyssnade genom hör-\n slangar och en handfull personer kunde lyssna samtidigt.\n År 1890 besöktes också Jönköping av en av Edisons agenter varvid Smålands Alle-\n handas redaktion fick en speciell förevisning. En reporter (signaturen Puck) fick\n både lyssna till Operans stora publikidol, tenoren Arvid Ödmann, som sjöng\n ”Vermeland, du sköna” och skådespelaren Viktor Lundberg från Göteborg, som\n föredrog en rolig visa. Men även mindre stjärnor spelade man in. Reportern berät-\n tar att ”en välkänd kvartett av sångare ur Jönköpings PB skall söka insjunga några\n af sina nummer, så att det kanhända ej är omöjligt att fonografen redan i morgon\n kan bjuda de besökande några för dem välkända sånger, hvilkas likhet med origi-\n nalen bör vara lätta att kontrollera”. (Smålands Allehanda 9 maj 1890)\n\n\nÅren 1905 - 1929\nUnder de följande åren var kören i flitig verksamhet. Många framträdande solister upp-\nträdde. Man känner hur bläckpennan fortleder festsalens vibrationer till protokollen:\n1919 25 oktober PB 2 Sedan gemensam supé afätits samlades bröderna vid kaffe med\npunsch till ett synnerligen animerat nachspiel, där sångarne under Broder Josef\nJacobssons ledning glänste.\n                                         1920 21 november PB* Efter det högtidliga\n                                      logesammanträdet samlades Bröderna till gås-\n                                      middag i Stora Hotellets festsal. Middagen afåts\n                                      under mycket animerad stämning. Sångkören sjöng\n                                      flitigt under hela middagen och gåsvisan måste\n                                      bisseras. Brodern Ekström gladde bröderna med\n                                      flera sånger och Brodern Graneli föredrog ett af\n                                      honom författat poem ”Jönköping om 100 år”,\n                                      hvilket mottogs af Bröderna med stormande bifall.\n                                          (Förtydligande av PB* PB** PB***. Stjärnan\n                                      efter PB markerar vilken riddaregrad det gäller.\n                                      PB* är Första Riddaregraden, S:t Sigfrids Riddare-\n                                      grad vår nuvarande Sjätte grad. PB** är Konung\n                                      Sverkers Riddaregrad vår nuvarande Sjunde grad.\n                                      PB*** motsvarar före 1925 Gyllene Korset vår\n                                      nuvarande Tionde grad, men senare Konung Mag-\n                                      nus Riddaregrad eller Nionde graden.)\n\n88"}, {"pdfPage": 90, "printedPage": null, "text": "1923 8 december Barbara. Sedan Bröderna intagit supé i den så kallade damsalongen\nvidtog måltidskalaset i Stora Fästsalen. Till den allmänna glädjen bidrog flitigt sång-\narna under brodern Josef A. Jacobssons ledning. Brodern Broberg demonstrerade radio\ngenom vilken Bröderna lyckades komma i förbindelse med Den Milde Fadern Bacchi\nande.\n   1928 Söndagen 4 november PB allmänt - Efter en utmärkt delikat supé samlades\nbröderna åter i Stora Salen till ett angenämt måltidskalas med nachspiel .”En liten men\ndock sångkör” på sju man under Broder Gustaf Söderbergs ledning underhöll bröderna\nmed sina vackra toner.\n   1929 12 oktober 50 årsjubileum i Valhallasalen, Jönköpings Rådhus. Härvid utför-\ndes den till 25 årsjubileet av Musikdirektör Carl August Johansson komponerade kan-\ntaten. Solopartierna hade anförtrotts åt Koncertsångaren Percy Richards, Löjtnant\nE Dahlberg och Sångaren A Granqvist. Kören var 32 man stark och orkestern bestod\naf 10 man. Kantaten leddes af Direktör J. Jacobsson. - Efter logens slut begåvo sig\nbröderna till Viktor Rydbergs byst, där St.M. efter ett kort anförande nedlade en krans.\nSångarne utförde ”Land Du välsignade” och ”Hör oss Svea” Sedan fortsatte promena-\nden till Stora Hotellet, där det högtidliga måltidskalaset vidtog.\n\n\nÅren 1930 - 1954\nTrots krisåren före och under andra världskriget fortsatte PB och kören med aktiviteter.\nEn taktfull tradition var att sångarne inför hemgång eskorterade Styrande Mästaren till\nkapprummet:\n   1933 14 maj PB** Efteråt samlades bröderna till en god och angenäm vårmiddag i\nDamsalongen och fortsatte samkvämet i den lilla matsalen, varvid sångarne under Koral-\nintendenten Jacobssons ledning till Brödernas förnöjelse utförde ett flertal vackra och\nglada vårlåtar.\n   1939 12 november PB* Efter logen samlades Bröderna i Stora Salen till ett festligt\nGåskalas. De stora händelserna ute i världen och krigets vederstyggliga aspekter tolka-\ndes av Styrande Mästaren, som dock hyste den innerliga förhoppningen, att vårt land\ni fortsättningen kunde hållas utanför stormakternas uppgörelse och att vi böra vara\ntacksamma mot en mild försyn, som ännu tillåter oss att samlas i munterhet och förtro-\nlighet.\n   1940 27 januari PB allmänt. Efter logen samlades Bröderna till gemensamt måltid-\nskalas, varefter PB:s sångkör och andra PB-bröder utförde ett omväxlande och gediget\nsång- och musikprogram till firande av 200-årsminnet av Bellmans födelse.\n   1942 7 november PB 4 - ”Stå stark” avsjöngs med sedvanlig brio. Styrande Mästaren\ntackade den nye koralintendenten Torsten Sonnander för en utomordentlig insats och\nBröderna voro med på noterna. Sångarna hyllade Broder Sonnander med ”Vår sångar-\nhyllning tag”. Styrande Mästaren eskorterades på sedvanligt sätt till kapprummet och\nsångarna under Broder Sonnanders ledning sjöngo med utomordentlig känsla och in-\nlevelse.\n\n\n                                                                                     89"}, {"pdfPage": 91, "printedPage": null, "text": "1948 7 november PB * samt parentation i\n                                            Ljungarums kyrka.18 sångare anfördes av Bro-\n                                            der Carl Carlsson. Så ljöd de sex klockslagen\n                                            för de sex Bröder, som under det gångna året\n                                            för alltid lämnat brödrakedjan och efter en\n                                            stunds tystnad brusade sången från orgelläkta-\n                                            ren, där sångkören tagit plats.\n                                               1950 14 maj PB** Under den följande mid-\n                                            dagen lät den fulltaliga kören de gamla vår-\n                                            sångerna ljuda till Brödernas stora glädje och\n                                            uppbyggelse. Tacksamma Bröder skall länge\n                                            bevara i minne Dustin Ottossons fängslande\n                                            föredrag och vackra röst, som han till allas glädje\n                                            frikostigt lät höra i ett flertal solopartier.\n                                               1950 Söndagen 1 oktober PB*** Samman-\n                                            trädet fick sin högtidliga prägel genom sånga-\n                                            ren Bernhard Sönnerstedts närvaro. Många\nTidigare KI Carl Carlsson vid Barbara\n1977.                                       gånger har Jönköpings Par Bricole haft förmå-\n                                            nen att se denne sångare i sin krets. Hans klara\n\n\n\n\nSångare från 1950-talet. Mitt i nedre raden Helge Ottoson med KI Carl Carlsson närmast till\nhöger i bild.\n\n\n90"}, {"pdfPage": 92, "printedPage": null, "text": "och mäktiga stämma fängslade alla denna afton. Ingen kan bättre fylla den stora fest-\nsalen med välljud och Bröderna lyssnade andlöst, då han gång på gång gav prov på sin\nförnäma konst.\n\nÅren 1955 - 1979\nNu gjorde kören flera resor och hade utbyten med andra Bacchanaliska körer. Under\nslutet av 1960- och början av 1970-talet saknades röster i vissa stämmor och kören var\ninte alltid ”sångbar”. Par Bricole lånade då skickliga sångare från manskörerna Orfeus\noch Sångarbröderna. Dessa blev körens räddning eftersom många trivdes och upptogs i\nPar Bricole. De göt stadga i kören, som åter utvecklades och många av dem har varit\naktiva ända in i vår tid.\n   1955 19 maj PB ** med vårmiddag. Kören med Carl Carlsson som ledare. Sångarna,\nsom just hemkommit från Norge presenterade valda delar av det program, som instuderats\nför denna resa, vilken var gemensam för de Bacchanaliska körerna i Sverige. John\nKoch gav i ett tal besked om det goda sätt, varmed kören fyllt sin mission i Norge vid\ntioårsminnet av Befrielsen. Bland framträdandena märktes att kören sjungit på Skaugum\ninför de Kongliga samt vid invigningen av Torgny Segerstedtmonumentet.\n   1964 10 maj PB ** och Installation. Tjelvar Hovstadius och kören underhöll Brö-\nderna med vårens vackraste sånger. Den skicklige dirigenten hade också låtit inöva\nAugust Södermans ”Ett bondbröllop”, som fick ett uppmärksammat framförande.\n   1965 14 mars PB 2. Besök av 35 sångare\nfrån Borås. Gästerna framförde ”Ryska kören”\npå ett synnerligen förnämligt sätt. Vidare\nunderhöll de båda körerna tillsammans och var\nför sig hela kvällen med olika nummer på ett\nsätt, som rev ned applåd-åskor.\n   1965 16 maj PB**. Vårkonserten vid\nsamkvämet var en strålande upplevelse. De\nskickliga sångarna hade en mycket stor af-\nton. Helge Ottosson sjöng solo ”Tallarnas\nbarr”. Sångarens vackra tenor gjorde sig ut-\nomordentligt i detta framförande. För övrigt\nvar det Bellman och Taube och många nya\noch gamla sånger och visor som framfördes.\n   1968 19 maj PB **. Sånganföraren med\nkören gav stor vårkonsert. Aldrig låter Carl\nCarlsson sitt utomordentliga kunnande och\nsin inspirerande ledareförmåga komma\ntydligare till uttryck än vid vårkonserten.\n   1972 6 februari PB 4. Från Göta PB gäs-\ntade 35 sångare. Aldrig har väl sången\n                                                KI Hugo Ramsten stämmer kören.\nklingat så mäktig i kapitelsalen som denna\n\n                                                                                    91"}, {"pdfPage": 93, "printedPage": null, "text": "Hugo Ramsten och Bo Berntsson vid 100-       Helge Ottosson som jubelkommendör 1979.\nårsjubiléet.\n\n\n\n\nBacchanaliska Kören 1979. KI Hugo Ramsten.\n\n\n92"}, {"pdfPage": 94, "printedPage": null, "text": "kväll och Göta PB sångkör och även våra egna sångare hyllades och avtackades med\novationer.\n   1973 10 mars PB 2. Besök från Systerlogen i Vänersborg av De Styrande och sång-\nare. Sången klingade som aldrig förr i Kapitelsalen och dirigentskapet alternerades\nmed den äran av Vänersborgs KI Kjell Lagerkvist och Jönköpings KI Hugo Ramsten.\n   1978 2 december Barbara. Under högtiden underhöll Par Bricoles manskör under\nHugo Ramstens ledning och han har verkligen utvecklat kören till professionellt for-\nmat. Varje man utvecklade allt i sångarglädje under sin skicklige dirigent och det blev\nen körsång, som man kommer att minnas.\n   1979 6 oktober 100 års jubileum på Jönköpings teater. Hugo Ramsten och Bo\nBerntsson sjöng duetten ur Don Juan med specialskriven text, där inte ens Berntssons\nnödtorftiga översminkade skägg förtog intrycket av en moster Barbara med spår av\ngången skönhet.\n   Bland de många, som utmärktes med nådevedermälen måste särskilt nämnas den\nomåttligt populäre tenoren Helge Ottosson, som i femtio år sjungande vandrat\ni bricolleriets salar och nu utnämndes till jubelkommendör. Efter teatern samlades\nbröderna på Stora Hotellet, där kören som så många gånger förr tycktes överträffa sig\nsjälv i sitt framförande.\n\nÅren 1980-2004\nKören har varit mycket aktiv även utanför Par Bricole vid firmafester, jubileer och\nuppvaktningar men även vid resor och utbyten med andra körer.\n   1980 6 december Barbara. Men vad vore bricolleriet utan sång. Kören under Hugo\nRamstens ”flaxande händer” lät som aldrig förr. SÅNGARGLÄDJE. En musikalisk in-\noch upplevelse. STRÅLANDE! Har detta sagts tidigare? I så fall bjuder recensenten\npå det. Det tål att upprepas.\n   1981 25 april Vårbal på Stora\nHotellet. Kören under Hugos Ram-\nstens ledning framförde en nyskri-\nven text av Gunnar Gårdmark och\nEric Haglund med musik från Au-\ngust Södermans ”Ett Bondbröllop”.\nSt. M. Carl Wilhelm Lothigius fram-\nträdde därefter till kören och hyllade\nHugo Ramsten för hans gjorda in-\nsatser under de gångna åren och för-\närade honom Jönköpings Par Bricole\nfrämsta utmärkelse Eklöfskransen. I\noch med Vårbalen gjorde Hugo sitt\nsista framträdande såsom Koral-\nintendent i Jönköpings Par Bricole,\nenär han skall övergå till annan verk- KI Nils Norrsell dirigerar kören år 1983.\n\n\n                                                                                    93"}, {"pdfPage": 95, "printedPage": null, "text": "Kören i Spegelsalen år 1982.\n\n\nsamhet i Kongl Huvudstaden. Kören under ledning av Gunnar Jerstell framförde en\nspecialskriven hyllning från sångarna till Hugos ära. I en paus under dansen framträdde\nånyo sångarna denna gång med ett antal vårsånger och fick förvisso mycket välför-\ntjänta applåder.\n   1982 23 mars. Sångarna med damer besökte Göteborg på inbjudan av Göta PB Sång-\nkör. Efter en hastig sångduell i Valands magnifika trapphall serverades en verkligen\nutomordentlig supé ackompanjerad av spirituella tal och vackra och/eller entusiastiska\nsånger. Bland de våra utmärkte sig Choralintendenten Nils Norrsell genom rytmiska\nåthävor och resolut agerande.\n   1982 2 oktober PB 3. Bröderna underströk såväl med viskningar som rop sitt gil-\nlande av kören, som tillsammans med sin dirigent Nils Norrsell utvecklats på ett takt-\nfullt, ja lysande sätt.\n   1984 18 maj Jönköpings 700-årsjubileum. Under lunchen för Deras Majestäter Kon-\nungen och Drottningen sjöng den Bacchanaliska kören, vilket synnerligen uppskatta-\ndes av Sällskapets Höge Beskyddare.\n   1984 20 maj Sångspel i Stadsparken. Thes Bacchanaliska Teater tillsammans med de\nsamlade körerna från Jönköpings och Göta PB gav en bejublad föreställning vid\nVärendsberget i Stadsparken. En månghövdad skara fick uppleva sångspelet ”Ulla III\noch Gustaf Winblad”, vilket var Par Bricoles jubileumsgåva till Staden Jönköping, som\nfyllde 700 år.\n\n94"}, {"pdfPage": 96, "printedPage": null, "text": "1985 11-12 maj Resa till Jaegerspris i Danmark. ”Par Bricole 30 personer stor\nmandskor under Gunnar Jerstell och teatergrupp gästade Jaegerspris Amateurscene och\nKonstforening tillsammans med Peter Dahls utställning.\n   ”Koren gav straks en prove på sin kunnen och beviste att det var endog serdeles\ndygtige sangere som var på besög. De svenske gester sluttede deres ophold med et\nbesög i Skovens kirke og viste her att de beherskede kirkelig korsang på samme\nfremragende måde som den meget vanskelige Bellmanmusik”.\n   1985 12 oktober Göta PB Sångkörs 150 års jubileum. Kören från Jönköping fram-\nträdde tillsammans med körerna från Stockholm, Borås och Vänersborg i en hyllning\nvid J.A.Wadmans byst, vid en Jubileumskonsert i Konserthuset och en sång- och min-\nnesrik bankett på Valand.\n   1986 maj PB** Ramsjöholm. Då graden är präglad av ljuset och våren skulle\ngradgivningen äga rum utomhus. Regnet, det livgivande och friska, var dock lite för\npåträngande med påföljd att utomhusvistelsen fick avkortas. Den Bacchanaliska kören,\nsom alltid är tillstädes med sin ljuva sång, hördes tappert sjunga i en berså, men det blev\näven för sångarna att dra sig inomhus.\n   1987 24 augusti. I slutet av augusti började övningarna under vår nye musikaliske\nledare Clas-Olof Lindqvist. Han har på ett mycket förtjänstfullt sätt lett vår verksamhet\nsåväl i dur som i moll. Han har visat prov på stor taktfullhet och följer kören riktigt bra.\n\n\n\n\nKören och KI Clas-Olof Lindqvist år 1988 i Spegelsalen.\n\n\n                                                                                         95"}, {"pdfPage": 97, "printedPage": null, "text": "1988 6-9 maj. Ett andra danskt sångartåg med konserter i Jaegerspris och Frederiks-\nsund. Frank Johnsson från Par Bricole i Vänersborg var solist och resan blev i alla\navseenden en i mannaminnen bevarad succés.\n   1988 14-19 juni. Dubbelkvartett och 20 supporters reste till Leningrad. Succé på\nVänskapens hus där bl.a. Påskantat av Yngve Gamlin utfördes. ”Vi har inte haft så\nroligt på 30 år” var ett allmänt omdöme. Det var då som Stalin dog.\n   1989 26 februari Sjung- och Blåskonsert tillsammans med Norrahammars musikkår.\nVarken dirigent Clas-Olof Lindqvist eller hans lydiga korister tycktes i går kväll ha\nnågra besvärligheter att ge fart och pregnans åt spänstiga punkteringar och rullande\nsextondelsfigurer i epistlar om musikanterna Movitz och Fader Bergström. Men det är\nklart att Beatles Michelle avslöjade mer av koristernas finstämda och lyriska förmåga,\nmen så hade dirigenten både nyanserna och flygeltangenterna i sin hand. Kören sjöng\nom ”Vackra flickor skall man inte tänka på”, men det var svårt för dem att låta bli, när\nfyra blåsarflickor samtidigt placerat sig på podiet. Kantat med papperspåsar var en\nfröjd för både öga och öra.\n   1990 3 mars. Bellman 250 år på Jönköpings Teater. Sune Winald som autentisk mycket\nvälljudande Bellman och Eva Malmgren som den lättfotade nymfen Ulla Winblad även\nhon högst skönsjungande. Men också de praktfullt sjungande Par Bricoleynglingarna i\nskilda åldrar uppvisade en oväntad livfullhet tack vare påhittig regi. Allt vad de sjung-\nande, ypperligt dirigerade av Herr Clas-Olof Lindquist, framförde klingade rent och\nsynnerligen skönt. Nåväl de brava sångarna ackompanjerades med ackuratess av Herr\nAnders Lindell, som dirigerade de förträffliga Par Bricole-musikanterna där nere i djupa\n\n\n\n\nClas-Olof Lindqvist som ledljus i mörkret.\n\n\n96"}, {"pdfPage": 98, "printedPage": null, "text": "orkesterdiket. I sanning en behagfull af-\nton i Fru Musicas och Herr Bellmans\noförlikneliga tecken.\n   1992 3-6 januari Resa till S:t Peters-\nburg. Kören gästade Svensk-Ryska klub-\nben och höll konsert i Jusopovpalatset.\nClas-Olof Lindquist dirigerade och Sune\nWinald var solist. Vid incheckningen för\navresan uppstod tvärstopp. Då rev kören\nav det tunga artilleriet i form av ”Dåne\nliksom åskan” och ”Klingom Bröder”.\nDen ryska byråkratin bröt fullständigt\nsamman och kören släpptes in i avgångs-\nhallen. Därinne var minst 20 meter till ta-\nket och en fantastisk klang. Solisten Bo Allan Perolainen sjunger kommendörsvisan\nBerntsson fick vid konserten liksom vid vid Barbarahögtiden 1996.\nden Bacchanaliska körens framträdanden\npå flygplatsen och andra ställen mottaga stort ryskt jubel i den ryska sången ”Kalinka”.\n   1992 7 november Operamaskeradbal på 200-årsdagen av mordet på Gustaf III. En\nsjungande dubbelkvartett fick äran att bära Kungen från balsalen till sjuksängen. Den\nBacchanaliska Kören har en härlig utstrålning.\n   1995 1 april. Smålands Sångarförbund på Elmia. PB-kören medverkade vid konser-\nten och hade sedan värdskapet för ett svårdirigerat sångarkalas.\n   1996 3 mars Besök av PB-kören med damer från Vänersborg. Visning av Jönköpings\nmest sällsynta sevärdheter såsom Fornrysk bussguide, 1904 års Badhusruiner uppifrån\nsamt ”Sjungande kirurger” i Länssjukhusets entréhall. Gemensam sångarfest i Konsert-\nhusets foajé.\n   1996 16 maj ”Dansken kommer”: Sönderborgs Manskor från Danmark. Gemensam\nkonsert på PB-gymnasiet, eftersits på restaurang Amadeus.\n   1996 och 1997 augusti Bejublade konserter vid Allsångskvällar i Jönköpings Stads-\npark.\n   1997 september Kören med kärälskeliga besökte kollegerna i Vänersborg. Nedanför\nHunneberg stoppades bussen av polis och eskorterades till en vätskekontroll. Sedan de\ngemensamma körerna uppvaktat Fridas staty, släpptes fångarna loss i ett ständigt sjung-\nande vårkalas.\n   1998 28 mars Styrande Kanslern i Borås hade vunnit ett valfritt framträdande av\nKören på Barbaralotteri. Vinsten utverkades genom körens medverkan vid Sjunde gra-\nden i Borås.\n   1998 12 juni Carlfors Bruk jubilerade på Stora Hotellet. Par Bricoles korgossar\nomskolades till kypare, serverade öl och sjöng snaps.\n   2000 15-16 april Kören fick äran att vikariera för Stockholms Bacchanaliska kör vid\nFjärde graden på Hasselbacken. Därpå följde animerat nachspiel i Bellmanshuset på\n\n                                                                                     97"}, {"pdfPage": 99, "printedPage": null, "text": "Urvädersgränd. Hela Kören och Clas-Olof Lindquist blev synnerligen väl bemötta,\napplåderade, medaljerade och trakterade.\n   2000 1 maj Kören inledde en ännu bevarad årlig tradition att sjunga in våren i Kultur-\nbyn Åsens by\n   2001 31 maj EU middag på Stora Hotellet. Den Bacchanaliska kören illustrerade för\nEU:s jordbruksministrar och andra kulturkompetenta, hur man sköljer ned potatis och\nandra flytande sädesslag.\n   2002 13 mars Besök av PB-kören från Vänersborg. Gemensam konsert och fest med\nSystrarna på Länsteatern i Tändsticksområdet. Utmärkt växeldragning mellan gästande\nKI Frank Johnsson och värdarnas Clas-Olof Lindquist.\n   2002 16 juni Husqvarna Viking Symaskiners Bankett på Elmia. PB-kören lärde\nSymaskinsagenter från U.S.A. att sjunga snapsvisor på engelska (ad modum Clas Wahl-\nbin) och spädde på med Bellman och folkvisor på svenska .\n   2002 31 augusti Första Bellmansfesten i parken vid Rosenlunds herrgård. Storm,\nregn och blåst. Bellmans ande lät sig därvid påtagligen påminna.\n   2004 19-21 mars Internat på Skagen med körkurs för sjungande Bröder och akvarell-\nkurs för målande Systrar. Kören gav konsert i Svenska Kyrkan.\n   2004 18 september installerade kören snapsar i 10 vid Högskolan nyinstallerade Pro-\nfessorer. Sång vid akademiska högtidsmiddagar i Jönköping har sedan några år blivit\nen ny och stimulerande uppgift för PB-kören.\n\n                                                Körens aktuella status och\n                                                utveckling\n                                                Samarbetet med teatern och musiken\n                                                har odlats i flera spex och många andra\n                                                gemensamma framträdanden. Körens\n                                                nuvarande Koralintendent Clas-Olof\n                                                Lindquist drar ”fullt hus” varje mån-\n                                                dag, vilket visar att sångarna uppskat-\n                                                tar hans repetitioner som är både gi-\n                                                vande och trivsamma. Bacchanaliska\n                                                kören inom Jönköpings Par Bricole är\n                                                och med sina 40 aktiva sångare en av\n                                                de största manskörerna i Småland. Nå-\n                                                gon gång per termin ordnar kören ut-\n                                                flykter och/eller kalas med och för sina\n                                                kärälskeliga systrar. Serenader står all-\n                                                tid på dagens meny och kan även be-\n                                                ställas à la carte.\n                                                   Presumtiva sångare med förmåga att\n                                                sjunga hörbart och i rätt stämma, utan\nKören vid Den Tredje Graden år 2004.\n\n\n98"}, {"pdfPage": 100, "printedPage": null, "text": "att störa omgivningen, är mycket välkomna. Har man väl börjat och klarar uppgifterna\nkan man aldrig gå hem. Den Bacchanaliska kören har varit tidigt ute med en frivillig\noch flexibel pensionsålder.\n   ”Dolda talanger har Sällskapet uppsökt och uppmuntrat. Mången Broder, som aldrig\nhaft en lyra i sin hand har uppkallats att knäppa i dess strängar, varvid Bröderna med\nvänligt överseende lyssnat. Andra, som förut aldrig använt sin röst i samkväm till annat\nän oljud, hava genom långvarig och trägen övning lärts att ur strupen framkalla sångens\nvälljud.”\n(Ur minnestal av Lektor C.O.von Porat vid Par Bricoles 10 årsjubileum 13 april 1889)\n\nSom sångarbroder känns det tryggt att vara en länk i denna långa kedja.\n\n\n\n\nDen Bacchanaliska Musiken\n”Utan tvivel finns det i vårt ordenslivs innersta mening och syfte mycket som får sin\nbästa tolkning i sången och musiken. Den erfarenheten har gjorts i gångna tider. Och\nden skall göras - det hoppas vi - även i kommande” (Ivar Norberg 1946). Musiken och\nsången har alltid varit viktiga inslag i Par Bricoles liv. Det är nästan omöjligt att före-\nställa sig Par Bricole utan dessa. Detta hänger ihop med Sällskapets upprinnelse i den\ngustavianska stockholmsmiljö där Bellman sjöng sina sånger. Där kunde man knappast\ntänka sig en festlig kväll utan sång och musik. Musiken är och förblir en självklar\ningrediens i bricolleriet.\n   ”Muntra och anständiga tidsfördriv har rikligen yppat sig på Jönköpings Par Bricoles\nlevnadsstig. Tale- och skaldekonsterna, skådespel, sång, musik och skämt i skilda for-\nmer har flitigt odlats av ’lysande brikoller’ och ’talanger’ i broderligt samarbete.” Så\nskrev Ernst Greén 1946 i sin översikt ”Jönköpings Par Bricole”. Och så är det nog. Och,\nnär det gäller kör och teater finns de rikligt dokumenterade i olika akter. Musiken har\nalltid funnits med, men dokumentationen är nästan obefintlig.\n   När Jönköpings Par Bricole bildades var staden ännu en liten idyllisk ämbets- och\ntjänstemannastad, dominerad av jurister från Kungliga Göta hovrätt och av officerare\nfrån stadens regementen, vilket också avspeglades i Par Bricoles medlemsrullor. De\nunga glada officerarna kom i mångt och mycket att framstå som en motpol till de strama\nhovrättsjuristerna. Staden hade två regementen, Kungl. Smålands Artilleriregemente,\nA6 (1895 - 1985), och Kungl. Norra Smålands Regemente, I 12 (1905 - 1928). Vid\nregementena fanns också musikkårer. Sigfrid Strand har i sin licentiatavhandling ”Militär-\nmusikern i svenskt musikliv” (1974) framhållit militärmusikens betydelse för det civila\nmusiklivet. Professionella symfoniorkestrar fanns bara i ett fåtal städer, medan musik-\nlivet ute i landsorten nästan helt präglades av insatser från militärmusiker. Man spelade\ninte bara marscher vid ceremoniella tillfällen utan medverkade även vid friluftskonser-\n\n\n                                                                                        99"}, {"pdfPage": 101, "printedPage": null, "text": "ter och musiksoaréer. Mili-\n                                                            tärmusikerna bildade också\n                                                            stommen i praktiskt taget alla\n                                                            andra orkestrar. De var dåligt\n                                                            betalda och behövde dryga ut\n                                                            kassan med extrainkomster.\n                                                            Sålunda såg man dem i dans-\n                                                            band, bruksorkestrar, lokala\n                                                            orkesterföreningar och blås-\n                                                            orkestrar, men också som le-\n                                                            dare för körer och orkestrar,\n                                                            som lärare i instrumentalmu-\n                                                            sik och som arrangörer av\n                                                            musik för olika typer av or-\n                                                            kestrar. Par Bricole hyrde, i\n                                                            brist på egna musikresurser,\n                                                            vanligtvis in delar av militär-\n                                                            musiken vid tillfällen då man\n                                                            ville förgylla sina evenemang\n                                                            med musik. Flera av dessa\n                                                            musiker blev bricollister. Mili-\n                                                            tärmusikerna av den gamla\n                                                            stammen var allroundmusiker.\nFörsättsblad till noter tryckta i Jönköping år 1887.        Förutom ett huvudinstrument\n                                                            hade man minst ett biinstru-\nment, men ofta flera. De behärskade i regel också olika musikgenrer och hade genom\nsitt yrke en bred repertoar.\n   Musiken fanns där men har inte satt stora spår i Sällskapets tidiga handlingar. I ordens-\nmatrikeln omnämns musiken - såvitt redaktionen kunnat finna - första gången 1894-\n1895 - ”Par Bricoles Kapells Anförare: Stomberg, Alfred” står det. Kapellet bestod av\nen komplett stråkkvintett där Stomberg spelade violoncell. Dessutom ingick piano.\n\n\n  Alfred Stomberg, anförare för Kapellet 1894 - 1895, var också Körens ledare 1893\n  - 1894. Han nämns i Karnells Barbaratal från 1893, som citeras under avsnittet om\n  Den Bacchanaliska Kören.\n     Alfred Stomberg tycks ha varit en aktiv man och ha ett spännande förflutet som\n  sångare. År 1890 planerade han för en stor konsert, där Den Bacchanaliska Kören\n  säkert också kom att delta. I Smålands Allehanda den 9 maj 1890 står att läsa:\n  ”Sångarfanan åter höjes, åtminstone för tillfället af den pröfvade kämpen från Arpis\n  dagar (Oscar Arpi, känd ledare för Allmänna Sången i Uppsala) och Upp-\n\n\n100"}, {"pdfPage": 102, "printedPage": null, "text": "salasångarnes första Parisfärd, landtbrukaren hr Alfred Stomberg, som kring sig\n lyckats samla en skara af yngre sångare och äldre, bland hvilka märkas några\n fördettingar från Uppsalasångens stora dagar, från de bägge segerfärderna till Paris.\n Hr Stomberg, som under en lång följd av år varit anförare för Smålands nations\n sång, vill, om han lyckas, slå ännu ett slag för ”nationen” samt genom en konsert\n skaffa bidrag till fonden för ombyggande av nationshuset i Uppsala. För att kon-\n serten skall kunna uppfylla sitt mål och häfda gamla traditioner har hr Stomberg\n satt sig i förbindelse med några sångarveteraner från andra håll.\n    Och lyckas han - och gör ej hr Stomberg det, så gör ingen det - att samla tillräck-\n liga krafter till den bebådade konserten, som då skall äga rum innan läroverket\n stänger sina portar och folket reser från staden, så torde ”nationen” få påräkna ett\n ej ovälkommet bidrag och Jönköpingsborna en af dessa populära konserter, från\n hvilka ingen vill vara frånvarande.”\n\n   Sedan tystnar musiken åter i matriklarna, men hördes i verkligheten från en kvalifi-\ncerad grupp, som dominerades av regementsmusiker av vilka många även recipierades\ni Par Bricole. Enligt Ernst Greén i ”Jönköpings Par Brikoll 1879-1929” tillträdde år\n1911 ”ordenskantorn Musikdirektören Josef A. Jacobsson, som alltsedan i onda och\ngoda tider med skicklighet och intresse omhuldat sången och musiken inom Par Bricole.\nVid sin sida har han numera två vice Ordenskantorer, kapten Gustaf Söderberg och\nmusikdirektör Enock Nilsson.”\n\nLedare för orkestern\nNedan redovisas Den Bacchanaliska Musikens ledare, så långt dessa har gått att spåra i\nakterna. Anders Lindell och Lennart Samuelsson har på begäran berättat litet om verk-\nsamheten under sin tid som Direktörer för Den Bacchanaliska Musiken.\n\n1. Knut Elmgren           1946 - 1966\n2. Bengt Stenberg         1967\n3. Knut Elmgren           1968 - 1977\n4. Ingmar Sjöholm         1979 - 1987\n5. Anders Lindell         1988 - 1995\n6. Bo L Spång             1996 - 2003\n7. Lennart Samuelsson     2003 -\n\nKnut Elmgren\nOrkestern leddes under två perioder av Knut Elmgren, ”Pianoknutte” kallad. Hans trio,\nsom var allmänt känd i staden, bestod av piano, violin och bas och var själva stommen\ni orkestern. Samtliga var yrkesmusiker från A6. Stämbesättningen präglades lite av\nKajsa Vargs koncept - man tager vad man haver. 1947-48 bestod orkestern av åtta man\nDen nämnda trion kompletterades med flöjt, trumpet, klarinett, saxofon och trummor. I\n\n                                                                                     101"}, {"pdfPage": 103, "printedPage": null, "text": "mitten av femtiotalet hade orkestern decime-\n                                            rats till bara sex man och 1960 till bara fem.\n                                            Utöver trion ingick då trumpet och saxofon i\n                                            orkestern.\n\n                                            Ingmar Sjöholm\n                                             Ingmar Sjöholm var arkitekt och recipiera-\n                                             des i Par Bricole år 1966. Ingmar var ofta\n                                             ackompanjerande musikant inom Den\n                                             Bacchanaliska Teatern, men också lite av\n                                             multimusikant, som även trakterade trumpet\n                                             och horn. Till 100-årsjubileet 1979 hade Mu-\n                                             siken övat in en repertoar med nyskrivna ar-\n                                             rangemang, gjorda av pianisten och PB-bro-\n                                             dern Jack Oltmans. Ingmar ledde musiken\n                                             under en ganska svår tid, då det var svårt\n                                             att samla en ensemble, som hann repetera till-\n                                             räckligt och kunde ställa upp när det gällde.\nDfBM Ingmar Sjöholm.                            1980 skrev Ingmar Sjöholm: ”Den Bac-\n                                             chanaliska Musiken har ännu inte funnit sina\nformer, och sådana förändras ju successivt. Glädjande nog har många anmält sitt in-\ntresse att medverka i musiken, f n 19 namn registrerade. Man måste dock ha klart för\nsig att de flesta av oss är amatörer av olika grad, ålder etc., vilket medför konsekvenser.\nDen civila karriären och andra engagemang medför t ex att några inte finns tillgängliga\npå orten vissa tider och det kan vara svårt att samlas till övningar”. Men då, liksom nu,\nvar både rekryteringen av nya musiker och närvaron vid repetitioner problem: ”Ca 20\nmusikanter finns f n noterade inom musiken. Med viss möda och med någon komplet-\ntering utifrån kan vi ställa upp knappt tio vid evenemangen, på repetitionerna kommer\nvanligen bara 4-5 stycken” (Årsberättelse 1982). Man skriver också att ”Bacchanaliska\nmusiken helst bör bestå av så många medlemmar att det alltid finns reserver”. Dessa\nsynpunkter och önskemål har gått som en röd tråd genom årsberättelserna alltifrån\nBacchanaliska Musikens tillskapande fram till dags dato. Så sent som i 1996 - 1999 års\nmatrikel kan man läsa: ”Trots det på papperet imponerande antalet musikanter\n(17 stycken) har det ibland varit nödvändigt att inkalla diverse Calmucker för att vi\nskulle bli spelbara... Men inte märks då det när processionen med Det Styrande\nGuvernementet i spetsen tågar in till tonerna av Stolta stad. Det klingar så skönt, takt-\nfast och i stort sett rätt och riktigt.”\n\nAnders Lindell\nIngenjör, gymnasielärare, amatörmusiker och trumpetare. Anders Lindell gick med i\nPar Bricole redan 1976. Han hade redan då länge sysslat med musik som hobby och\n\n\n102"}, {"pdfPage": 104, "printedPage": null, "text": "bl.a. i flera år spelat i ett dansband. När Anders kom med i Sällskapet var Ingmar Sjö-\nholm direktör för musiken. Repetitionerna brukade då äga rum i Sjöholms villa. Redan\nfrån begynnelsen försökte Anders verka för att det skulle vara mera musik under grad-\ngivningarna. När Sjöholm avgick som direktör övertog Anders ledarskapet. Skälet till\natt Anders 1995 lämnade uppdraget var att han hade fått arbete på annan ort.\n   Anders berättar, att en av hans första åtgärder var att försöka få bättre ordning med\nordnade repetitioner, egen ekonomi, en repertoar och även en liten samling musiker.\nMan hade en ganska blandad sammansättning. Anders anskaffade gehäng till notställen,\ninförde musikmedaljen och skrev statuterna till denna. Det var också Anders som in-\nförde kungafanfaren i samband med Hans Majestät Konungens skål. Han fick även\nmusiken att medverka i spexen. Repetitionerna ägde rum i kanslilokalerna.\n\nBo L Spång\nAmatörmusiker med saxofon och klarinett som huvudinstrument. Bo var också en upp-\nskattad medlem i Den Bacchanaliska Teatern. Han medverkade i flera av stadens amatör-\norkestrar och avled år 2003 efter en längre tids sjukdom.\n  Bo växte upp i Jönköping. Vid 7 års ålder började han spela trumpet och klarinett i\nKFUM:s gossavdelning. När Jönköpings kommunala musikskola startade 1947 var Bo\nen av de första som skrevs in. Musiken var hans livselixir även om han själv aldrig\nnådde den högre musikutbildningen, vilket han delvis skyllde sin far som inte ville att\nBo skulle bli regementsmusiker. Han blev i stället företagsekonom, men musiken var\nhans drivkraft.\n  I Par Bricole trivdes han som ”fisken i vatt-\nnet” och satt med i orkestern i 27 år. Under\nen stor del av denna tid var han också en av\nde mest aktiva spexarna.\n\nLennart Samuelsson.\nMilitärmusiker från Eksjö, valthornist med\npiano och violin som biinstrument. Efter ned-\nläggningen av militärmusikkåren verkade han\nsom musiklärare och musikledare i Eksjö. Han\när mångårig orkesterledare och van arrangör.\nLennart gick med i Par Bricole därför att han\ntillsammans med Broder Tommy Öberg hade\nbildat en liten duo med två valthorn - De Två\nMovitz - vilken framförde Bellmanmusik i ar-\nrangemang för två horn. Det kändes då natur-\nligt att söka sig till en förening med Bellman-\nintresse. Han övertog posten som direktör för\nmusiken i samband med Bo L. Spångs bort-          De två Movitz Lennart Samuelsson och\n                                                  Tommy Öberg.\ngång i juli 2003.\n\n                                                                                         103"}, {"pdfPage": 105, "printedPage": null, "text": "Efter pensioneringen har Lennart lagt ner mycket arbete på en liten blåsargrupp -\nRänneslättsoktetten. Han har också kommit att lägga stort arbete på att arrangera musik\nför mindre blåsarensemble, något som inte bara har kommit Ränneslättsoktetten till-\ngodo utan också har kunnat utnyttjas av den Bacchanaliska Musiken.\n\nRepetitionslokaler\nTill att börja med träffades man hemma hos någon av musikanterna och förde en ambu-\nlerande repetitionsverksamhet i Jönköping, Tenhult och Bunn. Ibland lånade man Odd\nFellow-lokalen och efter körens repetitioner kunde man ibland få låna Per Brahe-gym-\nnasiets musiksal, dvs. efter kl. 21 på kvällen. Denna repetitionstimma krymptes seder-\nmera till en halvtimma när skolan fått ny vaktmästare, vilken ”läst kollektivavtalet”.\nOfta saknade man piano. Från 1999 övade orkestern i Hälsohögskolans lokaler, men\nnumera brukar orkestern träffas två timmar före gradgivning på Stora Hotellet och öva\nkvällens musiknummer.\n\nMusikaktiviteter\nVanligtvis har Den Bacchanaliska Musiken deltagit med:\n1. Ritualenlig musik vid Barbara\n2. Underhållningsmusik vid Måltidskalasen.\n3. Ackompanjerande musik till teatern\n4. Soloinsatser fanfarer, hornsolo och liknande\n5. Brunnssextett med gamla instrument och arrangemang\n6. Dansmusik vid Vårbalerna\n\n\n\n\nSpexet Dam Bricole 1992 (Allmänt kallat Damlösa Brunn).\n\n\n104"}, {"pdfPage": 106, "printedPage": null, "text": "Medverkan med ”stor orkester” tycks framför allt ha skett vid Barbarahögtiden och\nVårbalen. Framför allt spelade orkestern ”Stolta Stad” vid procession in och Jacobssons\nFestmarsch vid lämpligt tillfälle. Festmarschen skrevs av Musikdirektör Josef A\nJacobsson till Sällskapets 25-årsjubileum år 1904. Den framfördes för första gången\ndå Bröderna vid detta tillfälle tågade in till Måltidskalaset i Spegelsalen. Jacobsson var\nledare för både musiken och kören åren 1911 - 1933.\n\nMusikalier\nNågon egentlig samling av musikalier för orkestern fanns inte före 1998, med undantag\nför en mindre samling. Olika medlemmar, bl.a. Gunnar Gårdmark, skrev arrangemang\nför musiken vid speciella tillfällen. Äldre noter har mycket få kompletta stäm-\nuppsättningar. En samling sådana noter visar sig mest innehålla körmusik, pianomusik,\neller solomusik för röst och piano. Uppenbarligen har det genom tiderna funnits en och\nannan storsångare, som kunde framföra stora operaarior till pianoackompanjemang.\n   Numera finns en grunduppsättning av noter omfattande ca 100 nummer, vilka arki-\nverats. De flesta arrangemangen är för blåsarensemble, men de kan vid behov komplet-\nteras med andra stämmor.\n\nMusiker\nI de äldsta förteckningarna finns av naturliga skäl inte upptagna några ännu verksamma\nmusikanter. Från mitten av 1980-talet finner man namn som Ingvar Selse, Holger Eng-\nström, Lars-Olof-Johansson, Bo L Spång, Peter Gadh, Per-Olof Ringquist, Gunnar\nGårdmark och Anders Lindell. De flesta av dessa är verksamma ännu idag.\n\n\n\n\n               Installationsmusik 1993. Johan Liljegrahn mitt i och Gunnar Gårdmark till höger\n               i första ledet.\n\n\n                                                                                          105"}, {"pdfPage": 107, "printedPage": null, "text": "Stor orkester vid Den Fjärde Graden 1997.\n\n\n\n\nGustaviansk orkester vid offentligt genrep av spexet Ulla III år 2000.\n\n\n106"}, {"pdfPage": 108, "printedPage": null, "text": "1981 uppges att man gjort vissa nyrekryteringar och även fått en del nyskrivna ar-\nrangemang av ”vår nyttige Torsten Hillenborg, som därtill exekverar div. saxofoner,\nhorn, esskornett, trumpet, gitarr och bas om så behövs. Till omväxling en något annor-\nlunda klang än den rena mässingssextettens.” Brunnssextetten med gammal instrument-\nbesättning hade tydligen använts så mycket att man tröttnat på klangen!\n   Idag består Den Bacchanaliska Musiken av 15-20 medlemmar, med olika aktivitets-\ngrad. Hel orkester, dvs. 8 - 10 musiker, samlas som regel till de stora evenemangen\nsåsom Barbara och Vårbal. Däremellan varierar orkesterbesättningen betydligt - från\ntvå till åtta man. Orkestern kan även formera sig på olika sätt, som blåsarensemble,\nkammarensemble eller som solister med ackompanjemang. Under senare år har orkes-\ntern haft förmånen att bland medlemmarna kunna inräkna professionella musiker som\nHåkan Molander, cello, och Jacob de Verdier, violin, vilka vid flera tillfällen visat sin\nvirtuositet. Även andra medlemmar av orkestern har förgyllt gradgivningar och mål-\ntidskalas med solomusik. Ledaren för Den Bacchanaliska Kören, yrkespianisten\nClas-Olof Lindqvist, är egentligen inte medlem i orkestern, men måste ändå räknas\nmed på grund av alla soloinsatser och ackompanjemang, som han har ställt upp med.\n   Vid Jönköpings Bacchanaliska Akademis Högtidssammankomst har det blivit tra-\ndition med framförande av Bellmanmusik för två valthorn, exekverad av ”De Två\nMovitz”. En ny tradition sedan tre år är Bellmandagen vid Rosenlunds herrgård. Även\ndå medverkar denna grupp, klädd i tidsenliga 1700-talsdräkter.\n\nFramtiden\nI hela landet ser man idag ett vikande medlemsunderlag i olika orkestrar. Flera har lagts\nned och en del vilar sin törnrosasömn i malpåse. Ungdomen dras till andra instrument\noch annan musik. De vill ha elgitarr och synthesizer. Kommer vi i framtiden inom Par\nBricole att ersätta Bellmanmusiken med rock, pop och rap? Den som lever får se. Vi\ntror i alla fall på ett framtida Par Bricole och på en framtida Bacchanalisk Musik. Och\nnog kommer 1700-talets anda att även i framtiden sväva över oss och påverka oss.\n\n\n\n\nDen Bacchanaliska Theatern. Några nedslag i\ndess liv och leverne\n”Mot välvisheten ditt löje håll\n Möt bitterheten med sång.”\n(Skalden Talis Qualis’ maning till Par Bricole vid Moderlogens hundraårsjubileum.)*\n*( Skalden och ledamoten av Svenska Akademin Carl Vilhelm Strandberg (Talis Qualis)\n(1818-1877) blev medlem i Par Bricole år 1840 och var en flitig Broder. Han skrev\ntexten till ”sekelkantaten” med musik av Ludvig Norman. Red:s anm.)\n\n\n                                                                                     107"}, {"pdfPage": 109, "printedPage": null, "text": "Vi skriver några år in på det tjugonde århundradet, en tidig vårnatt ligger blånad över\nVättern utan att vinterns kyla släpper taget. Från Stora Hotellet kommer Ordensbröder\nut efter en trevlig samvaro i bricolleriets andra grad, deras glada tal och skratt ljuder\növer hotellplanen. Någon i sällskapet småsjunger på en kuplett han hört i kvällens spex.\nAndra dividerar om det är dags att gå hem, var och en till sig, eller om det passar med\nen stunds samvaro på någon av Jönköpings pubar eller restauranger. Kvällen har varit\nlyckad, för några timmar har bricollisterna upplevt minnet av Carl Michael Bellman\noch ett 1700-tal med ordensliv, upptåg och medryckande kamratskap. Gruppen av\nBröder tänker nog inte på sig själva som länkar i den mänskliga kedja mellan då och nu,\nsom är Par Bricole. Men sedan Jönköpings Par Bricole bildades har fyra generationer\nav bricollister lämnat hotellet på det viset. Vandrat ut i Jönköpingsnatten stärkta av\nsamvaro, underhållning, god mat och dryck. Stora Hotellets Spegelsal har varit dess\nförgyllda inramning i tid och rum och salens stavparkett teaterns tiljor.\n\nDen lilla staden\nAntalet restauranger att välja på för fortsatt samvaro under förra seklets början var inte\nså många, som Jönköping nu visar upp. I gengäld ställde man då ofta till med ”nach-\nspiel” efter sammankomsterna, där teatern fortsatt fick uppträda och underhålla. Teater-\nverksamheten var betydligt mer omfattande under Jönköpings Par Bricoles första de-\ncennier än vad den är i dag. Då Sällskapet föddes hade staden idyllens format. Det var\nen liten ämbets- och tjänstemannastad, där de högre kvaliteterna först och främst var\nherrarna i Kungliga Göta hovrätt och därefter garnisonens officerskår. De på 1870- och\n80-talen rätt strama juristerna i hovrätten anslöt sig gärna till PB, särskilt sedan någon\nav hovrättens presidenter visat vägen. De levnadsglada unga officerarna kom utan häm-\nningar. Handels- och hantverksmännen tog gärna emot dem och det var inget fel på den\nbroderliga samvaron.\n\nTeaterns roll\nPar Bricoles ursprungliga grundare, Olof Kexél, var en teaterns man och tillskyndare.\nHans grepp var klassiskt. Både hos de gamla grekerna och Shakespeare var det endast\nmän och pojkar som stod på scenen. Och Par Bricole var och är en männens orden.\nRedan i begynnelsen slogs de bricollistiska bräderna upp i den lilla ”Vetterstaden”, på\nvilka Thalias mer eller mindre äkta barn skulle bidra till Brödernas anständiga munter-\nhet, då Jönköpings Par Bricole bildades 1879, hundra år efter moderlogen i Stockholm.\n    Den Bacchanaliska Theatern inom Det Lysande Sällskapet Jönköpings Par Bricole\nhar olika uppgifter i ordenslivet. Den mest omfattande och underhållande uppgiften är\natt i samband med Andra Graden roa Bröderna med ett spex på scen. Här får teatergrupp-\nens medlemmar chansen att spela upp och spela ut i sångnummer och dialoger. En\nannan uppgift är att inom ritualernas ramar gestalta delar av handlingen i Arbetsgradernas\nreceptioner. Där ges liten möjlighet till förnyelse, då teaterns uppgifter är hårt knutna\ntill gradernas ursprung av text och form. Här krävs mycket av en Teaterdirektör för att\n\n\n108"}, {"pdfPage": 110, "printedPage": null, "text": "få ihop en ensemble till ett engagerat och följ-\n                                         samt spel, efter handlingen i Par Bricoles\n                                         traditionsbundna ordensliv. En tredje uppgift,\n                                         med vida möjligheter till improvisation och\n                                         bricollistisk lekfullhet, är att så gott som vid\n                                         samtliga tillfällen då Bröderna träffas spela upp\n                                         kalmuckiska skämt och andra ”störande inslag”.\n                                         ”Kalmucken är den som när bekymren möta,\n                                         står färdig genast att sin näsduk blöta” säger en\n                                         Ordensskald. För denna del av teatergruppens\n                                         verksamhet finns ingen bestämd scen, hela\n                                         Ordenslokalen står till förfogande. Utöver de\n                                         fastlagda uppgifterna har många Teater-\n                                         direktörer också passat på att öka teaterns in-\n                                         satser, allt efter idé och uppslag. Spexen kan ha\n                                         varit flera under ett år, andra uttryck för teaterns\n                                         sceniska glädje har också blommat. Allt hand-\n                                         lar om tid och lust; Stora barns lek under pompa\n                                         och ståt.\n\nTre överdådiga direktörer\nDen förste Teaterdirektören hette Axel Ekelund (1879-85) och var apotekare till yrket.\nHan ägde en ovanligt framstående musikalisk och mimisk begåvning, som beredde\nBröderna många stunder av glädje. Någon Balettmästare fanns inte vid den tiden, en\nsådan valdes först långt senare. Ekelund började sin bana som Teaterdirektör genom att\ni mars 1880 ge en operett med den lovande titeln ”Hin håle i mjöllåren”. I maj månad\nsamma år ordnade han en ”Theatre Variété” med framstående artister som ”Baraskoj,\nkomiker vid operan i Habo, fagottvirtuosen Fusk från Halmstad och en balettmästare\nfrån Kongl. Teatern i Grenna”. Följande år återkom varietén och Bröderna fick bland\nannat se en flaska munväder från Norska fjällen samt Överblivna kartan, endast för\nherrar.\n   Med Axel Ekelund grundades alltså den Bacchanaliska Teatern i Jönköping 1879.\nEn teater som till Brödernas förnöjelse och gradgivandets förhöjande skulle under-\nhålla, skapa glädje och stämning. Det man fick se på dess tiljor framkallade ofta ”hög-\ntider av skratt och sällskapet vann stark tillslutning just för dessa glada nöjen, vilka för\nmedlemmarna voro ett angenämt och välkommet tillskott till stadens nöjesliv för öv-\nrigt”. Och många är de Vätterbygdens begåvningar, som med håriga ben framträtt som\nväna jungfrur på bricolleriets tiljor, eller dansat över scengolvet med gracen hos en\nartilleriöverste. Ett Ordensväsen utan upptåg och underhållning, sång och musik, skulle\nbli allt för stramt och allvarligt för att stämma med Par Bricoles grunder och Bellmans\nliv och leverne.\n\n\n                                                                                         109"}, {"pdfPage": 111, "printedPage": null, "text": "Stark profil\nAxel Ekelund kom att kallas den förste, store\nTeaterdirektören. Den andre av direktörerna var\nOlle Blank (1885-90), som satte stark profil på\nteatern. Han var stationsskrivare till yrket. Om\nhonom sägs det att han inte bara var en stor skäm-\ntare utan också en charmerande människa. ”Hans\nglada lynne, frodiga humor och stora komiska ta-\nlang” kom nu Par Bricole till del. ”Blank var ak-\ntör, folkskildrare, imitatör och lycklig sångare i\nen person.” Han kallade sig som Teaterdirektör\nJean Gauthier, en på den tiden kringresande och\nmycket bekant ”menageridirektör”. Blank debu-\nterade också med ett större galaspektakel, ”till vil-\nket enligt upplysning särskild liktornsoperatör för\nkvällen engagerats i händelse av stor trängsel vid\nin- eller utgångarna”. I januari 1889 ger Blank en stor ”chinesisk folkfest, därvid bl.a.\nen ofärdig musikförening från Bankeryd medverkar...” En annan gång hade han japaneser\npå scenen och citerade djärvt på sin affisch följande dräpande omnämnande, som hans\ntrupp fått i Tenhults Weckoblad Tallkotten för sina prestationer; ”i stället för blommor\nkastade publiken sten”. Blank framstår i historiens ljus som en av de mer levnadsglada\noch framträdande Teaterdirektörer Sällskapet haft. Inte minst hans olika programblad\nvar orgier i tokroligheter. Dåtidens humor kan förstås vara svår att förstå i dag, inget\nkan bli så gammalt som ett skämt. Humor är som bekant ett livsmedel.\n\nBred begåvning\nDen tredje, store Direktören under Sällskapets första decennier (1890-1895) blev\nteckningsläraren vid Jönköpings Högre Allmänna Läroverk Harald Theodor Uddén med\nordensnamnet Professor Janne. Han övergav burleskerierna och bjöd istället på upp-\nskakande skådespel och vågade skuggspel. ”Yapanas dom” eller ”Det hemliga gifter-\nmålet”, en andalusisk opera seria med greve Aqvavito som huvudfigur, var ett av hans\nmånga spel. Ett annat hette ”Spökerierna i hotellträdgården”, där H. H. Mefisto\nuppträdde i sällskap med Vaggeryds- och Gripenbergsbanan. Uddén var en mycket\noriginell man och en av bricolleriets hängivnaste medlemmar, han blev mäkta populär\nbland Bröderna. Få har med sådan ihärdighet ägnat sig åt PB: s tjänst. Visserligen kunde\nJanne vara övermåttan sarkastisk och despotisk som teaterdirektör. Men de som kände\nhonom nära, visste att hans hjärta var gott och hans sinne välvilligt. Han ritade och\nskrev också små häften, kallade ”Kludderier av Sudden”. Ett av hans satiriska stick\nhandlade om Jönköpings kyrkor, som var så fullsatta på söndagarna att kyrkobesökarna\ntog fällstolar med sig för att slippa stå. Denna ström av människor på väg till kyrkan,\nalla med en fällstol i handen, döptes av Uddén till ”Stolgång”.\n\n\n110"}, {"pdfPage": 112, "printedPage": null, "text": "I Jönköpings Länsmuseums samlingar finns en målning kallad ”Jönköpings hamn i\nmånsken”, målad på 1870- eller 80-talet. ”Tavlan föreställer Jönköpings hamn med\nvågbrytare och fyr och några förtöjda skutor. Till vänster i målningen skymtar stadens\nöstra stadsdel och i bakgrunden ligger Stora Hotellet och inloppet till själva hamn-\nkanalen. Över staden lyser en blek måne på en romantisk himmel med mörka moln.\nTavlan är ett verk av en konstnär helt besjälad av romantiskt måleri, nämligen ritläraren\nHarald Theodor Uddén”. Professor Janne var verkligen en begåvning på många områ-\nden. Han hade sin bostad i det kvarter där Par Bricole i dag har sitt kansli.\n    När han dog fick han en mycket högtidlig jordfästning i Sofiakyrkan. Själv hade\nJanne Uddén önskat sig en helt annan begravning, med bara en sång av Bellman: ”Hvem\när som ej vår broder minns, fastän han skugga mer ej finns.” Men hans önskan var inte\ntillräckligt konventionell för att kunna tillfredställas.\n\n\n\n\n                                                                                                    •1'\n\n\n\n\n                                                                    \\\\“\"1、1/ r·→I•□9□\n                                                          llfv,•r\n\nRitläraren vid Jönköpings högre elementarläroverk Harald Theodor Uddén ( 1838 - 1896), har\nutgivit en rad små skrifter med teckningar ofta av skämtkaraktär. Här driver ”Janne” eller\n”Sudden”, som han även kallade sig med samhällslivet och skjuter sina vassa pilar. Uddén var\näven bricollist under sina senare år. Han bodde länge i det trähus på Ö Storgatan 6, som vid\nsekelskiftet ersattes av det nuvarande stora stenhuset där Par Bricole har sina lokaler. Han var\nen uppskattad lärare och en känd profil i staden. Genom sina teckningar och målningar har\nhan dokumenterat staden under 1800-talets senare del. Detta är en av två teckningar under\nrubriken ”Våra ordnar och samfund.” En gradgivning inom Par Bricole såsom han uppfattade\nden med mottot ”Supa klockan öfver 12.” Den publicerades 1882 i ”Små roligheter uti\nJönköping”. Foto: Jönköpings läns museums arkiv.\n\n\n                                                                                                   111"}, {"pdfPage": 113, "printedPage": null, "text": "Unikt Ordensliv\nAll konst är eklektisk. Det gäller att lära av andra, låna, utveckla och förädla. Vilka\nförebilder hade våra första bricollister inom teatern - långt innan film, TV och Riks-\nteater? I motsats till Stockholm och Göteborg hade Jönköping inte några professionella\nskådespelare och dansare att dra in i ordenslivet. Det var först 1978 som Jönköpings\nLänsteater, numera Smålands Musik och Teater, fick en scen i staden. Redan i början av\n1800-talet besöktes dock Jönköping flitigt av resande teatersällskap vilket uppskatta-\ndes livligt av stadens borgare. Vid sångpjäser biträddes orkestern även av musikälskare\nfrån staden. Inte olikt dagens Par Bricole där amatörer och professionella i talang-\ngrupperna samarbetar för Brödernas bästa, något som gör vårt Sällskap unikt i svenskt\nordensliv. De resande teatersällskapens gästspel var säkert mycket inspirerande för de\nteateramatörer, som ägnade kraft åt Jönköpings Par Bricole. Antagligen besökte också\nflera av bricollisterna andra och större städer än Jönköping för sitt nöjes skull och fick\ndär idéer om spelstil och form.\n\nHög beskyddare\nNågra årtionden innan Jönköpings Par Bricole bildades inträffade en teaterskandal i\nstaden, då teaterdirektör Wallins sällskap skulle framföra August Blanches lustspel\n\n\n\n\n Tablå över tiljans män och uppförda skådespel under epoken H.T.Uddén (1890-talet).\n\n\n112"}, {"pdfPage": 114, "printedPage": null, "text": "”Döden fadder”. Eftersom sällskapen på den tiden inte kunde medföra egna dekoratio-\nner eller möbler på grund av de svåra kommunikationerna fick man låna sådana på\norten. I Blanches lustspel förekommer två porträtt, som skulle föreställa ett par rysligt\nhemska skurkar. Rekvisitören som hade glömt att ta med tavlorna blev i sista minuten\ntvungen att skaffa nya. När han återkom med de bägge lånade porträtten befanns ett av\ndem föreställa Sveriges Konung Oscar I. Direktör Wallin hade då att avbryta spektaklet\neller låta udda vara jämnt. Han valde det senare. Den uppståndelse det skapade hos en\nhäpen publik, när spelet kommit igång och hemligheten med de bägge porträtten avslö-\njats, kan man lätt tänka sig. Och på stående fot förbjöds Wallin av Landshövding\nBergenstråhle ”att vidare med sitt sällskap uppträda i Jönköping”! Inom Par Bricole\nskulle ett sådant intermezzo vara otänkbart då kungen är sällskapets högste beskyd-\ndare, ett arv från Gustav den III: s dagar. Den monark som införde teatern som konstart\ni Sverige och blev stor tillskyndare av Bellman, bricolleriets förste och störste ordens-\nskald.\n\nFantasi och verklighet\nJönköpings Par Bricole har under sina 125 år i stort sett haft alla sina sammankomster\npå Stora Hotellet. Där har Sällskapets inventarier också förvarats. Teaterns förråd finns\ndock numera i utrymmen som disponeras på Tändsticksområdet, där Teatern repeterar\nsedan slutet av 1980-talet. En hastig titt i gamla förteckningar över förråd av kläder,\ndekor och rekvisita ger en lustig inblick i ordenslivets sceniska värld. Fem balettdräkter\nav tyll, åsnan, fyra harnesk av bleckplåt, sex träsvärd, ett par damkalsonger, ett hvitt\nspetsförkläde, två rococodräkter (livrockar), ett par orientaliska skor, fjorton trattar af\npapp, två åror, en sufflörlucka med skåp, två fonder, fyra skog kulisser - och mycket,\nmycket mer av allt det som behövs när man skall ha skoj!\n   Repertoaren ger också hopp om glädje. En titt på de sista femtio årens spellistor\nvisar att bröderna fått möta spännande spex med namn som ”Grand Cabaret”,\n”Gycklarnas afton”, ”Tant Charlottes Testamente”, ”Cirkus Ungefär - med väldigt vilda\ndjur och clowner”, ”Piazza”, ”Högt spel om Nicanorka”, ”Ljuva 60-tal”, ”Vätterpirater”,\n”Parbrikollaren”, ”Kompaniafton”, ”Kvinno(l)året”, ”Obs Alla är amatörer”, ”Automat-\nskratt AB”, ”Transport - Spexet”, ”Adam” och ”Damlösa Brunn”. Detta som axplock\noch smakprov på en rik, stor och fantasifull repertoar, där de olika spexen - allt tokigare\noch påhittigare - avlöst varandra.\n\nRestriktionstider\nYtterligare nedslag i teaterverksamheten visar att spexen florerade som ymnigast under\n1920-talet. I en rad av år blev det då - trots skattmästarens hjärtslitande klagorop över\nenorma repetitionskostnader - även ett spex i Första Graden. Aldrig har väl en sådan\nbifallsstorm utbrutit ens på Dramatiska Teatern i Stockholm, som när en av Bröderna i\nett sådant spex - han var apotekare - räckte över tio liter hembryggd punsch till publi-\nken i en korg över rampen. Detta hände i den allra värsta restriktionstiden och fru\nPersson, som då ägde Stora Hotellet, befarade att bifallet skulle komma en stor del av\n\n                                                                                       113"}, {"pdfPage": 115, "printedPage": null, "text": "Kaparkapten DfBT Bror Nätt och Styrman Gerhard Sjöström i spexet Vätterpirater år 1962.\n\n\n\nhuset att rasa. Verkligheten har, som man kan förstå, en ständig medskapande roll inom\nden Bacchanaliska Theatern.\n   Teatern gav under sina första decennier på 1800-talet och en bra bit in på 1900-talet\nen mycket varierad repertoar av tal- och musikspex. Men under unionskrisen med Norge\noch de bägge världskrigen låg verksamheten nästan nere. Krig och dåliga tider främjar\ninte ordensliv och nöjen. Under en rad av år på 40-talet nämns teaterns verksamhet som\nnästan parodisk. Uppgiften togs inte på allvar och aktiviteterna blev inte heller som\nman tänkt sig. Sällskapet tycktes också sakna en ändamålsenlig scen. Många föreställ-\nningar fick spelas upp på närmsta biograf eller vid något tillfälle på Jönköpings Teater\nvid Hovrättstorget.\n\nTradition och förnyelse\nUnder alla år har diskussion pågått inom teatern om man skall ha en röd tråd i hand-\nlingen eller lägga upp spexet som en nummerrevy? Oftast har man valt nummerrevyns\nform. Kanske har det legat praktiska skäl bakom det valet? Långt in på 40-talet och\näven många år därefter fick ofta varje skådespelare sätta ihop sin egen text och repetera\nden i hemmet, ibland kanske tillsammans med de andra aktörerna över en kopp kaffe på\nett café. Teaterdirektören tittade måhända på resultatet först vid generalrepetitionen,\nnågon dag innan premiären, då alla aktörer samlades. Under senare decennier har större\n\n\n114"}, {"pdfPage": 116, "printedPage": null, "text": "ambition lagts ned på att repetera ihop spelen och skriva spex med sammanhängande\nhandling. Direktörerna har i ökad grad försökt att höja kvaliteten på text och spel inför\nvarje framförande. Tråkigt nog ledde arbetet oftast till både premiär och sista föreställ-\nning på en och samma dag. Sällan eller aldrig framfördes spexen vid flera tillfällen\n(undantag finns). Teatern har sin publik när Bröderna träffas, när de olika gradgivningarna\nställer krav på teaterns medverkan. Under andra delen av 40-talet började aktörerna\nbjuda in sina anförvanter till en generalrepetition eller till en föreställning av spexet\nnågon vecka senare för att kunna spela fler gånger. Bröderna kunde då visa sina nära\noch kära vad de gjort med en stor del av sin fritid. Det nya inslaget i bricolleriets\nverksamhet hade det goda med sig att revyförfattarna fick hålla sig på en god nivå och\nbalansera humorn ovanför naveln. Deras fruar skulle ju så småningom bevista föreställ-\nningen.\n   Omvärldens utbud av nöjen, film, TV och scenproduktioner, har bidragit till att skärpa\nTeaterns underhållning. Bröderna har i takt med utvecklingen blivit mer kritiska och\nfordrande i sina krav på nöjen och roas inte längre av allt för orepeterade och\nogenomtänkta spel. Mer än tvåhundra år av tradition måste självklart bevaras - men\nockså utvecklas. Sällskapet får inte fastna i det förgångna utan relation till nuet. Gam-\nmalt och nytt måste gifta sig och oupphörligen få nya barn av vår tid. En uppgift som\nTeaterns Direktörer, textförfattare och aktörer, under de senaste sex decennierna, med\nskiftande framgång har lyckats med. Teater är ögonblickets konst, i den blinkningen\nskall historia och nutid mötas annars är ögat inte seende.\n\nTeatern och kören\nEn recension av ett spex från början av 1980-talet, i Sällskapets tidning Avisa ger oss en\nbild av hur det gick till en kväll då Teatern spelade upp.\n   ”Plats på scen för Den Bacchanaliska Theatern för att, med hjälp av sina allestädes\nbefintliga fusklappar, sparka igång ett sprudlande Spex med Theaterdirektören Per\nGunnar Karlberg som primus motor. Ingemar Florberger sjöng första kupletten på\nnästan samma melodi som gitarrackompanjatören Peter Gadh knäppte fram. Anders\nRuberg, klippan i ensemblen, hade fått många bejublade entréer på sin lott. Ett upp-\nskattat inslag var naturligtvis reprisen på ”Kvartetten som sprängdes”, en sångligt\nförnämlig prestation av Per Gunnar Karlberg, Anders Ruberg, Sune Winald och Jan-\nErik Berggren samt med ”pinupen” Sigvard Ek som framträdande blickfång. Även\ndensammes ”Jönköping by Night” med välskriven text satt fint. Per Gunnars små\ngliringar till De Styrande gick fint hem. Benno Holm briljerade med ”The Whisky\nStory”. Tidigare nämnda kvartett förstärkt med Dag Holmgren och med assistans av\nKören exekverade ”Vi hörs och vi syns”. Mycket, mycket mera som framfördes skulle\ngivetvis kunna omnämnas. T ex att texterna var författade av de medverkande i allmän-\nhet och Sixten Larsson i synnerhet, samt att den 35-åriga snart klassiska Finalen ”Här\npå PB är det ingenting som glädjen stör”... fortfarande hänger med - upphovsman John\nKoch.\n\n\n                                                                                       115"}, {"pdfPage": 117, "printedPage": null, "text": "Teatern och Kören inom PB är som ler och långhalm, de hänger verkligen ihop och\nutgör grunden till Sällkapets ordensliv. Båda står samtidigt på egna ben och båda\narbetar ofta samman i spex och andra tokigheter.\n   ”(1958) Vid måltidskalaset gav Bacchanaliska Theatern ”Cirkus Ungefär” en före-\nställning som bejublades av Bröderna och som teaterchefen Gemfeldt och hans mannar\ninte minst regissören Gunnar Bengtsson hade heder av.\n   (1961) Teaterdirektören Bror Nätt med medhjälpare framförde så ett bejublat spex\nmed Hovrättstorget som bakgrund och ironiserade över stadens styrande och händelser\nsom timat.\n   (1962) Kvällen slutade med att Bacchanaliska Theatern under Gösta Karlströms led-\nning gav ”Högt spel i Nicanorka”. I spexet medverkade Rolf von Otter, Bertil Karl-\nström, Karl Erik Gemfeldt, Lars Ruberg m.fl. Skådespelet mottogs med förtjusning av\nBröderna.\n   (1968) Så avslutades kvällen med att Bacchanaliska Theatern gav spektaklet ”GOOD\nOLD FACE”. Teaterdirektören Bengt Stenberg (också musikalisk ledare år 1967) hade\nall anledning känna sig tillfredställd med sina förmågor och att spexet uppskattades\nframgick med all tydlighet av de applåder och hörbara förtjusning som mötte fram-\nförandet. Textförfattare Lennart Halldorf medverkade liksom Bröderna Lars Ruberg,\nIngemar Florberger, Rolf von Otter, Jan-Erik Berggren, Hans Roman, Helmer Johans-\nson och Hans Swartz. Briljant ackompanjatör vid pianot var teaterdirektören själv.”\n\nTiljans olika begåvningar\nDe medverkande, som här nämns i recension och protokoll, är några av en mängd\nBröder, som alla haft betydelse för Teaterns arbete under 1900-talets sista decennier.\nIngemar Florberger till exempel ansågs vara den borne Bricollisten. Han var Teaterns\nDirektör under några år (1973-1975) och var den Broder, som bäst kunde spela såsom\nen berusad kalmuck. Han myntade också det bevingade uttrycket: ”Bröder, nu går vi ut\nmaximalt, sen ökar vi efter hand!” Anders Ruberg blev tidigt den obestridde skåde-\nspelaren/spexaren i Par Bricole. Med stark sångröst, härlig fysik och fin närvaro på\nscenen, bär han med stor spelglädje upp allt han får att göra. Begåvningen har han\nsäkert ärvt från sin far, Lars Ruberg, en spexens verklige nestor. Far och son Ruberg har\npå ett förnämligt vis skrivit in sig i Jönköping Par Bricoles teaterhistoria.\n   Ett annat par av far och son Hans och Mikael Svartz går också till Sällskapets teater-\nhistoria. Fadern var Sällskapets Balettmästare och sonen har nu övertagit den rollen.\nUppgiften som Balettmästare är svår. Den gäller att ha förmågan att plocka fram den\nbegåvning, som ligger i Brödernas fötter. I recensionen ovan nämns också en Sune,\nhans efternamn var Winald. Sune var utan konkurrens Par Bricoles i Jönköping störste\n”Bellman” i modern tid. Det är få förunnat att äga den gåva Sune ägde, som tolkare av\nBellman, sångare och underhållare. Den ”Lutande Mästaren” Sune Winald blev en\nlegend inom hela Bricolleriet redan under sin livstid. Sixten ”Skrivare” Larsson bidrog\n\n\n116"}, {"pdfPage": 118, "printedPage": null, "text": "Spexet Ulla III i\n                                                                 Stadsparken år 1984.\n                                                                 Sittande vid bordet f. v.\n                                                                 Bo L. Spång och Leif\n                                                                 Thor.\n\nmed många texter i de recenserade spexen under åren. Han stod också själv på scenen\noch sjöng eller agerade med bravur.\n   De nedslag som Jubileumsskriften gör kring Sällskapets teaterhistoria syftar till att\nmåla upp en bild av verksamheten, inte att berätta om tiljans alla begåvade Bröder i\nJönköping. Några ytterligare profiler skall vi ändå dröja vid. Sixten Larsson var långt\nifrån den enda duktiga pennan inom Sällskapet. Andra namn kommer upp, som\n\n\n\n\nSpexet Ulla III år\n1984.\nF. v. Sigvard Ek, Bo\nBerntsson och Ingemar\nFlorberger.\n\n\n                                                                                        117"}, {"pdfPage": 119, "printedPage": null, "text": "Rutinerade estradörer\nsaluterar år 1983.\nF. v. Ingemar Florberger,\nSigvard Ek, Sixten\n”Skrivare” Larsson,\nBo L. Spång och Karl-\nErik Gemfeldt.\n\n\n\nLennart ”Bissen” Halldorf, Gunnar Gårdmark och Kurt Rudolf Malmgren. Halldorf\nvar journalist på Jönköpings-Posten, noga med skrivreglerna och författare till många\ntexter till Teatern. Han var en verkligt flink skribent, som kunde fånga och häckla dags-\naktuella händelser i samhället. Bissens texter kunde lyfta revyerna till höga höjder.\nSketcher och buskis var inte hans gebit, sångtexter var hans arena. Bissen Halldorf\ninsåg att de duktiga aktörer han skrev för också kunde roa en större allmänhet. Han\nvände Sällskapets Teater ryggen, tog med sig några av aktörerna och bildade Sällskapet\nKommunalskratt. Ett revygäng som sedan 1974 med sina nyårsrevyer är en institution i\nJönköping. Till sin hjälp fick han ett par verkligt garvade scenrävar, Rolf von Otter och\nLasse och Anders Ruberg. Dessa gled över till lokalrevyn men fortsatte även att göra\nbejublade inhopp i Sällskapet. Rolf var den allsidigare och kunnigare av dem medan\n\n\n\n\nOrdens Balettmästare Hans Svartz och hans son Mikael Svartz, som ärvde ämbetet.\n\n\n118"}, {"pdfPage": 120, "printedPage": null, "text": "Lasse Ruberg som ”naturskådespelare”\n                                                    agerade genom sina olika ”roliga figurer”.\n                                                    Båda var stora scenpersonligheter och\n                                                    ägde stark närvaro på scenen. Var för sig\n                                                    var de härligt publika och fyllde scenen\n                                                    bra - men tillsammans blev upplevelsen\n                                                    total. Rolf von Otter är än i dag en upp-\n                                                    skattad och kär underhållare ända upp på\n                                                    riksnivå.\n\n                                                    Moderna tider\n                                                    Teatern kanske inte kan skryta med att ha\n                                                    haft några ”överdådiga direktörer” under\n                                                    de senaste femtio åren. Även om Dan\n                                                    Ekströms period som direktör (1989-93)\n                                                    skiljer ut sig från mängden. Samtidigt är\n                                                    det så mycket enklare i en jubileums-\n                                                    krönika att skriva om de som har gått bort;\nSune Winald på Barbaradagen 1986.\n                                                    deras insats kan ses i en helhet och om de\n                                                    döda inget ont. Det har under åren också\n\n\n\n\nKuplettens komplette mästare: Rolf von Otter. 1980-tal.\n\n\n                                                                                           119"}, {"pdfPage": 121, "printedPage": null, "text": "blivit allt svårare för Bröderna att sätta av tid till arbete inom Teatern. Verksamheten har\näven blivit kostsammare och kraven ställs så mycket högre. Vid sidan av Direktörernas\n”trägna arbete i vingården” har teaterkollektivet i allt högre grad utmärkt sig. Modernt\nledarskap har gjort insteg i det gamla Par Bricole. Direktören är en coach, teater är\ninget för elitister och ensamvargar. Samtidigt hänger det på att aktören verkligen kan\nsin roll, vet att samspela med sina kolleger och lyfta fram spelets berättelse. Gångna\ntiders teaterspel bars mest upp av enskilda starka personligheter och deras rollfigurers\ngrimaser och tokroliga uppsyn. Naturligtvis måste spelglädje finnas, även de stora ut-\ntrycken, men allt för yviga gester blir just för stort. De senaste decenniernas aktörer har\nmer lagt vinn om ett vårdat och nyanserat spel. Den moderna teaterns framväxt i Sverige\nhar även lämnat spår inom ordensväsendet, visserligen inte genom psykologisk realism\ni gestaltningen utan genom en nedtonad och balanserad spelstil. Vi talar nu om nyanser,\nförstås.\n\nEn ny sorts direktör\nDen Bacchanaliska Teatern är som allt ideellt föreningsliv starkt beroende av de be-\ngåvningar som för tillfället känner sig manade att delta. När flera av de engagerade\nBröderna lämnade teatern i början av 70-talet för att ägna sin tid åt Kommunalskratt\nkom det att innebära svårigheter för Par Bricole. Visserligen fortsatte Teatern sitt\narbete, men hade under några år svårt att klara ut sina uppgifter och hålla kvalitén.\nEn Teaterdirektör, som verkligen drog sitt strå till stacken för att stärka teatern och höja\nkunskaperna hos dess aktörer, var Dan Ekström, lärare på Högskolan till professionen.\nHan tog hjälp av den nystartade Jönköpings Länsteater och gav Bröderna fortbildning\nav olika slag. Han ville odla en mer naturlig spelstil, samtidigt locka fram de enskilda\nkvaliteterna och skapa medvetenhet om helheten. Tal och rörelseövningar var ett led i\nden utvecklingen. Kontakten med Länsteatern (Smålands Musik och Teater) har sedan\ndess funnits kvar i högre eller mindre grad, allt efter att Direktörerna växlat. Redan som\nbiträdande Teaterdirektör tog Ekström initiativet till att teatern fick disponera en 50-60\nkvadratmeter stor övningslokal på Tändsticksområdet. Teatern har fortfarande denna\n”teatervind” till sitt förfogande. Det är en utmärkt repetitionslokal. I den fasta inred-\nningen ingår också en mindre scen.\n\nFramgångsår\nDan Ekströms tid som Direktör blev en framgångsrik period för Den Bacchanaliska\nTeatern. Han iscensatte en rad uppskattade spex - Bar Bricole, Far Bricole, Bad Bricole\noch Dam Bricole - som för tankarna till de tre stora Teaterdirektörernas tid från Sällska-\npets begynnelse. Ekströms arbete som Teaterdirektör fick Knut-Erik Jahnke att upp-\nskattande skriva: ”Under de 50 år jag haft glädjen att tillhöra Par Bricole har jag inte\nupplevt en så ”Blomstrande” och idérik konstellation av lysande Talanger”. I början av\n1990-talet producerade Ekström ett par mycket stora spex för offentligheten,\nOperamaskeradbalen och Magnus Ladulås, där Par Bricole visade upp sig i kommunen\n\n120"}, {"pdfPage": 122, "printedPage": null, "text": "som aldrig förr. Magnus Ladulås fick även kommunalt ekonomiskt stöd. De båda spexen\nfick stort genomslag i både den kalmuckiska och bricollistiska världen. Det är teater-\ninsatser som överstiger vad som tidigare åstadkommits och kan betraktas som höjd-\npunkter inom Jönköpings Par Bricoles teaterhistoria. En gammal kines har sagt: ”En\nteaterföreställning ska säga något om hur människan bör leva, den skall också säga\nnågot om hur världen är beskaffad och bör dessutom spelas på ett sådant sätt att även en\nberusad kan ha behållning av den.” Det är visdomsord som kärntruppen kring Ekström\nskulle kunna skriva under på och de allra flesta Bröderna känna igen sig i.\n   Utan goda medarbetare står sig varje Teaterdirektör slätt. Under den Ekströmska\neran var kreativiteten synnerligen hög. Hans ledarstil stimulerade medverkande förfat-\ntare, scenografer och aktörer till stordåd. Den professionella ambitionen var tydlig.\nSamtliga aktörer bidrog även med egna texter med Bröderna Gunnar Gårdmark, Kurt\nRudolf Malmgren, Gert Karlsson och Leif Thor i den absoluta frontlinjen. Dessa stod\näven på scen, sjöng och agerade. Mycket arbete lades också ned för att skapa förutsätt-\nningar till bra ljud och ljus i spexen. Roland ”Blyger” Söderbom ansvarade för den\ninsatsen, som sannerligen är en både slitsam och otacksam uppgift. Spegelsalen på\nStora Hotellet är inte helt lätt att förvandla till en se- och hörbar arena för teater. Andra\ni kärntruppen var Bröderna Sune Winald, Anders Ruberg, Bo Berntsson, Benno Holm,\nBo Spång, Ingemar Florberger och Jan-Erik Franzén - som dessutom med hjälp av\n\n\n\n\nUr spexet Bad Bricole år 1991. Leif Thor, Anders Ruberg, Kurt Malmgren, Stefan Svartz, Mikael\nSvartz och sittande Dan Ekström.\n\n\n                                                                                            121"}, {"pdfPage": 123, "printedPage": null, "text": "Åbros öl såg till att repetitionerna blev glada tillfällen. Broder Lars ”Pålle” Paulsson\nvar den mesta scenografen hos Ekström, en skicklig dekoratör med egen firma för\nutställningsmontrar vid mässor och liknande. Hans yrkeskicklighet kom väl till pass i\nden idévärld av spex som Ekströms kärntrupp levde i.\n\nTeaterrummet\nInom den professionella teatern i Sverige växlades yrkesbeteckningen dekoratör över\ntill begreppet scenograf under det tidiga 1960-talet. Nu såg man till hela scenbilden\ninte bara till dekoren i form av målade fonder och kulisser. Den inom Den Bacchanaliska\nTeatern, som hade ett yrke med tillgång till sådant som kunde utgöra dekor i teaterns\narbete, fick ofta uppdraget att ”möblera” scenen. Scenograferna inom Sällskapet har\nväl i allmänhet inte gjort så stort väsen av sig. Lars ”Pålle” Paulsson och konstnären\nPeter Gadh anses vara de två främsta inom Jönköpings Par Bricole.\n    Ett exempel på hur dekorationsarbetet under tidigare år kunde gå till var när Gunnar\nBengtsson under teaterdirektör Karl-Erik Gemfeldts (1956-1960) ledning, skulle regis-\nsera spexet ”Cirkus Ungefär” där det utlovades ”väldigt vilda djur” på scenen. En av\naktörerna var Bror Nätt, som blev Direktör efter Gemfeldt (1960-1962), han minns hur\ndet var: ”Vi skulle göra ett annorlunda spex med sammanhängande handling. Planering\noch textarbete drogs igång redan under hösten. Vi ville ha god tid på oss. Premiären låg\ni mars året därpå. Broder Gerhard Sjöström tog på sig att bygga burar för de farliga\n\n\n\n\nSt.M Jan-Erik Berggren tackar de nybadade spexarna 1991 och scenografen Lars ”Pålle” Paulsson i\nsynnerhet.\n\n\n122"}, {"pdfPage": 124, "printedPage": null, "text": "djuren. Han ägde en rörledningsfirma och var därmed kvalificerad för uppgiften. Det\npraktiska arbetet lämnade han vidare till sin förman på firman. Därmed tänkte vare sig\nSjöström, Bengtsson eller vi andra något vidare på det hela. Månaderna gick och en ny\nidé om dekor tog form, vi skulle ha en målad fond. En annan Broder, K-G Gustavsson,\nsom ägde en dekorationsfirma och var en duktig scenograf inom Sällskapet, tog på sig\nuppdraget. Han gjorde reklamskyltar till affärer och företag och att måla en dekor till\nspelet var inget problem för honom. Och burarna var ju spolade sedan länge. Rörlednings-\nfirmans nitiske förman däremot jobbade hårt med uppgiften, han hade inte hört annat.\nPå den tiden spelade vi på söndagarna. Och den dag då spexet skulle ha premiär körde\nfirmans stora lastbil upp framför hotellet. Fyra man hoppade ur och började baxa in\nstora, tunga, galler av järnrör, i bitar av två gånger två meter, genom Storans entré.\nGallren skulle monteras ihop på spelplatsen och vara burar till de väldigt vilda djuren -\nsom då hade blivit en höna och en kanin. Portieren hade verkligen ingen aning om att\nhotellet skulle byggas om. Och han protesterade högljutt mot att de tjocka\njärnkonstruktionerna skulle släpas in på Spegelsalens parkett. Så blev det inte heller.”\nAv händelsen återstår i dag en anekdot, som säger oss något om hur det kan gå till inom\nTeatern. Scenografin är en viktig del av ett skådespel, men det gäller att kunna fuska.\nDet skall bara se verkligt ut - inte vara det. Det är också en del av konsten.\n\nPar Bricole i världen\nJönköpings Par Bricole har även gjort internationella gästspel, bland annat genom sina\nnedslag i den danska kulturhistorien. Teaterdirektör Charles Petruson (1986-1989)\norganiserade med pengar från Nordiska Rådet resor till den danska staden Jaegerspris\nmed både kör och teater. Ett urklipp från Frederikssunds avis förmäler att gästspelet på\nJaegerspris teater blev en stor succé från allra första stund och samlade hela byns teater-\nförening och kulturelit. Avslutningsfesten, med aktörer och publik, blev en mycket sen\növning med diverse förvecklingar. När den tidiga morgonen svepte in byns slottspark i\nen mjuk dimma satt Charles Petruson och Sune Winald och hängde på en bänk tysta\noch trötta, klädda i 1700-talskläder, med perukerna på svaj. Tidningsbudet som då kom\ntrodde sig se ett par månghundraåriga gengångare, stannade och stirrade stort på de\nbägge figurerna. De båda Bröderna höll sig alldeles stilla, lyfte sedan samtidigt lång-\nsamt på huvudena och tittade tillbaka utan att röra en min. Tidningsbudet fick då en\nvådlig fart på benen och flydde från platsen. Antagligen har händelsen gett upphov till\nen lokal spökhistoria. Den Bacchanaliska Teatern har verkligen rykte om sig att göra\nintryck när den möter den kalmuckiska världen.\n\nLeve teatern\nTeatern är en omistlig del av Det Lysande Sällskapet Jönköpings Par Bricole, vilket\ntorde ha framgått av historiken ovan. Under de 125 år som gått sedan PB grundades i\nJönköping har 38 Teaterdirektörer grubblat på texter, aktörer och allt det som skall till\nför att få teatern på lätta fötter. Tio av dessa direktörer lever fortfarande jubileumsåret\n2004. Samtliga har hängivet arbetat för teatern och gjort insatser som Sällskapet inte\n\n\n                                                                                       123"}, {"pdfPage": 125, "printedPage": null, "text": "skulle ha klarat sig utan. Det tål att sägas igen; Par\nBricole är teater, sång, musik och talekonst. Bara\nså lever traditionen vidare och stimulerar Bröderna\natt verka inom Sällskapet. Vissa tider har varit\nsvåra - andra frustande festliga, fyllda av spex utan\nsans och måtta. Men då som nu sjunger aktörerna\nefter varje avslutat spex den visa som Teaterdirek-\ntör John Koch (1947-1950) skrev.\n\nHär på PB är det ingenting som glädjen stör\nVi roar oss jämt och är på jätteglatt humör\nOch kör det ihop sig någon gång\nSjunger vi bara denna sång\nDet är det som susen gör\n\nRidå!\n\n                                                         Benno Holms skepnad höljd i dunkel\n                                                         år 1990.\n\n\n\n\nJönköpings Bacchanaliska Akademi för Tale-\noch Skaldekonsten\nJan-Erik Berggren, Jeje kallad, Styrande Mästare inom Jönköpings Par Bricole åren\n1983 till 1993, hade många strängar på sin lyra. Han skrev, talade, tog och skapade\nkontakter, strödde idéer kring sig, ledde kapitel, var synnerligen generös, ja till\noch med sjöng några gånger. Allt i syfte att sprida sin omhuldande värme och\nglädje kring sig till andras och sin egen stora förnöjelse. Han var i sanning en sann och\nmycket varmhjärtad Broder och en genuin Bricollist! Hans valspråk var ”Ödmjukt leva,\nofta le”.\n   De idéer, som under denna kreativa tid närdes i kretsen runt Jeje och Jeja (Gerhard\nMattus, StK), tedde sig för många bricollister troligen lite omtumlande. Idéerna kring\ntalanggruppen Luculli Gille, exempelvis, var inledningsvis inte så väl sedda. Samma\nmottagande rönte hans idé om att inrätta en grupp för att ta vara på nutidshistorien och\ndärmed lägga en säker grund för att värna om, men också utveckla, traditionerna inom\nvår egen loge. Först efter flera års diskuterande och ett till synes självsvåldigt beslut av\nde dåvarande Styrande inom vår loge kom Jönköpings Bacchanaliska Akademi till stånd.\nDet slutliga beslutet togs på hösten 1994. Idén var Jeje’s. Han drev den, förvisso till-\nsammans med andra övertygade, såsom Akademins blivande Director Charles Petruson.\n\n\n124"}, {"pdfPage": 126, "printedPage": null, "text": "Jeje blev också Akademins förste Praeses och\ndess självskrivne ledare och inspiratör. Under\nhans varsamma händer togs fram förslag till\nAkademins Reglor, grundlades mötes-\ntraditioner och utvecklades verksamheten.\n   Jönköpings Bacchanaliska Akademins\nfrämsta uppgift är att bevara sällskapets tradi-\ntioner, att värna om Sällskapets arkivalier och\ngöra dem tillgängliga för Bröderna, dokumen-\ntera nutiden för kommande Bröders förståelse\nför sin egen dåtid samt att värna om och sti-\nmulera till utvecklingen av Brödernas välta-\nlighet och skrivande.\n\nFörsta sammanträdet\nStyrande Mästaren emeritus Jan-Erik Berggren\nfick under hösten 1994 i uppdrag av Det Sty-\nrande Guvernementet att starta och leda en\n                                               Akademins grundare och förste Preses Jan-\ngrupp med arbetsnamnet Akademia Bricola. Erik Berggren.\nDen 21 november 1994 samlades så denna\ngrupp för första gången i Bellmanssalen på\nKansliet.\n                                           Akademin presenterades vid Barbaradagen\n                                        1994 av dess Praeses Jan-Erik Berggren med\n                                        följande ord av Ordens Talare och Skald, Gö-\n                                        ran Grefbäck:\n                                          Redan Platon uppå grekisk mark\n                                          Samlade adepter i en skuggig park\n\n                                          Cicero i Tusculum\n                                          Gav åt talekonsten rum\n\n                                          Nu i vårt Bricolleri\n                                          Har vi fått en Akademi\n\n                                          Vi vill samla vittre, lärde\n                                          För att under färden genom världen\n\n                                          Vandra i Apollons spår\n                                          Med lagerkrans i grånat hår\nOrdens Talare och Skald Göran Grefbäck.\n\n\n                                                                                    125"}, {"pdfPage": 127, "printedPage": null, "text": "När vi bägarn fyller i\n   Fylls vårt hjärta utav eufori\n                                            の位匁acclia匹ん•(a 月,{a今加\n   Efter vår förmåga ville vi för-\n   söka\n   Att som guden vitterhet och\n   ljus föröka\n\n   Därför ber vi Er med oss cele-\n   brera\n   Akademin som vi haft glädjen\n   att fundera\n\n\nAkademins sammanträden\nRedan från början betonade ini-\ntiativtagaren Jan-Erik Berggren\natt ”arbetet inom Akademin skall\nvara aktivt, producerande, fram-\nåtsyftande, dokumenterande, re-\ngelbundet förekommande, ka-\npitelmedverkande, stimulerande\ntill eftertanke och framtidsvisio-\nner. Akademiledamot skall sprida\nskimrande stänk av vitterhet över Inbjudan till det allra första sammanträdet med\nalla Bricolli-Bröder.”                  Akademin år 1994.\n    Akademin har samlats regel-\nbundet fyra till sex gånger varje år. I de flesta fall hemma hos någon av ledamöterna\neller på kansliet. Som regel har bjudits in till en måltid varefter sammanträdet startat på\nriktigt. Vid sidan av stående punkter som föregående mötes protokoll och förväntade\nAkademiinsatser under kommande kapitel har den mesta tiden ägnats åt frågor kring\nvåra gamla dokument av skilda slag. Deras ordnande, förvaring och registrering, till-\ngänglighet och liknande har ständigt diskuterats. Kopiering av de Gyllene böckerna,\ninte minst kostnaderna härför, har varit och är fortfarande en återkommande fråga.\n    Akademin har inbjudit gäster till sina sammanträden. Gästen har ombetts att redo-\ngöra för sitt arbete/intresseområde och har därmed berikat ledamöternas kunnande. Vid\ni det närmaste varje sammanträde har en eller flera av ledamöterna framfört egna eller\nandras texter i bunden eller obunden form. På så sätt har vi fått inblick i Göran Grefbäcks\neleganta rimsmide och stora kunnande om bland andra den heliga Birgitta och\nVadstena kloster, Alf Henrikssons underfundighet och ordhantering, Bellmansskildrarnas\nsakkunskap och fantasibilder och inte minst Harald Wigstrands spexarådra liksom hans\nstora insikter i svensk poesi, litteratur och klassisk musik. Ett efterlängtat ögonblick vid\n\n126"}, {"pdfPage": 128, "printedPage": null, "text": "Akademins\n                                                                 Högtidssammanträde\n                                                                 1998. F. v. Harald\n                                                                 Wigstrand, Charles\n                                                                 Petruson, Göran\n                                                                 Grefbäck och Eric\n                                                                 Haglund.\n\nvarje sammanträde har varit den ständige sekretären Ragnar Jonsells uppläsning av\nföregående mötes protokoll. Träffsäkert formulerat, associationsrikt och alltid oför-\nglömligt framfört!\n\nAkademins ledamöter och inre organisation\nVid akademins andra sammanträde i januari 1995 fastställdes pallplaceringar och för-\ndelades arbetsuppgifter. Därefter har några nya ledamöter tillkommit och pallar och\nfunktioner ändrats. Se nedanstående tabell.\n\n Pall nr 1     Ordens Talare och Skald            Göran Grefbäck, 1994 - 2001\n                                                  Gunnar Åkerskog 2002 -\n Pall nr 2                                        Eric Haglund 1994 - 2001\n                                                  Dan Ekström 2002 - 2004\n Pall nr 3                                        Leif Thor 1994 -\n Pall nr 4     Praeses                            Jan-Erik Berggren 1994 - 1998\n                                                  Eric Haglund 1998 -\n Pall nr 5     Art Director                       Charles Petruson 1994 -\n Pall nr 6     Ständig sekretär                   Ragnar Jonsell 1994 -\n Pall nr 7     Revisor                            Gunnar Åkerskog 1994 - 2001\n                                                  Göran Grefbäck 2002 -\n Pall nr 8     Bokhållare                         Gert Karlsson 1994 -\n Pall nr 9     Bibliotekarie                      Harald Wigstrand 1995 -\n Pall nr 10                                       Dan Ekström 1997 - 2001\n                                                  Bo E Karlsson 2004 -\n Pall nr 11                                       Bernt Lindqvist 1999 -\n\n\n                                                                                  127"}, {"pdfPage": 129, "printedPage": null, "text": "Den Bacchanaliska Akademins kedja, medalj\n                                    och ordförandeklubba.\n                                     Akademins särskilda ledamotstecken utgörs av en tri-\n                                     angel med inlagd oval i emalj samt pallens ordnings-\n                                     nummer. Triangeln hänger i sin spets i en kedja av 15\n                                     konstfärdigt utformade länkar. Den skall bäras runt\n                                     halsen. Halskedjan designades och framställdes av Art-\n                                     Director Charles Petruson.\n                                        Akademins medalj utformades också efter en idé\n                                     av Charles Petruson. Den godkändes och reglerna för\n                                     dess utdelande fastställdes av Det Styrande\n                                     Guvernementet i april 1998. Medaljen har formen av\n                                     en liksidig triangel, omsluten av strålar. Inne i triangels\nAkademins halskedja.                 syns den brinnande lampan. Den bäres i svart band.\n                                        Petruson lät också tillverka en särskild ordförande-\nklubba, som Praeses har att hantera vid Akademins sammanträden. Den är knappt 50\ncm lång, i trä, har ett massivt, tungt huvud samt ett svarvat skaft. Den är försedd med\nflera silverplattor, vilka tillverkats av den uppskattade Brodern, silversmeden och förre\nbyggmästaren Gunnar Knutsson.\n\n\nHögtidssammankomsten\nAkademin genomför årligen sedan 1996 under mars/april en Högtidssammankomst,\nvilken är öppen för alla Bröder. Därvid avhålles Akademins årsmöte samt utdelas\nAkademins medalj i guld till en eller flera väl förtjänte Bröder. En viktig punkt på\nprogrammet är det särskilda Högtidstalet, vilket framföres av en av Akademins leda-\nmöter. De flesta gångerna har sammankomsten genomförts på restaurang Mäster\nGudmunds Källare och avslutats med en enklare måltid bestående av ärtsoppa och varm\n                                                        punsch. Vid ett tillfälle, år\n                                                        2002, avhölls sammankoms-\n                                                        ten på Länsteatern Lillstickan,\n                                                        varvid spexet ”PB-fäderna” av\n                                                        Ordens Bibliotekarie Harald\n                                                        Wigstrand framfördes.\n                                                           De två första åren inbjöds\n                                                        särskilda gäster för underhåll-\n                                                        ningen till kaffet. Rolf von\n                                                        Otter med speleman Fred\n                                                        Andersson gästade oss 1996\n                                                        och trubaduren Gunnar Nils-\n                                                        son 1997. Övriga år har de\nAkademins ordförandeklubba                               egna talangerna inom Den\n.\n\n128"}, {"pdfPage": 130, "printedPage": null, "text": "Praeses Jan-Erik Berggren talar vid Akademins Högtidssammanträde år 1994.\n\n\nBacchanaliska Musiken, Kören och Theatern förgyllt Högtidssammankomsterna med\nsång, musik och bricollistiskt trubadurande. Med den äran!\n\nSkriftserien\nAkademin utger högtidstal, andra bemärkta tal och annat väl skrivet och framfört inom\nJönköpings Par Bricole i en särskild skriftserie. Hittills har utgivits två nummer inne-\nhållande högtidstalen från år 1997, ”En gustavian i Vätterbygd” av Gunnar Åkerskog\nsamt från år 1999, ”Par Bricole 1779 - 1822, dess äldsta historia” av Dan Ekström.\n\nGyllene böckerna\nInom Jönköpings Par Bricole har ända från Sällskapets grundande samlats tal och skrifter,\nbrev och berättelser m.m. inbundna i böcker.\n   I samband med St.M emeritus Jan-Erik Berggrens 70-årsdag insamlades medel och\ninstiftades en fond för att möjliggöra framställning av ännu en Gyllene bok. Akademin\nfick uppdraget och en mindre grupp bildades för arbetet. Den bestod av Gunnar Åker-\nskog, Ragnar Jonsell och Harald Wigstrand, tillika sammankallande. Arbetet blev om-\n\n\n                                                                                     129"}, {"pdfPage": 131, "printedPage": null, "text": "fattande men också mycket intressant och framgångsrikt. Den femte Gyllene boken,\nomfattande åren 1945 - 1997, kunde överlämnas till De Styrande vid Barbaradagen år\n1999. Därefter har arbetet med att samla material till en sjätte Gyllene bok påbörjats.\n\nTal till moster Barbara\nJönköpings Bacchanaliska Akademi har sedan dess instiftande föreslagit Barbaratalare\noch försäkrat sig om att talet har haft lämpligt omfång, inriktning och kvalitet. På\ninitiativ av Director Charles Petruson inbjöds år 1994 alla Bröder att anonymt in-\nsända sina hyllningar till Moster för Akademins granskning. Inbjudan hörsammades av\nBröderna och de första åren inkom omkring fem varje år. Efter hand tunnade dock\nströmmen ut och under senare år har Akademin valt att självsvåldigt utse Barbara-\ntalaren, att ensam våndas under kulna höstdagar för att på Barbaradagen exekvera sitt\nalster.\n\nKapitel och Måltidskalas\nAkademin medverkar vid nästan alla gradgivningar med redovisning av ”Gradens his-\ntoria”. Vid minneshögtiden över under året avlidne Bröder har Ordens Talare och Skald\nunder senare år medverkat i kyrkan med recitation på ett stämningsfullt och av Brö-\nderna mycket uppskattat sätt. Den samme har vid andra tillfällen framfört välskrivna\noch stilfulla tal till exempelvis tillresta gästers ära eller till vid Vårbalen närvarande\nSystrars förnöjelse.\n   Vid åtskilliga Måltidskalas medverkar ledamöter ur Akademin med kvällens ”Aka-\ndemiska Krydda”. Ett kortare tal i bunden eller obunden form med anknytning till\nGraden, händelser i den kalmuckiska världen, i anledning av dagen eller något helt\nannat för en stunds förnöjelse eller berikande av den gemensamma kunskapen inom\nlogen.\n\nTidningen Avisa\nAkademin har fått i uppdrag att tillse att Avisa utges med någorlunda regelbundenhet\noch med minst ett nummer per verksamhetsår. Inbjudan till tilltänkta skribenter, insam-\nling av material, bearbetning av material, redigering m.m. ombesörjes av en särskild\nredaktör, fr o m 2002 Brodern Bo Fjaestad.\n\nFortsatt arbete\nJönköpings Bacchanaliska Akademi har funnits i 10 år. Akademin har nu funnit for-\nmerna för arbetet, definierat arbetsuppgifterna och funnit en stimulerande roll i det\nbricollistiska arbetet i Vingården. Mycket arbete har lagts ned på att ordna sällskapets\nhandlingar och finna en säker förvaring av dessa för framtiden. Åtskillig tid och kraft\nhar av enskilda Bröder, liksom av ledamöterna, ägnats åt att ta fram grundmaterial till\ndenna Jubileumsbok. En viktig förutsättning för boken har varit genomgången och\nsystematiseringen av våra äldre handlingar.\n\n\n130"}, {"pdfPage": 132, "printedPage": null, "text": "Med denna nu ordnade grund är det lätt att se mot framtiden. Jönköpings\nBacchanaliska Akademi skall fortsätta sitt arbete och dokumentera nutiden för fram-\ntida Bricollisters sökande i deras forntid. Akademin skall också än mer arbeta för att\nstimulera intresserade och talangfulla Bröder till än mer eget skrivande och talande vid\nvåra kapitel.\n\n\nDen Bacchanaliska Måltidsakademin - Luculli\nGille\nHösten 1983 började det. Bröderna Knut Erik Jahnke och Sidney Dahl samt krögaren\nLasse Lendrop i Malmö kom med idén. Det borde bildas en ”måltidsgrupp” inom Par\nBricole.\n   Styrande Kanslern Gerhard Mattus och Deputerade Styrande Mästaren Torsten\nWelander tände helt på idén. Första mötet skedde den 23 november och 19 intresserade\nBröder infann sig. På Barbaradagen samma år tillkännagavs att Luculli Gille bildats\noch Brodern Ingemar Boman utpekades av Styrande Kanslern som bas för det hela.\nI december hölls konstituerande sammanträde och tre grupper med sex man i varje\nbildades - en grupp för träff på måndagar, en på tisdagar och en torsdagar. Mötesplatsen\nblev det gamla lägenhetsköket i våra kanslilokaler på Östra Storgatan 6.\n\n\n\n\nFem Bröder tittar in i spisen 1984: Stående f. v. Sven-Åke Suhr, Lennart Stridh, Bertil Utberg\nHukande:f.v. Gerhard Mattus, Lars-Olof Björk.\n\n\n                                                                                                 131"}, {"pdfPage": 133, "printedPage": null, "text": "Det hela blev en veritabel succé och redan till hösten 1984 hade Luculli Gille sju\ngrupper om inalles 47 Bröder, vilka träffades, trivdes och njöt av i de flesta fall luculliska\nanrättningar. Brodern Joseph Strub, mångårig kökschef på Stora Hotellet, utsågs till\nMATador och spred visdomsord, råd och tips som anammades av Bröderna, av vilka\nmånga var noviser vid spisen. 1986 hade Joseph Strub besökt matlagningsaftnar i\nsamtliga sju grupper om tillsammans ca 55 Luculli-bröder.\n\nSällskapet Par Bricole och Luculli Gille\nOrdenssällskapet Par Bricole hade 1979 firat 200 år och Det Lysande Sällskapet\nJönköpings Par Bricole hade firat sitt 100-årsjubileum. Under drygt 200 år hade talang-\ngrupperna inom Par Bricole bestått av grupper som kännetecknats av vältalighet, sång,\nmusik och teater. Då kommer Jönköping med en ny, djärv idé inom ett sällskap, som\nbygger så mycket på tradition. Moderlogen var av förståeliga skäl ganska avvisande\nmot förslaget från den då yngsta av döttrarna. Säkerligen har många förslag till föränd-\nringar funnits genom de 200 åren. Det är ofta som ungdomar velat utveckla och för-\nändra saker och ting speciellt med idéer i tiden.\n   Genombrottet för idéen med Luculli Gille kom då Den Bacchanaliska Akademin\nden 13 april 1984 för första gången förlade sitt Högtidssammanträde utanför Stock-\nholm. Jönköping fick äran att, med vår Styrande Mästare Carl-Wilhelm Lothigius som\nvärd, arrangera denna historiska sammankomst. Luculli Gille, endast några månader\ngammalt, fick förtroendet att ansvara för Akademins festmåltid. Sex Kockar i Kock-\nkläder, sex servitörer och en Suhr hovmästare (Sven-Åke Suhr) i gustavianska kläder\nvar en passande bricollistisk inramning, liksom festsalen med kristallkronor och\nornamenterad kakelugn i våningen under våra kanslilokaler. Stämningen stod verk-\nligen högt i tak.\n   I pausen före kaffet med punsch kom Akademins exalterade Praeses Fredrik W\nLettström ut i köket och uttryckte sitt gillande. Lucullibröderna visade då - som av en\nhändelse - ett färglagt förslag till talanggruppsmärke och medalj för Luculli Gille. Fredrik\ntog det inramade förslaget, rusar in i festsalen och visade upp det utropandes: ”Titta här\nHans (Stormästaren Hans Kjellgren) vad pojkarna gjort! Det här måste vi satsa på!”\nSå var halva slaget vunnet och islossningen började. Officiellt beslut om talanggruppen\nLuculli Gille togs dock inte förrän i Stora Konseljen den 31 januari 1986.\n\nLuculli Gille\nInom Jönköpings Par Bricole kallades till en början Luculli Gille för den ”Femte\nAkademien”. Styrelsen bestod av Praeses Ingemar Boman, Inspector Knut-Erik Jahnke,\nGillespräntare Gerhard Mattus och Gillesfogde Ola Adamsson, tillsammans utgörande\nAU, samt InSPISient Claus Marcus, MATador Joseph Strub och Överste Munskänk\nLars Boll. Rätt snart visade det sig praktiskt att bilda en beslutande Luculli Senatus,\nsom utöver styrelsen också bestod av en Monsieur le chef för varje grupp samt två\nrevisorer.\n\n\n\n132"}, {"pdfPage": 134, "printedPage": null, "text": "Låtom oss peppra! F. v.\n   Lennart Fornander,\n   Lennart Tranesjö och\n   Rune Algren år 2001.\n\n\n\n   Ett av målen för Luculli Gille var att officiellt bli upptaget i kretsen av talanggrupper.\nMan ansökte därför hos Det Styrande Guvernementet om ett talanggruppsbidrag om en\nsvensk krona för verksamheten inom Gillet, vilket också beviljades. Vid sammanträde\nden 17 april 1985 beslutade De Styrande att uppta Luculli Gille såsom en talanggrupp\ninom Sällskapet. Samma år beslutades om att ta fram ett talanggruppmärke och tillika\nmedalj.\n   Att tillföra en ny aktivitet i ett av tradition präglat 200-årigt sällskap är inte så lätt.\nVåra Styrande önskade med rätta en anpassning till den bricollistiska verksamheten,\nsedvänjor och ritualer. Det var många som frågade sig hur Luculli Gille kunde kalla sig\nen talanggrupp inom Sällskapet om Gillet inte tillförde dess måltidskalas m fl tillfällen\nnågot talangfullt till alla Bröders glädje? Luculli Gille har under åren visat att Gillets\nmedlemmar visst har denna förmåga.\n   Broder Ingemar Boman var Luculli Gilles förste Praeses. Han ledde verksamheten\nunder tio år och efterträddes de kommande åren av Bröderna Ulf Månsson, Kent Käll,\nBerno Wessman och den nuvarande Praeses Pär Malmvall. Bröderna Hans Lebert, Dag\nThulin och Björn Timén har varit Gillets Präntare. Över alltihopa svävade de första\nåren Inspektorn Knut-Erik Jahnkes anda. Han gjorde en ovärderlig insats för och inom\nGillet och tilldelades postumt Gillets guldmedalj år 1991. Redan 1987 bestod Gillet av\n104 medlemmar fördelade på elva grupper. Platsbrist uppstod och matlagningsaftnarna\nmaximerades till fem gånger per grupp och säsong.\n   Idén med Luculli Gille inom Par Bricole har numera utvecklats till en väsentlig och\nväl mottagen verksamhet inom Sällskapet. Sedan starten 1983 i Jönköping har Gille-\nidén förts vidare till Göteborg, Malmö och Sundsvall. Gillet har förökat sig inom\nfamiljen Par Bricole. I Jönköping har den 12:e Gille-gruppen utvecklats till Sällskapets\nTraktörgrupp efter en modell från Moderlogen.\n\n\n\n\n                                                                                          133"}, {"pdfPage": 135, "printedPage": null, "text": "Galina Kovzel, S:t Petersburg är gäst i dåvarande Bellmanssalen inför Operamaskeradbalen 1992.\nHerrarna runt bordet f.v. Gerhard Mattus, Vikar Säfvestad, Lennart Stridh, Josef Helperin, Hans\nLebert och Torsten Welander.\n\n\nLuculli kök\nAllt eftersom verksamheten ökade stod det klart att en ombyggnad av det gamla köket\ni kanslilokalen var nödvändig. Det skissades och planerades, eftersom köket hade en\nyta av endast 13 m2. Med en annorlunda placering av dörrar och fönster bildades en\nmycket oregelbunden form. På våren 1987 påbörjades rivnings- och ombyggnads-\narbetena. De genomfördes av Bröderna själva.\n   Tack och lov var det många Bröder som hjälpte till med både arbete och material.\nIngen nämnd och ingen glömd! Dock med undantag för Brodern Jan Swefors. Jan var\ninredningsspecialist och en bricollistisk eldsjäl, som med kompetens och stort hjärta\nmedverkade till förverkligandet av ett fantastiskt fint och väl fungerande kök på det\nminimala utrymmet. El, VVS och målning med mera utfördes helt utan kostnad. Dock\nkom det en faktura på ett ”normalstort” belopp för köksinredningen. Efter rabattavdrag\nmed 40 %, viss prisreduktion, öresutjämning slutade den dock på 0 kr + moms, vilket\nalltså blev slutsumman 0 kr - Tack och lov!\n   Sällskapet skrev år 1999 ett nytt hyreskontakt på hela 4:e våningen på Östra Storga-\ntan 6. En större sal - kallad Barbarasalongen - och två mindre rum inlemmades i kansli-\nlokalen. Då gjordes en renovering av hela våningen och ny ombyggnad av kök och\ntoaletter. Köket blev något större och utrustades med ny spiskåpa med bättre fläktar,\nviss komplettering av skåpen skedde, ett nytt undertak sattes upp och allt målades om.\nDen nya Bellmanssalen försågs med helt nya möbler och konferens- och matsalsbord\nför 18 personer.\n\n134"}, {"pdfPage": 136, "printedPage": null, "text": "Under de gångna 20 åren har Gillets måltider intagits i den festligt dukade Bellman-\nsalen. Måltiderna har sedan 1985 inletts med unison sång av Frans Michael Franzéns\nunderbara bordsvisa ”När skämtet tar ordet vid vänskapens bord” och har alltid följts\nav en Brödraskål.\n\nAktiviteter genom åren\nSedan den inledande festmåltiden för Den Bacchanaliska Akademin år 1984 har Gillet\nmedverkat inom Sällskapet vid många tillfällen. Här kan nämnas den ofta återkom-\nmande ”Kvällens krydda”, ett kort kåseri om kvällens måltid, använda kryddor och\nderas ursprung, potatisens många möjligheter, rysk matlagning, kvällens viner och\nmycket annat. ”Kvällens krydda” avslutades alltid med att Bröderna unisont sjöng Frans\nMichael Franzéns måltidssång ”När skämtet tar ordet vid vänskapens bord” till under-\nfundigt pianoackompanjemang av Koralintendenten Clas-Olof Lindqvist.\n   Luculli Gille anordnade på hösten 1986 en mycket uppskattad eftersits på Hantverks-\nföreningen i samband med besök av Den Bacchanaliska Teatern från Moderlogen,\nvilken gav spexet Napoleon på Jönköpings Teater. Minnas skall bedriften att, med hjälp\nav en spis med bara två plattor, kunna servera hundratalet gäster nystekta ägg.\n   Hösten 1986 inbjöds till adventskaffe i våra kanslilokaler på Östra Storgatan 6.\nGatuskyltar med marschaller inbjöd Bröderna med familjer till glögg och hembakat\nbröd, liksom naturligtvis saft, bullar och glass till barnen. Detta blev mycket populärt\noch redan 1987 var besökssiffran uppe i 110 personer. Tyvärr minskade intresset och\nadventskaffet är numera nedlagt.\n   Broder Ingemar Boman, tillika Gillets Praeses, medverkade påtagligt i arbetet med\natt göra det nedlagda regementet A6 till ett stort\nköpcentrum, kallat Nya A6. På hans initiativ\nförlades år 1990 den Andra Graden till det\ngamla marketenteriet på A 6. Luculli Gille\nanordnade måltidskalaset och serverade en\ndelikatesstallrik med Halmstadslax. Många\nBröder hade hörsammat kallelsen och njöt i\nfulla drag av mat, dryck underhållning m m.\nDet fanns två barer och en militärutställning.\nEn utställd riddare i fullt harnesk stod mäktigt\nvid utställningen. Bröderna imponerades över\nden gamla rustningen, som man trodde var\ntom. Under gradgivningen börjar Riddaren till\nallas förvåning plötsligt röra sig och lämnade\nskramlade salen. I rustningen hade Broder Ste-\nfan Svartz funnits i en dryg timma. Många\nbröder drack därefter mycket måtteligt eller\ningenting alls.                                    Kvällens krydda: Ingemar Boman på\n   Luculli Gille har medverkat också vid den Barbaradagen 1988.\n\n                                                                                    135"}, {"pdfPage": 137, "printedPage": null, "text": "Sjunde Gradens måltidskalas. År 1994 gavs\n                                             Graden på Styrande Mästaren emeritus Jan-\n                                             Erik Berggrens gård Sandvik, belägen intill\n                                             sjön Ylens sydvästra strand. Gillet svarade\n                                             för festmåltiden med blommiga viner på den\n                                             björksmyckade logen, till stor belåtenhet\n                                             också för Stormästaren Hans Kellgren.\n                                                 År 2000 gavs graden vid Tempelgården på\n                                             Visingsö. Efter vistelsen i Lunden gjordes ett\n                                             stopp vid Visingsborgs slottsruin, där Gillet\n                                             bjöd Bröderna på salut och nytt bränsle med\n                                             tilltugg.\n                                                 Vid den av Bröder och Systrar mycket upp-\n                                             skattade och omtalade Maskeradbalen år\n                                             1992 medverkade Luculli Gille aktivt i ar-\n                                             rangemangen i Spegelsalen. Studiebesök på\nIngemar Boman och Luculli gille utfordrar    Nordiska Museet gav idén till ett kungabord\nBröderna på Visingsborg. 2000.               på ett stort podium mitt i salen, omgivet av\n                                             kolonner med blomsteruppsättningar. Övriga\nbord utgick som solstrålar från det kungliga sällskapets i mitten av Spegelsalen. Luculli\nGille svarade för olika tilltugg, vilka serverades när Systrarna vid entrén gick till vän-\nster bakom skärmar och fick smaka ”rött vin med pimpinella” medan Bröderna visades\ntill höger och inmundigade ljuvligt, synligt fluidum.\n\n\n\n\nÄdel tävlan på Ingemarsgården sommaren 1995.\n\n\n136"}, {"pdfPage": 138, "printedPage": null, "text": "D.St.M em. Torsten\n                                                                     Welander vänder på\n                                                                     pannkakan.\n\n\n\nLuculli Gille på vift\nDe olika grupperna inom Luculli Gille har skapat egna traditioner, som våra kärälskeliga\nSystrar då och då deltagit i. Krogbesök i Danmark, ett antal herrgårdsvistelser med\nvinprovning och superba måltider, besök på Måltidens hus i Grythyttan med föreläs-\nning av Carl-Jan Grankvist, måltider i hemmiljö eller på sommarresidens är några ex-\nempel. Årliga träffar med strömmingsfiske i Sankt Annas skärgård, besök på Öland,\nbåtturer med fiske i Vättern eller på västkusten är andra exempel. Tidaholm har ett fint\nlitet provkök som ligger på Vulcanön i Tidan. Anläggningen som invigts av prins Bertil\nhar besökts och var perfekt för både matlagning och föreläsning för två bussar fyllda\nmed vetgiriga Luculli-Bröder.\n\nIngemarsgården vid sjön Bunn\nLuculli Gille har sedan 1984 samlats till en avslutande familjemåltid i ”det gröna”.\nBröderna har tillsammans med sina kärälskeliga Systrar, barn och vänner samlats med\npicnic-korg, goda viner, dukar och filtar till en sagolik måltid uppdukad i en vid de\nflesta tillfällen solglittrande John Bauernatur hemma hos värdparet Yvonne och\nIngemar Boman. Vid dessa tillfällen tävlades det också grupperna emellan om en\ninteckning i MATador Joseph Strubs vandringspris - en vacker skärbräda i björk. Efter\nkvalifikation, med hjälp av utslagsfrågor inom ämnesområdet, tävlade två grupper i en\ndirekt final i matlagningskonst inför en särskild jury och en månghövdad och ivrigt\npåhejande publik.\n   Efter drygt tio år utvidgades denna tradition till en tvekamp mellan Luculli Gille-\nBröder från Jönköping och gästande Gillebröder från Göta Par Bricole, som 1993\nbildat sitt Luculli Gille. Gillena tävlade om en inteckning i ett västkustskt vandrings-\npris. Första gången hemfördes det av Jönköping. Tyvärr var doften av det i Bellmans-\nsalen hängande priset så stark, att det senare tvingades in i en vakuumförpackning. Vid\n\n\n                                                                                    137"}, {"pdfPage": 139, "printedPage": null, "text": "firandet av Göta Par Bricoles Luculli Gilles 10-årsjubileum 2003 vann Göteborgarna\nen inteckning i vandringspriset, vilket i skrivande stund alltså hänger på Valand i\nGöteborg.\n   Dessa uppskattade säsongsavslutningar hos Yvonne och Ingemar Boman i Bunn\npågick varje år till år 2001, då de flyttades till Slottsvillan i Huskvarna.\n\nGåsablot\nRedan till Mårten Gås hösten 1984 anordnade Gillet ett riktigt gåsablot. Det blev sedan\nen årlig tradition. Allt utfört enligt gammal sedvänja med gås, svartsoppa, krås, hjärta,\nrödkål, brunkål och leverkorv gjort av gåsstrupe följt av skånsk äppelkaka och äkta\nvaniljsås. Smaksättningen av svartsoppan var det verkliga eldprovet. Det var svart vin-\nbärsgelé, kanel, ingefära, lagerblad, timjan, mejram, sirap, peppar och salt, gåsflott,\näppel- och plommonspad, portvin, madeira och konjak. Drycken till svartsoppan var\nRamlösa. Till gåsen serverades ett rödvin och till äppelkakan ett Chateau Lasalle.\n   Att ordna Gåsablot till drygt 100 personer är otroligt krävande om man skall hålla\nmaten varm och av högsta kvalitet. Traditionen Gåsablot avbröts därför in på nittiotalet\ni samband med att gåsamiddagen i anslutning till den sjätte Graden återinfördes i\nSällskapet.\n\nEgna vinstockar\nSedan många år har Luculli Gille egna vinstockar på Château Fougas i Frankrike. De\nger en 15 - 16 flaskor per år ”Vendange manuelle pour la Récolte de Luculli Gille”.\nVinet tappas på numrerade flaskor med specialetikett. De första flaskorna provsmaka-\ndes vid 10-årsjubileet och en stor del av de övriga när Gillet firade sina 21 år.\nProvsmakningen utföll till blandad belåtenhet, men det var ju i alla fall vin från egna\nstockar.\n\nKokbok 1993\nEn egen kokbok gavs ut till 10-årsjubileet 1993. Kokboksfonden, som tillkommit bl a\ntack vare jubelkommendören Bertil Larsson, bekostade denna 44-sidiga kokbok. Den\nbestod av de bästa menyerna under de första tio åren. Den fick ett entusiastiskt motta-\ngande och slutsåldes med en gång trots en stor upplaga.\n\nJubileer\nLuculli Gille har hitintills firat uppnådda 10, 15 och 21 år. På källarkrogen Kejsar-\nkronan firade 133 bröder och systrar våra första tio år med en festmeny anrättad i Elmias\nrestaurangkök. Måltiden bestod av gravad sik och röding med sås och dillpotatis, hjort-\nstek med potatisgratäng, äppelpaj med hemgjord glass och därtill goda drycker. Måltids-\nakademin Luculli Gille uppvaktades av De Styrande och alla de andra talanggrupperna.\nDet hela leddes med bravur av nytillträdde Praeses Ulf Månsson.\n   Fem år senare firades under Praeses Kent Källs ledning på Trottoaren hos vår huvud-\n\n\n138"}, {"pdfPage": 140, "printedPage": null, "text": "traktör Stora Hotellet. Naturligtvis fanns mycket gott både att äta och dricka. Vid års-\nmötet valdes Berno Wessman till vår kommande Praeses.\n   Gillets 20-årsjubileum firades först i mars 2004 och blev alltså ett 21-års-kalas. Praeses\nPär Malmvall vägledde drygt sjuttio Bröder hos Ove Gräsman på Restaurang Klubbhus-\ngatan 13. Föredrag hölls om gotländsk tryffel. Vårt eget vin provsmakades. Tävlingar\ngenomfördes. De Styrande harangerade Gillet med en vacker ”vällingklocka”, vilken\nnumera hänger utanför Bellmanssalen och kallar till Gillets måltider. Gille-Bröderna\nfrån Göta PB liksom Traktörerna uppvaktade också. Festmåltiden bestod av gubbaröra\noch kall snaps, rådjurssadel och dessert - allt naturligtvis med charmanta drycker. Ja, se\ndet var ett riktigt jubileumsgille - men vad annat var att vänta! Luculli Gille 21 år -\noslagbart!\n\nInSPISientgruppen\nFör ordning, inköp av pannor, porslin och förnödenheter till kök och Bellmanssal sva-\nrar en inSPISient. Genom åren har allehanda reparationer, kompletteringar och exem-\npelvis ett nytt parkettgolv i gamla Bellmanssalen utförts av dessa bröder. Claus Mar-\ncus, Anders Bernhardsson och Tore Palmqvist har innehaft denna viktiga och maktpå-\nliggande befattning. Allt fungerar synnerligen perfekt. Det kan tyvärr ändå finnas lite\nbrister när Bröderna gått hem fram på småtimmarna.\n\nGillets gästbok\nAlla deltagare och gäster noteras regelbundet i Gästboken. Vid 21-årsjubileet användes\nden fjortonde (14) gästboken. Gästböckerna berättar om mer än 1700 matlagnings-\nträffar. De är dokument över vad som hänt inom Luculli Gille. Gästboken har dock inte\nalltid varit med. Tyvärr! Det finns dessutom sex A4-pärmar med vid måltiderna an-\nvända recept.\n\n\n\n\n                                                                                         139"}, {"pdfPage": 141, "printedPage": null, "text": "Sällskapets andra aktiviteter\n\nTraktörerna\nModerlogen har en traktörgrupp för aktiviteter som går av stapeln i Bellmanhuset på\nUrvädersgränd. Därför föll det sig naturligt att våra utökade lokaler med Bellmanssal\noch Barbarasalong även skulle få del av denna service. Traktörerna är en talanggrupp\nbestående av alerta och positiva Bröder. Under Bröderna Lars Bolls och Fredrik Ackebys\nledning har Traktörerna på kort tid fått en aktiv roll när det gäller att ställa upp vid\nrepresentation och sammankomster. En ny fräsch blomma inom Par Bricole-familjen.\n\nArkiv X\nArkiv X samlas på Par Bricoles kansli på förmiddagen varannan tisdag. Gruppen består\nav sex ordinarie ledamöter. Förutom att dricka förmiddagskaffe är huvuduppgiften\natt gå igenom, identifiera och klistra in foton från Par Bricoles olika aktiviteter.\n\nKulturutskottet/Bellmansfirande\nÅr 2002 bildades ett kulturutskott inom Jönköpings Par Bricole. Utskottets uppgift var\n                                                att ta initiativ till ”kulturella Arrange-\n                                                ment till Brödernas och Systrarnas\n                                                fröjd och gamman”. Tanken var också\n                                                att Par Bricole skulle synas mera ute\n                                                i samhället. Kulturutskottet har från\n                                                2002 årligen ordnat en Bellmansfest\n                                                utomhus vid Rosenlunds herrgård,\n                                                vars nuvarande huvudbyggnad upp-\n                                                fördes medan C. M. Bellman ännu\n                                                levde. Till festen välkomnas alla Brö-\n                                                der med Kärälskeliga Systrar, Most-\n                                                rar, Cousiner, övrig släkt, vänner, be-\n                                                kanta och alla andra intresserade.\n                                                Hästar och hundar kan även medföras\n                                                i den mån de ej förtära grannen eller\n                                                dennes matsäck. Vid dessa välbesökta\n                                                fester framträder kören, delar av tea-\n                                                tern och musiken. Ordens antikvarie\n                                                Bo E. Karlsson beskriver och visar\n                                                herrgården och dess betydelse i\n                                                staden och tiden. Par Bricole har från\nBror Nätt med fotografiska minnen. 2003.        Jönköpings kommun erhållit ett\n\n140"}, {"pdfPage": 142, "printedPage": null, "text": "diariefört beslut att få uppsätta en byst över Carl M Bellman. Genom Bröderna Charles\nPetrusons och Ingvar Selses skaparkraft tillväxer denna byst varje år i samband med att\nden avtäckes. Trots att C. M Bellman i livstiden veterligen ej besökt Jönköping har hans\nande varje år vid avtäckningen åstadkommit orkanby, hagelsvärm eller åskblixt. Dessa\nhelt oplanerade utbrott har uppskattats av festdeltagarna, som skulle bli besvikna om\nframtida överraskningar uteblev.\n\nPunschbröderna\nPunschbröderna bildades den 12 maj 2003. Gruppen är ett nätverk för helt eller delvis\ndaglediga bricollister, vilka finna nöje i att träffas och utbyta tankar och erfarenheter,\nvunna i såväl det kalmuckiska som i det bricollistiska livet. Bröderna träffas en torsdag\ni varje månad i våra kanslilokaler. Vid träffarna möts bland annat äldre Bröder, som av\nnågon anledning har svårigheter att delta i de vanliga kapitlen. ”Än större gemenskap\nmellan sanna bricollister” är gruppens främsta mål. Punschbröderna leds av initiativ-\ntagaren Leif Thor, som benämns Förste Punschus. Vid samlingarna deklameras\nbl. a ”Dagens dikt” och föredras en kortare presentation över ett för dagen intressant\nämne. Samtidigt serveras en ärtsoppslunch, med eller utan punsch och öl, allt till själv-\nkostnadspris. Naturligtvis sjungs också en speciell hyllning till den värmande punschen.\nVid ett eller två tillfällen per år företas en gemensam resa till intressanta trakter med\nberikande kulturellt/historiskt innehåll. 2004 års resa gick till Karlshamn och dess\nPunschmuseum.\n\nKulturmorgon\nMånga känner sig kallade - men få äro utvalda! Ordet ”Kulturmorgon” är med rätta\npositivt värdeladdat. När dåvarande Deputerade Styrande Mästaren Leif Thor för snart\nett halvt decennium sedan uppmärksammade det från tid till annan föreliggande be-\nhovet av kuvertistoppare - nödvändiga för att brevledes kunna kommunicera med\nBröderna - samlade han kring sig ett knappt dussin villige Bröder. Avsikten var att\ndessa regelbundet skulle träffas för en stunds kulturell samvaro samt vid behov för-\nstärka kanslifunktionen. Denna består av kanslirådet Tore E. Meijer, som svarar för\nall korrespondens samt för att det äldre viscardsystemet städse hålls aktuellt. Som\nregistrator tillser Broder Ingvar Larsson att alla medlemsuppgifter blir elektroniskt re-\ngistrerade. Kansliintendenten Tore Palmqvist reparerar och underhåller inventarier samt\nhåller efter i synnerhet slarviga Lucullibröder. I detta arbete assisteras han av Broder\nUlf Larsson.\n   Det är inte varje torsdag som kansliarbete behöver utföras. Den gemensamma fru-\nkosten kryddas då med ett kort anförande, ett framträdande, en uppläsning eller en god\nhistoria. Såväl egna förmågor som gäster framträder. Då har avnjutits musik på trumpet\noch bastuba, väsandet från en säckpipa och solosång. Andra gånger har gäster berättat\nom Trådrullatåget och om sjöfart. Konsten att tillverka och sälja korv har också redo-\nvisats.\n   Att såväl vårens som höstens arbete där jämte avslutats med en resa, till ett mål som\n\n                                                                                      141"}, {"pdfPage": 143, "printedPage": null, "text": "någon av Bröderna bestämt, har gett ytterligare sälta åt kuvertarbetet. En morgon i\nseptember innefattade den kräftfrukost hos Broder Leon Benér. Resor har också gjorts\ni närliggande landskap i syfte att berika gruppens kulturella kunskaper. Besök har gjorts\ni den genom riddaren Arn mycket aktuella Falbygden, de tidigare försvarsstrategiskt så\nviktiga trakterna kring Varberg, de forna danska nejderna på Österlen i Skåne liksom på\ndet fagra Öland.\n   Det vore att tänja på sanningen att påstå att det är lätt att bli kuvertistoppare. Grup-\npen förnyar sig nämligen själv.\n\nBacchi Penselriddare\nBacchi Penselriddare bildades år 1999 och har som ändamål att vid sina Sammankoms-\nter under gemyt krama sina tuber, doppa sina penslar och vässa sina pennor.\nPenselriddarna skall bland annat bistå Bröder, som uppnått Första Riddargraden med\nidéer om utformning och, om så önskas, vara dem behjälpliga vid framtagandet av en\npersonlig Riddare-sköld.\n   CM Bellman var road av bildkonst och har däri säkert funnit inspiration till många\nav sina poetiska verk. Han har framställt talangfulla och trevliga akvareller, som finns\nbevarade för eftervärlden. En av Bellmans många konstnärsvänner, Per Hillerström har\nförevigat Fredmans Movitz såsom ”Riddaren av penseln”. Originalet, som är en\nbläckteckning, finns på Nationalmuseum.\n   En Bacchi Penselriddare måste inneha minst Den Sjätte Graden för att kunna vinna\ninträde i gruppen. Ledamot av Penselriddarna besitter en numrerad ”pall-ett”. De är\n12 till antalet. Innevarande år är pall-etterna besuttna av Bröderna:\n\nNummer       1.   Peter Gadh,           Professeur\n             2.   Allan Perolainen,     Art Direkteur\n             3.   Nils Norrsell,        Pablo Inkasso\n             4.   Jan Fåhraeus,         Secreteur\n             5.   Lars Nordqvist,       Graveur\n             6.   Mats Pohl,            Revaxeur\n             7.   Benno Holm,           Informateur\n             8.   Lars Löfstedt,        Arkitekteur\n             9-12 Vakanta\n\n   Bacchi Penselriddare har mellan åren 1999 och 2004 skapat och inför Bröderna pre-\nsenterat 16 personliga Riddaresköldar och har därmed aktivt bidragit till bevarandet av\nPar Bricoles sköldtradition.\n   Inom Sällskapet finns ytterligare nystartade grupper, som t.ex Maltakademin under\nledning av Christer Wallinder.\n\n\n\n\n142"}, {"pdfPage": 144, "printedPage": null, "text": "Två publika evenemang på 1990-\ntalet\nMagnus Ladulås 700 år - ett historiskt skådespel\nfrån tiden för Jönköpings grundande\nMagnus Ladulås dog på Visingsö år 1290. Jönköpings Par Bricoles Teater och dess\nledning hade länge diskuterat att hylla stadens grundare inför allmänheten till minne av\ndennes död utan att ge avkall på Sällskapets krav angående den egna slutenheten. Tea-\nterdirektör Dan Ekström fick kontakt med ett medeltida sällskap i Skara, Orbis Gyck-\nlare, och ett samarbete inleddes. Målet var att sätta upp ett medeltida spel om konung\nMagnus Ladulås i Jönköping. Jönköpings kommun beviljade en ekonomisk garanti på\n40 000 kronor, vilket får anses som mycket pengar för genomförandet av två offentliga\nutomhusföreställningar.\n   En lördag i slutet av oktober år 1990 upphörde stormvindarna och regnet. Solen sken\nfrån en klarblå himmel och Par Bricole hyllade Jönköpings grundare Magnus Ladulås i\ntvå föreställningar vid hamnplan framför Stora Hotellet. Satsningen gick hem hos sta-\ndens innevånare. Jönköpingstidningarnas journalister rosade föreställningen liksom Par\nBricoles satsning, både före och efter föreställningarna och gav den ett stort spaltut-\nrymme.\n   Så här skrev Jönköpingsjournalisten Yvonne Teiffel innan medeltidsspelet om Mag-\nnus Ladulås uppfördes. (Saxat ur Jönköpings-Posten den 22 oktober 1990)\n\n”Jubel för Magnus Ladulås 750 år firas med teater\nI år är det 750 år sedan Jönköpings grundare Magnus Ladulås föddes och 700 år sedan\nhan dog. Detta dubbeljubileum har knappast firats eller uppmärksammats alls av\nJönköpingsborna, en lapsus som dock Par Bricole i Jönköping nu ska råda bot på. På\nlördag bjuder de på ett skådespel, som vi aldrig sett maken till i Jönköping. Det blir en\nmastodontföreställning med himlen som tak och hamnkanalens terrasser som scengolv.\nPå andra sidan kanalen - framför Stora Hotellet - finns det gott om plats för publiken.\nTvå föreställningar ges, en på förmiddagen och en på kvällen. Om vädrets makter är\nvälvilliga så kan det bli en fantastisk teaterdag i Magnus Ladulås stad. Från Par Bricole\nhoppas man på en tusenhövdad publik. Nu ska den gamle kungen firas!\n\nKända ansikten\nDen unika föreställningen är en samproduktion mellan teatergruppen Orbis i Skara och\nPB:s teatergrupp där Kommunfullmäktiges ordförande Torsten Welander är ordförande.\nBland skådespelarna från Jönköping känner vi igen flera ansikten som vi har sett förr i\n\n                                                                                     143"}, {"pdfPage": 145, "printedPage": null, "text": "teatersammanhang. Bland de sammanlagt cirka 50 skådespelarna kan nämnas Anders\nRuberg som spelar kung Magnus själv, Dan Ekström som spelar biskop Bengt, Sune\nWinald i gestalt av kung Valdemar, som var bror till Magnus och låg i fejd med denne,\nMarie Winald som spelar en skön jungfru, Thomas Ahlebro som är munk och Hans\nFagerlund som är varubud. Manuskriptet har skrivits av Leif Olsson som också är\nregissör. Han är också berättaren i föreställningen. Från spektakelgruppen Orbis\nkommer bland andra också Ylwa Lauren som spelar Magnus Ladulås gemål, drottning\nHelvig från Holstein. Med henne hade han sönerna kung Birger, Erik och Valdemar\nsamt döttrarna Ingeborg och Rikissa, den senare abbedissa i Klara kloster i Stockholm.\nBland övriga rollinnehavare märks i en salig blandning gycklare, pager, bödlar,\nväpnare, krogslinkor, nunnor, pestoffer, härolder, krogjungfrur och andra, som antogs\nvara med på den tiden det begav sig. Ett mustigt skådespel! Föreställningen har fått ett\nimponerande namn. ”Magnus Ladulås 700 år - ett historiskt skådespel om Jönköping\nvid tiden för dess bildande.”\n   Den är egentligen en berättelse med tablåer mer än ett skådespel. Den berättar om\nJönköping och om dess grundare, kung Magnus som föddes 1240 och som avled på\nVisingsö 1290. Han var kungen som strängt upprätthöll friden i landet och sitt namn\nfick han ju därför att han satte lås på bondens lada. Magnus Ladulås ligger begravd\ni Riddarholmskyrkan, under en gravvård uppförd av Johan III.\n\n\n\n\nSlaget vid Hova i Västergötland år 1275. Kung Magnus (Anders Ruberg) vann och Brodern\nValdemar fick fly till Norge. Foto: Åke Karlsson, JP.\n\n\n144"}, {"pdfPage": 146, "printedPage": null, "text": "Farväl Jönköpingsbor. Kung Magnus lämnar sitt Junaköping för att åka hem till Visingsö och där\navsluta sina dagar. Vid årorna Hans Fagerlund. Foto: Åke Karlsson, JP.\n\n\n\nKultur 90\nFöreställningen ges alltså utomhus och kostar inget att se. Den är ett Kultur 90-\narrangemang och det stöds ekonomiskt även av bland andra Jönköpings Köp-\nmannaförening - vilket kanske kan vara lämpligt, eftersom Magnus Ladulås ju även\ngav rättigheter till handeln i Jönköping. Med den här föreställningen kan man väl säga\natt ordenssällskapet Par Bricole öppnar sina dörrar en liten aning på glänt även för\nallmänheten.\n   PB är ett forum för kultur, säger PB-teaterns ordförande Torsten Welander som til-\nlika är kommunfullmäktiges ordförande. Sällskapet ville göra något för att uppmärk-\nsamma Jönköpings grundare det år då han dubbeljubilerar och nu får också vi andra\nta del av det storslagna firandet.”\n   Recensionen av föreställningen i Jönköpings-Posten upptog två helsidor på mitt-\nuppslaget med många och stora bilder från Magnus Ladulåsspelet.\n\n”Farväl Kung Magnus - En vacker tid - men svart som korpen och\nbödelns kåpa\nVälkommen till vår tid, medeltiden. Välkommen till Junaköping år 1275.\nLördagsflanerande Jönköpingsbor som stannade till vid hamnplan fann sig plötsligt\n\n\n                                                                                            145"}, {"pdfPage": 147, "printedPage": null, "text": "förflyttade tillbaka i tiden, en tid då Birger Jarl regerade i landet medan sönerna\nMagnus och Valdemar slogs om makten.\n   Detta är en vacker tid; svart som korpar och bödelns kåpa, vit som solens sken och\njungfruns hår, röd som blod, men också som kärleken, förklarade berättaren, tillika\nmanusförfattaren och regissören Leif Olsson. Det var sällskapet Par Bricole och teater-\nsällskapet Orbis Gycklare från Skara som bjöd på denna Friluftsföreställning, framförd\npå hamnplans terrass och med åskådarna på andra sidan hamnkanalen. Under en\ntimmes skådespel uppmärksammade man Magnus Ladulås genom ett historiskt\nskådespel om kampen om kungamakten och hur Jönköping bildades. Här fanns förstås\nkungarna Magnus (Anders Ruberg) och Valdemar (Sune Winald), deras bror biskop\nBengt i Skara (Dan Ekström), Magnus gemål drottning Helvig från Holstein (Ylwa\nLauren), Valdemars gemål drottning Sofia från Danmark, jungfrun Rebecka (Marie\nWinald), hovdamer, munkar, gycklare, bödel, lieman, dansare och eldslukare.\n\nLandsfadern död\nOch medan publiken fick se hur livet var för de 800 invånarna i det som senare skulle\nbli Junaköping, förde berättaren Leif Olsson handlingen framåt.\n- Folket sörjer. Vår store landsfader har gått bort. Hans svåraste kamp var inte yttre\nfiender, utan att skapa fred mellan sönerna.\n- Valdemar blev kung, men han var ingen stor man. Han älskade kvinnor mer än att\nsköta riket och affärerna. Och åskådarna får följa det kärleksdrama som börjar med\nkung Valdemars eriksgata till Junaköping och som sedan skulle bli hans fall.\nHustrun, drottning Sofia, får besök av sin syster Jutta, nunna i ett danskt kloster. Hon\nblir förstås kär i Valdemar, och de båda reser till Norge medan drottning Sofia blir\nlämnad kvar ensam. Åtta månader senare återvänder han till Junaköping, sedan hans\nhovmän lämnat honom på grund av sveket mot hustrun. Jutta födde en son och gömde\nsig i kloster.\n\nSju med barn\n- På vägen till Norge hade han också gjort sju andra kvinnor med barn, förklarar berät-\ntaren, och det gick ett sus genom publiken. För Valdemar är det bara att hoppas på\nförlåtelse från sin bror, biskop Bengt. Men icke. Han mister den kungliga kronan och\nblir bannlyst av påven. Ett års bortgörning i Rom är straffet, och färden anträds. För-\nnedrad och bannlyst lämnar han landet, alltmedan Junaköping gycklare ställer till med\nfest. Men Valdemar skulle förstås återkomma, och vi får följa historien allt ifrån slaget\nmot brodern Magnus vid Hova i Västergötland , tills Magnus övertar kungatronen och\nkommer på Eriksgata till Junaköping. För kung Magnus är det sedan dags att tacka\ninvånarna i Junaköping för stödet han fått, genom att ge marknadsprivilegier, utfärdade\npå Alsnö hus i Mälaren, 18 maj 1284.\n\n\n\n\n146"}, {"pdfPage": 148, "printedPage": null, "text": "Övergiven\nOch hur gick det för Valdemar? Ensam och övergiven blev krogen och krogslinkorna\nhans hem, men han fick sitt arv och kunde sitta på fädernegården. Han överlevde sin\nbror Magnus, som gjorde sitt sista besök i Junaköping sedan pesten härjat, och som tog\nfarväl av sina trogna undersåtar innan det var dags att åka hem till Visingsö och sluta\nsina dagar år 1290\".\nMikael Bergström (text)\nÅke Karlsson (foto)\nText och foto med benäget tillstånd av Jönköpings-Posten\n\n\nOperamaskeradbalen den 7 november 1992\nOperamaskeradbalen, som hölls i Spegelsalen lördagen den 7 november 1992, var en\nfantastisk fest. Kanske en av de bästa och mest uppskattade som någonsin hållits inom\nJönköpings Par Bricole. Det är naturligtvis svårt att jämföra denna fest med andra tidi-\ngare fester av liknade slag. Operamaskeradbalen blev en strålande fest och en mycket\nstor framgång för alla agerande och för Jönköpings Par Bricole.\n   Grunden till framgången utgjorde sannolikt det enastående fina samarbete, som ut-\nvecklats mellan de skilda Talanggrupperna under förberedelsearbetet.\n   För att göra balen extra spännande för baldeltagarna engagerades Broder Felix\nGrönfeldt från Göta Par Bricole i rollen som kung Gustaf III. Broder Benno Holm fick\nuppdraget att spela Anckarström, vilket han genomförde med den äran. Anckarström\n(Holm) lyckades i sitt uppsåt att skjuta kungen men hade själv kunnat bli ett offer denna\nkväll. När pistolen avlossades i Röda Salongen, bar det sig inte bättre, än att Anckarströms\nmantel fattade eld. Det blev således dramatiskt på flera sätt när Gustaf III än en gång\nsköts 200 år efter det första skottet.\n   Jönköpings-Posten berömde översvallande århundradets spektakel i Jönköping. Det\nStyrande Guvernementet under ledning av Jan-Erik Berggren beslöt att Gustaf III minnes-\nmedalj, som utdelades till samtliga deltagare, skulle räknas som en officiell medalj\ninom Jönköpings Par Bricole. Evenemanget fick god förhandspublicitet genom den\nartikel journalisten Yvonne Teiffel skrev några dagar före premiären.\n\n(Saxat direkt från Jönköpings-Posten.)\n”Maskeradbal på Stora Hotellet - Gustav III skjuts igen i Jönköping\nHur gick det egentligen till när kung Gustav III på maskeradbalen i Operahuset i Stock-\nholm den 16 mars 1792 fick en kula i ryggen? Ja, det får vi veta då Det Lysande Säll-\nskapet Par Bricole i Jönköping den 7 november flyttar oss 200 år tillbaka i tiden och\ninbjuder till - maskeradbal! Huvudperson är densamme som då - kung Gustav själv, de\nsköna konsternas beskyddare, en av den svenska historiens mest omdiskuterade ge-\nstalter.\n\n                                                                                        147"}, {"pdfPage": 149, "printedPage": null, "text": "Detta utsökta konstverk gjorde Peter Gadh av en minnesvärd händelse, då Kung Gustaf III åter\ngick på maskeradbal och denna gång i Jönköping!\n\n\n   Vi förflyttar oss från Operahuset i Stockholm till spegelsalen på Stora Hotellet i\nJönköping. Nu var det längesedan det anordnades maskeradbaler här, men det har\nfaktiskt förekommit. - Det var kring 1930-talet, berättar Jan-Erik Berggren, Styrande\nMästare i Jönköpings Par Bricole och därmed logens högste. Och nu ska det alltså ske\nigen. Stort spektakel lär det bli, i talangfull bricollistisk anda givetvis och så över-\ndådigt, att Jönköpingsborna inte i första taget skall glömma denna dramatiska kväll, då\nåterigen det ödesdigra Skottet ska avlossas, det skott som tretton dagar senare förpassade\nkonungen bort från detta livet.\n\nPå Gustavs tid\nGustav III regerade under åren 1746-92. Han var kulturkungen framför alla andra, och\ninstiftare av bland annat både Svenska Akademin, Vitterhetsakademin, Musikaliska\nAkademin, och Kungliga Teatern. Det var under hans tid - 1779 - som Par Bricole\ninstiftades i Stockholm. Exakt 100 år senare instiftades logen i Jönköping, en av sam-\n\n148"}, {"pdfPage": 150, "printedPage": null, "text": "manlagt sex filialer ute i landet. Det är kungen som är sällskapets högste beskyddare,\nmen centralfiguren har alltid varit dess första skald, Carl Michael Bellman, som förstås\nockså kommer att vara med i Jönköping den 7 november om aftonen.\n\nInga kvinnor\nI Par Bricole i Jönköping finns 600 medlemmar. De är alla män. Kvinnor äger inte\ntillträde. Här höjs väl en och annan bägare och en av det vittra sällskapets uppgifter, får\nvi veta, är ”att med muntra och anständiga tidsfördriv lindra livets besvärligheter”. -\nSällskapet har en kulturbefrämjande uppgift, understryker Jan-Erik Berggren. Vi är\nindelade i de fyra talanggrupperna - talet, sången, musiken och teatern. Vi gissar att det\nges prov på samtliga dessa talanger den 7 november då den lysande och givetvis tidsty-\npiska maskeradbalen i närvaro av bland andra landshövdingen äger rum i Jönköping.\nRedan utanför Stora Hotellet lär det hända spännande saker denna kväll, då Jönköping\nväntar på kung Gustav III:s ankomst och - för så var det väl ändå? - de sammansvurna\nmed kapten Anckarström i spetsen konspirerar för att röja kungen ur vägen och om-\nstörta hela regeringen.\n\nKonstnärligt minne\nEn lång rad kända män är med-\nlemmar i Par Bricole i Jönköping.\nEn av dem är konstnären Peter\nGadh, scenograf och även den\nsom gjort det grafiska blad som i\nexklusiv upplaga försäljs, som ett\nminne av denna mycket speciella\nkväll då det blir Operamaskerad-\nbal på Stora Hotellet. En kväll då\ndet ska vila över Jönköping ett\nskimmer som över Gustavs dagar.\n   Den 9 november 1992 recen-\nserade Jönköpings-Posten Opera-\nmaskeradbalen som följer:\n\n”Ett strålande spektakel\nInte sedan 30-talet har väl Jön-\nköping fått uppleva en sådan fest,\nett sådant strålande spektakel som\ndet som timade på Stora Hotellet\npå lördagen. Klockan har skru-        Jönköpings Postens utsända Jan-Erik Ejenstam och Yvonne\nvats 200 år tillbaka i tiden och vi   Teiffel var på plats redan innan det small.\nbefinner oss på maskeradbal på        Foto: Jan-Erik Ejenstam, JP.\n\n\n                                                                                         149"}, {"pdfPage": 151, "printedPage": null, "text": "Kungliga Operan i Stockholm. Det är den 16 mars om aftonen, år 1792.\n    ”Je vous connais bien, beau masque.” En man klädd i svart domino och svarta stövlar\nhar just hälsat på konungen. I bröstfickan bär han en pistol, vars hane redan är spänd.\nOch alla är där. Kung Gustaf och hans adjutant Gustaf Armfeldt, Jacob Johan\nAnckarström, Claes Horn, A L Ribbing, sekreteraren i Kungliga Nummerlotteriet Carl\nMichael Bellman, kungens befallningshavare uti Jönköpings län Gösta Gunnarsson och\ntill och med Ulla Winblad, som smugit sig förbi slinkor och slödder vid operahusets\nentré, för att ansluta sig till det lysande sällskapet Par Bricole ifrån Jönköping.\n\nPå vitpudrad kind\nÖver 200 personer har intagit sina platser i den vackra Spegelsalen. De väldiga kristall-\nkronorna tindrar i kapp med ordnar och medaljer. Pudrade peruker och stångpiskor\nguppar på medborgarnas förnäma huvuden, spetskråsen dallrar, korkskruvslockar gungar,\nmoucher lyser på vitpudrade kinder och damernas vida kjolar böljar mot ekparketten.\nDet högst upplysta majestätet kung Gustaf III, de sköna konsternas beskyddare, har\n\n\n\n\nTiggare, slinkor och slödder möter D.St.M Anders Hugoson och andra vid entrén till Stora\nHotellet. Olika falla ödets lotter.\n\n\n150"}, {"pdfPage": 152, "printedPage": null, "text": "Galamåltid i Spegelsalen. Foto: Jan-Erik Ejenstam, JP.\n\nklätt sig i en jacka av melerad grå sil-kestrikå och bär ett brett skärp om livet. På hans\nbröst glittrar en broderad serafimerkraschan. Han ler allra nådigast. Precis som det\nlysande sällskapet Par Bricoles bröder anser konungen, att man med muntra och an-\nständiga tidsfördriv högst väsentligt bör kunna lindra livets besvärligheter.\n\n\nMed pimpinella\nOrkestern spelar upp och kungen tråder menuetten med sin befallningshavares hustru\nRigmor Gunnarsson som synes helt oförberedd, men icke alls obegåvad i den sirliga\n\n                                                                                      151"}, {"pdfPage": 153, "printedPage": null, "text": "Konung Gustaf III (Felix Grönfeldt) tråder menuetten med Konungens troman Gösta Gunnarssons\nkärälskeliga hustru Rigmor. Foto: Jan-Erik Ejenstam, JP.\n\n\n 152"}, {"pdfPage": 154, "printedPage": null, "text": "Jan Fåhraeus är ättling i rakt nedstigande led till Kungamördaren Anckarström. Här klädd i en\nlikadan mask, som hans farfars fars farmors far bar när han sköt Gustaf III.\nFoto: Jan-Erik Ejenstam, JP.\n\n\nfranska sällskapsdansen. På balkongen står Carl Michael Bellman - märkvärdigt lik\nadjunkten Sune Winald - med sin luta. Denne sällskapets centralfigur sjunger så välbe-\nhagligt, den fullkomligt lysande kören under Clas-Olof Lindquists ledning stämmer in\noch snart också den högst förtjusande och begåvade Galina Korsel, hitsänd som ambas-\nsadör från S:t Petersburg av kejsarinnan Katarina II, som på detta sätt vill visa den\nsvenske kungen sin ynnest. Därpå är det dags att intaga den utsökta måltiden, kompo-\nnerad efter fransk modell. På menyn står sju rätter. Vin med pimpinella och tilltugg,\ngrön ärtpurésoppa med pepparrotsgrädde, laxpastej med örtsås, melonsorbet, rådjurs-\nstek med brysselkål och inkokta päron med kastanjepuré och efter detta illuminerad\napelsinglass och café avec med chokladmedaljong.\n\nKärleksbiljett\nOch surpriserna duggar tätt. En kärleksbiljett som plötsligt ligger på tallriken (vem var\nbeundraren?), medaljering genom konungens nådiga försorg och det nu välmående\nmajestätet som talar till sina trogna undersåtar. - Vi Gustaf... Då lämnas plötsligt ett\nkonvolut med sigill på hans bord. Konungen läser. - Haha, skrattar han. Man hotar mig\ntill livet. Inget att fästa sig vid. Haha. Så bryter han upp för att klä om sig till maskera-\nden. - Vi ses igen bakom masken, säger kungen och musiken spelar åter upp. Under-\ntecknad Madame med gåspennan ger sig nu också ut i dansen, ledd av bordskavaljeren\n\n\n                                                                                                153"}, {"pdfPage": 155, "printedPage": null, "text": "Konungen är skjuten och måste lämna balen. Sjungande bärare från vänster Ragnar Jonsell,\nGunnar Kitraeus och Ingvar Selse. Foto: Jan-Erik Ejenstam, JP.\n\n\nMats Forsgren, nye vägdirektören, som för henne så galant i valsen. Utefter väggarna\nstryker Anckarström. 205 ansikten döljs bakom sina masker. Några av dem är klädda\nhelt i svart. Det är deras kännetecken. Och då plötsligt! Ett skott ekar genom operans\nsalar!\n\nElden är lös\nElden är lös! Skriker de svartklädda. Stäng dörrarna! Skriker militärchefen. ”Ay, ay! Je\nsuis blessé!” Jag är sårad, skriker konungen och faller till golvet, ack grymma öde, i det\noperahus som han själv några år tidigare låtit bygga. Damerna skriker och svimmar.\nHerrarna jagar fram som yra hönor i operasalen eller står förstenade av chocken. Polis-\nmästare Anders Ruberg synes dock strax ha läget under viss kontroll. ”Hans majestät är\nskjuten,” förkunnar han för det djupt skakade, lysande sällskapet. Skottet har avfyrats\npå nära håll av någon i denna sal.\n\nNya livsandar\nHans majestät konungen bäres så till sitt sovgemak. Livmedikusen Sten Janér tillkallas,\nkungens nära vän, statssekreteraren Elis Schröderheim sjunker förtvivlat ner vid kung-\nens dödsbädd. Medborgarna - nåja, åtminstone de flesta - sörjer redan sin Gustaf. ...\nEller? Vad händer? Stiger inte majestätet strax spänstigt upp från sitt sjukläger förkun-\n\n\n154"}, {"pdfPage": 156, "printedPage": null, "text": "nande att ryktet om vår bortgång är betydligt överdrivet? Jojo, vi som fick vara med\ndenna lysande maskeradkväll i detta lysande, livsnjutande sällskap Par Bricole i Jönkö-\nping, vi vet hur det egentligen gick till när det berömda skottet avlossades på\nOperamaskeradbalen den 16 mars 1792, om aftonen. Alla vi som nu fick sola oss en\nstund i det skimmer som vilade över Gustafs dagar”.\nPå Operamaskeradbal:\nYvonne Teiffel (text)\nJan-Erik Ejenstam (foto)\nText och foto med benäget tillstånd av Jönköpings-Posten\n\n\n\n\n                                                                                   155"}, {"pdfPage": 157, "printedPage": null, "text": "Sällskapets Styrande Mästare under\n125 år\nCarl Lars Svante Friedländer\n1879-1899\n”Omkring Friedländers hela personlighet\nsvävade en nimbus av det glada gustavi-\nanska tidevarvet. Redan hans skönlockiga,\nädelt bildade huvud med drag, vilka tyck-\ntes vara skapade för bronsen eller mar-\nmorn, vittnade om, att han icke var någon\ngenomsnittsmänniska. Hans uppträdande,\npräglat av en viss gammaldags sirlig gran-\ndezza, hans konversation vars verkan för-\nstärktes genom det livligaste minspel och\nsom stundom beledsagades av dramatisk\nhandling, hans gnistrande skämt som på\nsamma gång röjde något av både faun och\ngratie, hans medryckande vältalighet vars\nskala omfattade varje skiftning mellan den\nsaftigaste humor och det djupaste allvar - allt detta gjorde Friedländer till en man\nbetydligt olik den i konventionella former stöpta mängden.” Så beskrevs Carl Friedländer\ni en parentation hållen av Robert Tolft. Carl Friedländer var en av Sällskapets stiftare\noch blev utsedd av Moderlogen att bli Styrande Mästare för den nybildade filiallogen i\nJönköping. Han inträdde i Göta Par Bricole redan 1849 och blev Jubelkommendör til-\nlika RSK vid året för sin avgång. I en dödsruna över Carl Friedländer kunde man läsa\natt ”hans gentlemannalika uppträdande och hans gladlynthet gjorde honom till en gärna\nsedd gäst i det enskilda umgänget”. Ett annat vackert bidrag som belyser denna ”Frid-\nens man” och hans personlighet lämnades i tidningen av en enskild person. Han skri-\nver: ”Vad som allra mest utmärkte honom var ett jämnmod och ett sinneslugn som\naldrig övergick till häftighet, hur illa det än gått för någon av hans underhavande. Bland\nhans arbetare gick den sägen, att detta hans jämna lynne var en frukt kanske ej så mycket\nav medfött anlag som fastmer av självtukt, i det att han i en bitter stund i början av sin\nverksamhet uppställt den livsgrundsatsen att aldrig med ord eller handling förfördela\nen medmänniska. Och den grundsatsen höll han obrottsligt.”\n   Carl Friedländer föddes i Göteborg den 6 juli 1827 där han utbildade sig till affärs-\noch industriman. Han kom till Jönköping 1867 och hans verksamhet i våra bygder\nupptogs i huvudsak av Stensholms pappersbruk och Ebbes bruk. Han förvärvade seder-\n\n156"}, {"pdfPage": 158, "printedPage": null, "text": "mera det senare och drev upp det till ett mycket framgångsrikt bruk. Efter ett par år av\nsjukdom avled Friedländer den 20 september 1902. Han jordfästes i Sofiakyrkan och\nhan ligger begravd på Bäckebols kyrkogård på Hisingen i Göteborg.\n\n\nAnders Bernhard Hay\n1899-1906\n\nNär Carl Friedländer avgick 1899 var det\nförmodligen ganska självklart att Bernhard\nHay, som då var Deputerad Styrande Mäs-\ntare, skulle efterträda honom. Hay var en\nmäktig man med stor pondus. Han var chef\növer den stora Tändsticksfabriken och\ndessutom en mycket ståtlig person. Tor\nAlmén höll parentationen över Bernhard\nHay och talade om honom som en mycket\nbestämd man. Han nämner hans skarpa\nblick, hans sätt, hans distinkta tal. Bern-\nhard Hay var inte en person som man spon-\ntant närmade sig. Han höll människor på\navstånd genom sin stora pondus. Många\nbetecknade honom faktiskt som en despot.\nMan kan kanske förstå detta när man be-\ntänker att han verkade som chef över en\nfabrik med över 2000 arbetare i slutet på\n1800-talet och in i det nya seklet. Bern-\nhard Hay var en framgångsrik företagsledare och krävde förmodligen sträng disciplin\nbåde av sig själv och av andra.\n   Parentatorn talade vidare om Bernhard Hay som en ovanligt ordfast och trofast man\nnär man lärde känna honom. Under den stränga ytan klappade ett varmt hjärta, där det\nfanns förståelse för harmlösa skämt och en viss humor. Det sägs också att han ”under-\nstundom var en vek natur”. Kännetecknande för Bernhard Hays sätt att leda verksam-\nheten i Par Bricole var att han var minutiöst noggrann med repetitioner inför varje grad.\nÄmbetsmän repeterade och Bernhard Hay delade ut noggranna instruktioner. Ceremo-\nnin skulle ske klanderfritt och han gav oftast skriftliga anvisningar som påminde om en\nbefälhavares sätt att leda verksamheten. Han värnade allra mest om vår första pelare\nsom är Ordning. Hans ledning av Sällskapet var ganska dominant men den var också\npräglad av en faderlig vänskap. Bernhard Hay höll gärna ett öga på kommendörernas\nsvagheter. Han ledde Sällskapet med glans och auktoritet. I skriften som gavs ut vid 50\nårsfirande talas det om glansperioden under Bernhard Hays ledning. Han avgick i sep-\ntember 1906 och var då över 70 år gammal.\n\n\n                                                                                     157"}, {"pdfPage": 159, "printedPage": null, "text": "20 år tillbringade Bernhard Hay i styrandekretsen och de sista sju som Styrande\nMästare. Han föddes i Varberg 1835 och avled i Jönköping den 14 mars 1917. Många\nmänniskor var närvarande när hans stoft fördes till den sista vilan på Slottskyrkogården\ni Jönköping. Par Bricoles kör och musik medverkade och på den gravsten som av\nJönköpings stad rests till hans minne finns vårt Sällskaps symbol - Den skinande Lam-\npan inristad i guld.\n\nBror Axel Salomon von Geijer\n1906-1909\nEfter många förhandlingar svarade slutli-\ngen major Bror von Geijer ja till att efter-\nträda den dynamiske tändstickschefen\nBernhard Hay som Styrande Mästare i\nJönköpings Par Bricole. Bror von Geijer\nvar överflyttad från Moderlogen i Stock-\nholm och hade endast varit Jönköpingsbo\ni två år, när han tillträdde sitt höga äm-\nbete. Han ställdes inför en svår uppgift.\nDet var inte lätt att axla företrädarens man-\ntel. Dessutom skar det sig ganska snabbt\nmellan Arbetsgradernas leklynne och\nBror von Geijers allvarliga filosofiska\nläggning. Han såg bricolleriets vackra idé-\nvärld i Riddaregraderna men förstod sig\ninte riktigt på det där med lustigheten och\nskämtet i Ordenslivet. Major von Geijers\ntid som Styrande blev för kort för att man\nska kunna ge rättvisa åt hans talanger. För\ntalanger hade han. Dessutom sådana ta-\nlanger, som vi anser är ovärderliga för en ledare inom bricolleriet. Han var en fängs-\nlande och mycket framstående vältalare. Det omnämns bland annat vid vårt 25 års-\nfirande, då man kan läsa att Bror von Geijer höll ett briljant tal för ”hela det lysande\nbricolleriet”. I jubileumsboken från 1929 berättas det att han var personligen inbjuden\noch att man planerade för att ägna honom en uppriktig tacksamhet för att han ”påtog sig\natt länka Sällskapets öden under en period, vilket kan betecknas som en vågdal efter en\nföregående kulmination av intresse”. Under Bror von Geijers tid skrevs nästan inga\nprotokoll från Gradgivningar och andra sammankomster varför denna tid är en ganska\nokänd tid i vårt Sällskaps historia.\n\n\n\n\n158"}, {"pdfPage": 160, "printedPage": null, "text": "Henrik Wrede\n1909-1917\n\nHenrik Wrede var i mångt och mycket lik\nvår förste Styrande Mästare i sättet att vara.\nFriedländer har karaktäriserats som sirlig.\nHay var ordningens man och Wredes karak-\ntär omnämns som ”älskvärd”. Det sägs också\natt båda ägde ”magnificens, lätthet att char-\nmera och attisk sälta i talet”. När Henrik\nWrede tillträdde som Styrande Mästare led\nvårt Sällskap av sviterna från den nyss\nnämnda vågdalen. Under hans tid växte det\nupp en ny anda i Sällskapet, vilken nästan\nåteruppväckte de flydda dagarnas glans. För-\nsta världskriget pågick under denna tid och\ndet lade naturligtvis en viss sordin på verk-\nsamheten. Friherre Wrede ägde alla förut-\nsättningar. Han var Aristokrat och ämbets-\nman men också den ödmjuke Bricollisten.\nHan fann sig väl till rätta i sitt Guvernement\noch hade förmodligen stort stöd från Brö-                         0909 ー 9997•\n\nderna Carl Gustaf Roos af Hjelmsäter och\nHenrik Karnell. Henrik Wredes talekonst var\njuridiskt klar, kanske ibland i avsaknad av Bacchanaliska inslag, men var inte desto\nmindre kvick och satirisk. Detta gjorde att man med stort nöje lyssnade till honom.\n    Henrik Wrede var gift med Bernhard Hays dotter och han var Styrande Mästare ett år\nlängre än sin svärfar. Han avgick 1917 efter åtta år vid rodret. Han recipierades 1896\noch upphöjdes redan 1913 till Riddare av Svarta Korset. Henrik Wrede var hovrättsråd\nvid Göta Hovrätt. Hans gestalt bar den tidens yttre pondus. Han var dessutom en mycket\nälskvärd person som uppskattades både inom och utom vårt Sällskap. Henrik Wrede\ntillhörde adeln, men det var inte ovanligt att man talade om ”hjärtats adelskap” när man\ntalade om Henrik Wrede.\n\n\nErnst Leonard Hartmann\n1917-1928\n\nI raden av Styrande Mästare i vår historia intar Ernst Hartmann ett av de förnämsta\nrummen. Han intar det bland annat på grund av sin ”personliga värme, sitt goda hjärta\noch sitt friska och rättframma sinnelag av vilkas håvor han gav brödraskapet med fulla\nhänder”. Citatet är hämtat ur jubileumsboken Jönköpings Par Bricole 50 år. Under krigs-\n\n\n                                                                                    159"}, {"pdfPage": 161, "printedPage": null, "text": "åren var stämningen ganska tryckt men man\n                                            kan ana att bricolleriet betydde mycket för\n                                            tryggheten och gemenskapen i en tid av oro.\n                                            Ernst Hartmann fanns med i den tiden och\n                                            ledde dessutom Sällskapet under Sveriges\n                                            ”lyckliga 20-tal”. Man kan förmoda att sam-\n                                            hällets positiva synsätt och glädje också präg-\n                                            lade det bricollistiska arbetet under denna tid.\n                                            Han var en varm och innerlig människa. Man\n                                            ska också komma ihåg att samhället var an-\n                                            norlunda under von Geijers tid i början av\n                                            1900-talet än det var under det ”lyckliga” 20-\n                                            talet. Detta skall inte förta den insats man till-\n                                            skriver Ernst Hartmann som Styrande Mäs-\n                                            tare. Han var den äkta Bricollisten. Hela hans\n                                            natur låg för det glansfulla och festliga. Han\n                                            älskade att vara glad bland de glada och han\n                                            tyckte om ett gott skämt och en vacker sång.\n                                            Men Ernst Hartmann var också bärare av de\negenskaper som kännetecknar det Bacchanaliska Ljuset. Sinnets och själens ljus, det\nmilda sken som strålar ut från vårt Sällskaps innersta mening och grundidé. Skenet\nkring den pelare som vi benämner förtrolighet och som kännetecknas av vänskap och\nbroderlighet. Ernst Hartmann ville inte ensam vara glad, han ville att alla skulle vara\nglada.\n   Ernst Hartmann var också noga med att dokumentera vår historia. Han gav oss de\nförsta Gyllene Böckerna. Han letade i Sällskapets arkiv och sammanställde protokoll\noch tal, vilka hade hållits i vårt Sällskap från begynnelsen. Tack vare Ernst Hartmann\nfinns två vackra maskinskrivna volymer av De Gyllene Böckerna. Nästan på varje blad\ni dessa Gyllene Böcker ser man spår av hans granskande och ordningsamma hand.\n   Ernst Hartmann föddes i Stockholm den 4 december 1864. Vid jubileet 1929 var det\ntänkt att han skulle leda festligheterna på våren, men han avled redan den 12 januari\n1929 och fick aldrig uppleva det han hade längtat efter och planerat så flitigt för. På\nhans krans från Par Bricole kunde man läsa ”Det du i vänskap gav, ditt varma och\ntrofasta hjärta, länge skall leva bland oss, slutet i minnenas famn”.\n\n\nHenrik Valfrid Karnell\n1929-1944\n\nHenrik Karnell recipierades redan 1887 och hade på nära håll följt Sällskapet i dess\nupp- och nedgångar. Han upplevde när vi sprakade av ungdomligt mod och framtidstro.\nHan upphöjdes så sakteliga inom graderna och arbetade som ämbetsman med det mesta.\n\n\n160"}, {"pdfPage": 162, "printedPage": null, "text": "Henrik Karnell hade en lång och genuin skolning\ninom vårt Sällskap. När han tog över efter Ernst\nHartmanns plötsliga död så var han väl förberedd\noch väl förtrogen med bricolleriets alla ämbeten\noch Gradgivningar. Henrik Karnell hade agerat\nsom ceremonimästare, han hade varit teaterdirek-\ntör och riddareprelat. I Guvernementet hade han\nvarit Styrande Kansler innan han blev Deputerad\nStyrande Mästare, så det var ganska naturligt att\nhan gick upp som Styrande Mästare efter Hart-\nmann. Henrik Karnell skrev skämtsamma pjäser,\nhan skrev tal på vers och han tecknade vackra\nparentationer av bortgångna Bröder.\n   Man kan inte beskylla Henrik Karnell för att\nha åkt snålskjuts till sin Mästareroll. Han arbe-\ntade sig långsamt fram till sin position och ägde\nbåde klokskap och kunskap när han tillträdde sitt\nämbete. Dessutom var han en mycket aktad man\noch en framgångsrik företagsledare. I början av 20-talet kan man läsa från ett tal där\nHenrik Karnells namn nämns ”att det i sin nuvarande högsta styrelse äger ett tretal\nmän, vilka icke blott i den allmänna världen äro en prydnad för vårt samhälle, utan\näven inom vår slutna krets i kärlek för Bricolleriets ädla syfte, i nitisk verksamhet för\nderas uppnående, i vänskap för Bröderna och överseende med Kommendörernas svag-\nheter från sitt högsäte förelysa oss alla i de egenskaper, som utgöra grundvalen för vår\nOrdens styrka, för dess ära och glans”.\n   Henrik Karnell föddes i Småland 1865. Han var en hängiven bricollist och en lika\nhängiven bevarare av Jönköpings Stadspark. En medaljong av Henrik Karnell finns\ningjuten i bergväggen när man går stigen upp från Bäckalyckan till Stadsparken. Hen-\nrik Karnell var också en hängiven Frimurare. När han tillträdde som Styrande Mästare\n1929 blev han också Ordförande Mästare i Den Mellersta Pelaren inom Frimurarorden\ni Jönköping.\n\n\nErik Ludvig Gösta Pantzerhielm\n1944-1954\n\nGösta Pantzerhielm (”P-z”) föddes i Stockholm 1884. Han hade inte enbart andligt\nsläktskap med Carl Michael Bellman utan även en antavla där ”den riktiga” Moster\nBarbara (Barbara Klein) var en viktig del av genbanken.\n   P-z var officer och kom till Smålands Artilleriregemente (A 6) som underlöjtnant\n1928. Han avancerade till major och blev 1944 överstelöjtnant. Sedan P-z tagit avsked\nfrån armén tjänstgjorde han som militärassistent på Länsstyrelsen. P-z var mycket in-\n\n\n                                                                                     161"}, {"pdfPage": 163, "printedPage": null, "text": "tresserad av hästar och en framstående ryt-\ntare. Han var aktiv i Jönköpings fältrittklubb\noch även i svensk ridsports centrala styrelse.\n   Inom Par Bricole kom hans utmärkta egen-\nskaper som ledare, administratör och talare\nväl till pass. Han var Riddarceremonimästare\ni hela 20 år 1922-1942 och 1927-1930 tillika\nDirektör för den Bacchanaliska Teatern. 1942\nutnämndes han till Styrande Kansler för att\ntvå år senare installeras som Styrande Mäs-\ntare, vilket ämbete han med oförvanskad ära\nbeklädde i 10 år.\n   P-z var en damernas riddare och det är\ningen tillfällighet att Dam-Bricolleriet inför-\ndes i Jönköpings Par Bricole under hans ”re-\ngeringstid”.\n   P-z arbetade med stort och smått. I vårt arkiv finns ett märkligt intyg, som kan\ntolkas som att officeren bytt sida:\n”Till vederbörande chef Fältpost 61722\nSällskapet Jönköpings Par Bricole får härigenom hemställa att Signalisten 78 Hagelin,\nsom är inkallad till militärtjänstgöring, måtte beviljas tjänstledighet, så att han kan\nmedverka i ett sångspel vid givandet av Sällskapets tredje grad i Jönköping den 7 näst-\nkommande april.\nJönköping den 28 mars 1945\nG. Pantzerhielm\nStyrande Mästare Överstelöjtnant.”\nGösta Pantzerhielm avgick efter 10 år som Styrande Mästare för ett Par Bricole, som\nblomstrade i den optimistiska efterkrigstiden. Han levde vidare i Jönköping och avled\npå Luciadagen 1964.\n\nAnders Graab\n1954 - 1970\n\nAnders Graab hade ansvarsfulla uppgifter i samhället. Han\nvar chef både för Jönköpings Mekaniska Verkstad och för\nDomneåns Kraft AB. Han uppges ha varit en skicklig le-\ndare och tillhörde också stadens ledande män. Sålunda var\nhan under några år Drätselkammarens ordförande.\n  I Par Bricole kunde han koppla av från vardagen. I en\nminnesruna från 1985 skriver Broder Carl Wilhelm\nLothigius ”I Jönköpings Par Bricole lyfte Anders av sig\n\n162"}, {"pdfPage": 164, "printedPage": null, "text": "vardagens arbetsdräkt och klädde sig och sin omgivning till fest. Då glittrade bringan\nav förtjänsternas guld och hjärtat sjöng till alla vänners glädje.”\n   En äldre Broder minns Anders Graab och beskriver honom på följande sätt: ”Då\njag, vid Barbarahögtiden år 1967, inträdde i det Lysande Sällskapet Jönköpings\nPar Bricole var Anders Graab dess Styrande Mästare. Graab var en i alla stycken\nstor man, till växten, i det kalmuckiska livet och inte minst inom Jönköpings Par\nBricole. Vi kände stor respekt för denne man, särskilt som det rådde en klar hierarkisk\nordning inom Sällskapet. Graab ledde kapitlen med stor kraft. Hans anföranden\npräglades av stor klarhet under stundom parad med en glimt av humor som inte alla\nkunde finna.”\n\nCarl Wilhelm Lothigius\n1970 - 1983\n\nCarl Wilhelm Lothigius var son till Länsjägmäs-\ntare Wilhelm Lothigius. Skogsvården och parti-\npolitiken engagerade honom genom hela livet. Han\nblev ledamot i länets Skogsvårdsstyrelse och fick\npå så sätt fullfölja sin fars engagemang i skogs-\noch kursgården Trollebo, som hans far inköpt år\n1920 för Skogsvårdsstyrelsens räkning. Tillsam-\nmans med ett stort antal andra privata sågverksä-\ngare bildade han Sågverkens Biprodukter (SÅBI)\noch blev också SÅBI:s ordförande. Carl Wilhelm\nLothigius var under två längre tidsperioder, med\nett kortare uppehåll, riksdagsman i andra kamma-\nren och senare i den nuvarande enkammarriks-\ndagen.\n   Carl Wilhelm Lothigius var på många sätt som klippt och skuren för bricolleriet.\nHan hade en klar poetisk ådra och ett vackert språk. Han skrev regelbundet krönikor i\ndagspressen där han samtalade om ”livet”, ofta med bilder hämtade från naturen. Han\nvar en sökare, som inte kunde dagtinga med sanningen.\n   Som Styrande Mästare var Carl Wilhelm Lothigius elegant och med en osedvanlig\nkarisma. Han formulerade sig väl i alla sammanhang. Ofta var hans tal humoristiska,\nja roliga, och innehållet alltid intresseväckande.\n\nJan-Erik Berggren\n1983-1993\nJan-Erik Berggren är en i raden av kända skogsmän och viltvårdare, som betytt mycket\nför Jönköpingsbygden och Par Bricole. ”Jeje”, som han själv kallade sig, hade inte bara\nuppgiften att förvalta familjens skogsfastigheter i Haurida i Anebys kommun, utan också\n\n                                                                                   163"}, {"pdfPage": 165, "printedPage": null, "text": "en rad anställningar och uppdrag knutna till skoglig\nverksamhet. Inte minst gjorde han banbrytande in-\nsatser för att utveckla Elmia Mäss AB och interna-\ntionellt kända skogsmässor som Elmia Wood. Att\nha många järn i elden var karaktäristiskt för Jeje.\nUppdragen var många; i kommunen, i tingsrätten i\nEksjö, i hovrätten i Jönköping, i hembygds-\nföreningen, som honorärkonsul för Tyska Förbunds-\nrepubliken och mycket mer.\n   Jan-Erik Berggrens engagemang i Par Bricole var\nlika omfattande som det i den kalmuckiska världen.\nHan kom under åren att inneha en rad olika ämbe-\nten, som han på ett mycket uppskattat sätt förval-\ntade. Detta vittnade inte minst hans medaljtyngda\nfrack om. Jan-Erik Berggrens riddaresköld i Par\nBricole har valspråket ”Ödmjukt leva - ofta le”, vilket beskriver ”Jeje” väl. Hedersman,\ngenerös, vänlig, arbetsam och idérik. Med andra ord en fin kamrat, omtänksam med-\nmänniska och generöst varmhjärtad Bricole-Broder.\n   ”Jeje” engagerade sig också i hela bricolleriets utveckling som ledamot av Den\nBacchanaliska Akademin i Stockholm. Även där fick han utlopp för sina ”teatraliska”\ntalanger med både lättsamma och djupsinniga tal som värderats högt av Bricole-\nBröderna.\n\nAnders Hugoson\n1993-1999\n\nAnders Hugoson är professor vid Hälsohög-\nskolan i Jönköping. Han är uppvuxen i Sunds-\nvall och utbildade sig till tandläkare i Umeå. Efter\nutbildningen fick han tjänst som lärare och spe-\ncialist i parodontologi vid Odontologiska fakul-\nteten i Göteborg, där han disputerade 1970. Han\nkom till Jönköping 1972 och var med och byggde\nupp den Odontologiska Institutionen i Jön-\nköping. Han blev dess chef år 1976. Han tjänst-\ngjorde som tandvårdsdirektör vid Jönköpings\nläns landsting 1996 - 2003.\n   Han ledde under sin tid som Styrande Mäs-\ntare Det Lysande Sällskapet Jönköpings Par\nBricole med lugn och värdighet. Han var saklig\noch utstrålade en norrländsk trygghet. Han var alltid påläst och hans medämbetsmän\nkunde känna sig trygga under hans ledning. Ekonomiredovisningen reformerades,\n\n\n164"}, {"pdfPage": 166, "printedPage": null, "text": "vilket medförde bättre förutsättningar för Sällskapets ekonomi. Anders Hugosons tjänst-\ngöringstid präglades av en långtgående delegering av ansvar och befogenheter inom\ntjänstemannakåren. Detta var en grund för det goda samarbetsklimat, som rådde. Han\nvar en elegant företrädare för vårt Sällskap såväl i den bricollistiska som i den kal-\nmuckiska världen.\n\n\n\nDan Ekström\n1999 -\n\nUniversitetsadjunkt Dan Ekström\ntillträdde som Styrande Mästare 1999.\n\n\n\n\n                                                                                   165"}, {"pdfPage": 167, "printedPage": null, "text": "Sällskapets vedermälen\n\nSällskapet Par Bricoles första medalj hedrar minnet av sångaren Jacob Lundström, som\nförnöjde bröderna med många glada sällskapsvisor. Hans röst prisades mycket av sam-\ntiden och han hedrades 1795 genom att väljas in i Musikaliska Akademien. Ett slagan-\nfall ändade Lundströms liv år 1800 och året därefter, 1801, lät Sällskapets Ordens-\nbröder slå en minnesmedalj över honom, den Lundströmska Medaljen. Ytterligare två\nmedaljer framställdes på 1800-talet, Bellman-medaljen och Sällskapets förnämsta ut-\nmärkelse Westerstrandska Medaljen, som båda instiftades år 1859. Sällskapets medalj-\nhistoria sträcker sig visserligen från 1801, men Sällskapets medaljtraditioner är i övrigt\nen ganska modern företeelse, vars utveckling tog fart på 1970-80 talet för att kulminera\nkring sekelskiftet. Numera förs diskussioner där man ifrågasätter om antalet medaljer\nstämmer överens med det vi kallar Måttlighet och som är en av våra grundpelare.\n\nJönköpings Par Bricoles första vedermälen präglades av allt att döma år 1917, Jön-\nköpings Par Bricoles Förtjänstkors samt Eklöfskransen. I våra matriklar angavs Förtjänst-\nkorset som vårt förnämsta tecken fram till år 1979, alltså under en tid av 62 år. År 1979,\nåret för 100 års-jubiléet, placerades emellertid i stället Eklöfskransen överst på stegen.\nOrsaken till förändringen kan inte utläsas i något protokoll. Efter 100-årsjubiléet 1979\ngjordes ytterligare en förändring; i matrikeln för 1980-1981 lyftes även den nya\nSekularmedaljen upp och placerades över Förtjänstkorset. Vid Stora Rådets möte år\n2000 presenterade De Styrande ett förslag om att placera Förtjänstkorset högre upp på\nstegen. Stora Rådet fastställde år 2002 den ordning, som numera gäller.\n\nEklövskransen\nInstiftad år 1917\n\n                            Jönköpings Par Bricoles förnämsta medalj, Eklöfskransen\n                            har utdelats till 13 Bröder under vår 125-åriga historia. Den\n                            förste som erhöll Eklöfskransen 1917, var musikdirektör\n                            Josef A Jacobsson. De senaste i raden är Riddareprelaten\n                            Tage Löf 1953, Körledaren Calle Carlsson 1954, Gustaf\n                            Lorentz 1954, D.St.M Sixten Arensten 1970, Koralintendent\n                            Hugo Ramsten 1980, St.K Gerhard Mattus 1993, StM Jan-\n                            Erik Berggren 1995 och Riddareprelaten Per-Axel Jonzon\n                            2000. Från dess statuter finns följande text, som läses vid\n                            utdelandet av Eklöfskransen: ”Varhelst ett tempel bygges åt\n                            Bacchus, forntidens Gud för lekar och nöjen, där reses ock\n                            altaren åt skaldekonstens, talekonstens, musikens och\n\n\n166"}, {"pdfPage": 168, "printedPage": null, "text": "dramatikens gudinnor. Det Bacchanaliska ljuset kommer aldrig till sin fulla rätt, om det\nicke blandas med skenet från offerelden på dessa Gudinnors altaren. När vi Bacchi barn\nsöka vila i vänskapens famn efter dagens vedermödor och därigenom hämta veder-\nkvickelse efter trägen id, så blir denna vila och vederkvickelse aldrig fullständig, om vi\ndärvid ej få njuta av de håvor Gudinnorna älska att skänka oss genom dem, som äro\nderas lärjungar och skyddslingar. Rätt hylla vi Gudinnorna, då vi hedra deras\nskyddslingar”. Eklöfskransen ges endast till den som äger samtliga Bröders högsta akt-\nning.\n\n\n\nFörtjänstkorset (JFK)\nInstiftat år 1917\n\nJönköpings Par Bricoles Förtjänstkors (som till utseendet\nliknar 25-årskorset,som har vita armar och röd mittglob) har\nröda armar och vit mittglob. Det bäres på höger sida av bröstet\noch tilldelas den Broder, som under minst 15 år tillhört Säll-\nskapet och under denna tid antingen tillhört det Styrande\nGuvernementet under 5 år eller varit Riddareofficiant under\n5 år. Dock äga de Styrande sig förbehållet att avkorta denna\ntid och utdela Förtjänstkorset till den Broder, som på ett syn-\nnerligen förtjänstfullt sätt skött sitt ämbete och därigenom\nbidragit till såväl Brödernas trevnad som Sällskapets till-\nväxt och förkovran.\n\n\n\n\nSekularmedaljen (JSM)\nInstiftad år 1979\n\nSekularmedaljen instiftades år 1979 till minne av Jönköpings\nPar Bricoles 100-årsjubileum. Sekularmedaljen kan tillde-\nlas den Broder, som gjort sig särskilt förtjänt därav genom\nförtjänstfulla arbetsinsatser till Sällskapets fromma och för-\nkovran. Sekularmedaljen utdelas dessutom till Styrande från\nandra loger, samt besökare som gjort sig synnerligen för-\ntjänta.\n\n\n\n\n                                                                                      167"}, {"pdfPage": 169, "printedPage": null, "text": "Jan-Erik Berggrens medalj (JJEB)\n      Instiftad år 2001\n\n      I vårt Sällskap finns det ett antal medaljer som framtagits\n      för att pryda Bröder som gjort sig ”förtjänta”. Det heter ofta\n      ”för lyskraft” eller för ”synnerligen administrativ gärning”\n      och ”för synnerlig talangfullhet”. JJEB medaljen är framta-\n      gen som en trohetsmedalj och kan bara delas ut till förtjänt\n      och trogen Broder inom Jönköpings Par Bricole som visat\n      nit, trohet och bricollistiskt sinnelag i enlighet med Styrande\n      Mästaren (1983-1993) Jan-Erik Berggrens valspråk, som\n      finns inristat på hans Sköldemärke: ”Ödmjukt leva - Ofta\n      le”.\n\n      Gerhard Mattus medalj (JGM)\n      Instiftad år 1996\n\n      Gerhard Mattus var Styrande Kansler under åren 1983-1993.\n      När Mattus avled 1996 beslöts ganska omgående att hedra\n      hans minne med ett vedermäle. Det blev ganska stor diskus-\n      sion om Jönköpings Par Bricole skulle porträttera Gerhard\n      Mattus på medaljen och därmed framställa det första ansik-\n      tet på en medalj. Det blev istället Gerhard Mattus karakte-\n      ristiska initialer, som fick pryda ett mycket vackert veder-\n      mäle. Medaljen kan utdelas till talanger, som var och en\n      inom sitt område, gjort betydande och högt värderade insat-\n      ser för Jönköpings Par Bricole. Den ska utdelas sparsamt\n      och i statuterna har man t o m uppgivit antalet med en maxi-\n      mering på tre exemplar per år.\n\n      Jönköpings förtjänsttecken (JFT)\n      Instiftad år 1969\n      Förtjänsttecknet har formen av en lagerkrans som i sig inne-\n      sluter Aladdins lampa. Lagern var i forntiden helgad åt gu-\n      den Apollon - Skaldekonstens, Tonkonstens och Sångens\n      Gud. Tecknet kan föräras Bröder från Moderloge och Syster-\n      loger som ett synbart bevis för vår glädje över ett uppskattat\n      besök eller också såsom en honnör vid eget besök i främ-\n      mande loge. Lagerkransen är hämtad från Jönköpings\n      Spårvägars logotype. Förtjänsttecknet ska bäras på frack-\n      ens vänstra sida strax ovanför frackfickan.\n\n168"}, {"pdfPage": 170, "printedPage": null, "text": "Tack och Lov (silver) (ToLs)\nInstiftades år 1999\n\n\nTack och lov (silver) är den medalj som delas ut flitigast.\nTack och lov tillkom för att Sällskapet skall kunna vara\ngeneröst med ett synligt bevis på uppskattning.\n\n\n\n\nTack och Lov (brons) (ToLb)\nInstiftades år 1988\n\nTack och lov (brons) delades i början ut till Barbaratalaren.\nSå småningom har det blivit svårt att kontrollera vem som\nhar fått Tack och Lov medalj. Det är inte ovanligt att Bröder\nhar fått både två eller flera. För tack och lov kan man ju\ntycka att en insats är bra både två och flera gånger.\n\n\n\n\n                                                                169"}, {"pdfPage": 171, "printedPage": null, "text": "Tabula Gratulatoria\nABRAHAMSSON         CHAIB               GREFBÄCK\nLENNART             MOHAMED             GÖRAN\n\nAHLBERG             CLAESSON            GÖPERT\nJOHAN               MARTIN              CLAS\n\nAHLIN               CLAESSON-ÅKERBLAD   HAGLUND\nSVEN-ROBERT         CLAES               ERIC\n\nANDERSSON           DAHLGREN            HANSSON\nBERTIL I.           GUNNAR              CLAES\n\nANDERSSON           DAHLQVIST           HANSSON\nJAN-ERIC            BENGT               TOMAS\n\nARVIDSSON           EBBESSON            HEDLUND\nTOMAS               SVEN                TORSTEN\n\nBENÉR               EK                  HELKIMO\nLEON                SIGVARD             MARTTI\n\nBENÉR               EKENBERG            HELLMAN\nMATIAS              ROLAND              KENNETH\n\nBERGMAN             EKSTRÖM             HERMANSSON\nBENGT               DAN                 STEN\n\nBERNTSSON           ELMÉR               HESSLER\nOLA                 GÖRAN               ÅKE\n\nBJÖRKLUND           ENANDER             HOLM\nOLOF                KARL-GÖRAN          ÖRJAN\n\nBOLL                ERIKSSON            HOLMBERG\nLARS                MATS                STEFAN\n\nBOMAN               FJAESTAD            HUGOSON\nINGEMAR             BO                  ANDERS\n\nBORÅS PAR BRICOLE   FORSBERG            ISAKSSON\n                    JOHAN               ROLAND\nBRANDES\nPER                 FRANKE              JOHANSSON\n                    PER-GUNNAR          BENGT I.\nBRÄNNSTRÖM\nSIGVARD             FRANSSON            JOHANSSON\n                    JONAS               HANS\nCARLÉN\nTHOMAS              FÅHRAEUS            JOHANSSON\n                    JAN                 PER-ANDERS\nCARLSTEIN\nOLA                 GRAHNQVIST          JOHANSSON\n                    HELGE               ÖSTEN\n\n\n\n170"}, {"pdfPage": 172, "printedPage": null, "text": "JONSELL          LINDELL           NORRSELL\nRAGNAR           ANDERS            NILS\n\nJÖNSSON          LINDÉN            NÄTT\nLARS             BJÖRN             BROR\n\nKALLINGS         LINDER            OLSSON\nPEROLOF          TOMMIE            KJELL\n\nKARLSSON         LINDQUIST         OSCARSSON\nGERT             BERNT             LARS\n\nKISELL           LINDQVIST         PALMÉ JOHNSSON\nHÅKAN            CLAS-OLOF         BERTIL\n\nKLINGBERG        LUNDIN            PALMQVIST\nSTEFAN           CHRISTER BOSSON   TOMMY\n\nKLINGENSTIERNA   LUNDQVIST         PALMQVIST\nMAGNUS           ALF               TORE\n\nKOCH             LÖF               PEROLAINEN\nGÖRAN            PER-ÅKE           ALLAN\n\nKVINT            LÖFBERG           PETERSSON\nSVEN             LARS-GUNNAR       GÖRAN\n\nKÄLL             LÖFSTEDT          PRAHL\nKENT             LARS              HÅKAN\n\nLAGERLUND        LÖWINGER          QVARFORDT\nPER              UNO               MATS\n\nLARSSON          MALMVALL          RUNSTRÖM\nINGVAR           PÄR               GERHARD\n\nLARSSON          MARKLUND          RYDÉEN\nJOHAN            INGVAR            JAN\n\nLARSSON          MEIJER            SANDBERG\nROLF             TORE E.           STELLAN\n\nLARSSON          MELANDER          SANDELL\nULF              GÖRAN             SVEN\n\nLEMAN            MILLER            SANDWALL\nTORSTEN          SVEN-OLOF         JAKOB\n\nLETTERFORS       MÅNSSON           SCHYBERG\nIVAN             ULF               TAGE\n\nLILJEGRAHN       MÖLNE             SEGERBERG\nJOHAN            LENNART           ALLAN\n\nLILJEGRAHN       MÖLSTAD           SJÖBERG\nLARS-ERIC        NILS              PER-OLOF\n\nLINDBLOM         NILSSON           SJÖSTRÖM\nBENGT            STEN              PETER\n\n\n                                                    171"}, {"pdfPage": 173, "printedPage": null, "text": "SKAFVENSTEDT   WARÉN\nBENGT          HANS\n\nSKOGLUND       WENNBERG\nSTIG           HANS\n\nSTENBERG       WESSMAN\nLARS           BERNO\n\nSTENBÄCKEN     WETTÉUS\nGÖRAN          LARS-OLOF\n\nSTENVALL       VON SIVERS\nROBERT         CLAES\n\nSTRANDHEIM     ÅKERBERG\nGÖRAN          LARS-GÖRAN\n\nSTRIDH         ÅKERSKOG\nLENNART        GUNNAR\n\nSUNDBERG       ÅSTRÖM\nANDERS         LENNART\n\nSUNDQVIST      ÖBERG\nCHARLES        TOMMY\n\nSVENSSON\nKJELL-ÅKE\n\nSVENSSON\nSÖREN\n\nSZEPESVARI\nGREGER\n\nSÄFVESTAD\nVIKAR\n\nTHOR\nLEIF\n\nTHORFINN\nARNE\n\nTIMMAN\nKLAUS\n\nTRANESJÖ\nLENNART\n\nWAHLQUIST\nCHRISTOPHER\n\nWAHLQUIST\nRUTGER\n\nWALLIN\nALF\n\n\n172"}, {"pdfPage": 174, "printedPage": null, "text": "", "ocrText": "", "ocrSegments": [""], "autoTextLayer": "original", "machineAssessment": {"confidence": 0.0, "needsReview": true, "automaticSplit": false, "engine": "Tesseract 5.5.3; LSTM; psm 3", "version": "batch-v2", "sourceSha256": "552b25917ca2695102397ad4b17ca210f8f72da5c21dd9fafa57c486d4bb1df1", "modelHashes": {"Fraktur": "29a867a25f1b00a5e9827356582515619d5102688bc1d14015789c78941116ee", "swe": "360303308aa5d4a912ac3b3637691152b7532d9bd6e960639db1affb83db7ea9"}, "languages": ["swe"], "selection": "confidence-and-coverage-heuristic; not proofreading", "createdAt": "2026-10-05T14:09:58.466992+00:00", "statisticsParser": "tsv-quote-none-v1; prior row counts checked"}}]}
